export default [{"id":165,"question":"هل على أهل جدة طواف وداع؟ وما الدليل؟","title":"هل يلزم أهل جدة طواف الوداع؟","answer":"الجواب: نعم؛ لأنَّهم ليسوا من أهل الحرم، وليسوا في حكم أهل الحرم، والنبي عليه الصلاة والسلام يقول: لا يَنْفِرَنَّ أحدٌ منكم حتى يكون آخر عهده بالبيت رواه مسلمٌ، ويقول ابنُ عباسٍ: \"أمر الناس أن يكون آخر عهدهم بالبيت، إلَّا أنه خفَّف عن المرأة الحائض\".\nفأهل جدة وأهل الطائف ليسوا من أهل مكة، ليسوا من أهل الحرم، فإذا أرادوا النَّفير من الحج فعليهم الوداع. أما العمرة فأمرها أوسع وأسهل، إن ودَّعوا فهو أحسن، وإن لم يُودعوا فالصواب أنه لا يجب الوداع في العمرة، ولكنه يجب في الحج على الصحيح.","link":"https://binbaz.org.sa/fatwas/3703/هل-يلزم-اهل-جدة-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0159.mp3","categories":["الطواف بالبيت"]},{"id":210,"question":"شيخنا الفاضل، ما تحية المسجد الحرام؟ وهل تلزم إن كانت الطوافَ عند كل دخولٍ للمسجد؟","title":"هل يجزئ الطواف عن تحية المسجد الحرام؟","answer":"الجواب: الطواف هو التَّحية إذا تيسر، إذا تيسر الطوافُ فهو تحية المسجد، ومعه الركعتان -ركعتا الطواف- فإنه متى طاف شُرع له ركعتا الطواف، وإذا لم يُرِد الطَّواف أو لم يتيسر الطواف إذا دخل صلَّى ركعتين -ركعتي التحية- كسائر المساجد. فليس الطوافُ واجبًا كلما دخلت، الطواف الواجب هو طواف العمرة وطواف الحج، وهو طواف الإفاضة وطواف الوداع، ثلاثة أطواف هي الواجبة: طواف العمرة أول ما تقدم، وطواف الإفاضة في الحجِّ بعد النزول من عرفات، بعد نصف الليل من ليلة النحر، والطواف الثالث طواف الوداع عند الخروج من مكة، هذه أنواع الطواف الواجبة، وما سواها نفلٌ، وطواف القدوم على الصَّحيح نفلٌ، وهكذا بقية الأطواف كلها نافلة.\nفإذا دخلت المسجد الحرام وتيسر لك الطوافُ فهذه نعمة عظيمة، وهو تحية المسجد، وتُصلي بعده ركعتين -ركعتي الطواف المعروفة- ولا سيَّما في حقِّ الغريب، فإنه ينبغي له أن يستكثر من الطواف؛ لأنه مسافرٌ ليس بمُقيم عنده، فإذا لم يتيسر الطوافُ لكسلٍ أو زحمةٍ أو غير هذا؛ فإنه يُصلي ركعتين، والحمد لله، ويجلس.","link":"https://binbaz.org.sa/fatwas/3989/هل-يجزى-الطواف-عن-تحية-المسجد-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0217.mp3","categories":["الطواف بالبيت"]},{"id":377,"question":"لو طاف ودخل مع الحِجْر، وصار جزءًا من الحِجْر على يمينه، والكعبة على يساره، دخل من بابٍ وخرج من بابٍ في الطواف، وهو محرم، يعني: طواف عمرة؟","title":"ما حكم الطواف من داخل الحِجْر؟","answer":"الجواب: هذا لا يُجزئ، لا بدّ من الطواف من وراء الحِجْر؛ لأنَّ الحِجْر معظمه من البيت، فلا بدّ أن يكون الطائفون من ورائه، فمَن طاف من داخل الحِجْر لم يُجزئه الشوط، لا بدّ أن يأتي بشوطٍ بدله، وإن كان شوطين لا بدّ من شوطين، وهكذا حتى يُكمل.","link":"https://binbaz.org.sa/fatwas/4697/ما-حكم-الطواف-من-داخل-الحجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0433.mp3","categories":["الطواف بالبيت"]},{"id":382,"question":"ما أفضل وقت لطواف الإفاضة؟ وهل ينعقد التَّحلل بالحلِّ يوم النحر إذا أخَّر الحاجُّ الطواف إلى اليوم الثاني؟","title":"ما الصواب في وقت طواف الإفاضة والرمي؟","answer":"الجواب: طواف الإفاضة يبتدئ بعد طلوع الشمس عند أهل العلم، وأما الضعفاء من الشيوخ والنساء فيبتدئ بعد نصف الليل عند جمعٍ من أهل العلم؛ لأن الرسول ﷺ رخَّص للضّعفاء، فلهم أن يرموا في النصف الأخير من ليلة النحر، ولأتباعهم ومَن معهم كذلك على الصَّحيح. وأما الأقوياء فالسنة أن يكون رميهم بعد طلوع الشمس؛ لحديث: لا ترموا الجمرةَ حتى تطلع الشمس، وإن كان فيه مقالٌ وضعفٌ، لكن لأن الرسول ﷺ رمى بعد طلوع الشمس، فالتأسِّي به هو السنة، ومَن رمى قبل ذلك في النصف الأخير؛ أجزأه ذلك على الصحيح، ولا سيما إذا كان من الضَّعفة والشيوخ والعجائز والكبار ونحو ذلك.\nولو صحَّ هذا الحديث: لا ترموا حتى تطلع الشمس فالجمع بينه وبين ما جاء في أحاديث الضَّعفة: أن ذلك من باب الأفضلية؛ الرمي بعد طلوع الشمس أفضل، وإذا رمى قبل ذلك في النصف الأخير من الليل؛ أجزأ ذلك.\nوأما الحديث فلا يُعتمد عليه؛ لأن في سنده انقطاعًا، ولأن له روايةً أخرى أن الصبية رموا عند وقت الفجر.\nفالحاصل أنه حديثٌ فيه ضعفٌ، وفيه انقطاعٌ، ولو صحَّ لكان محمولًا على الأفضلية، كما فعله النبي صلى الله عليه وسلم، فإنه رمى ضُحًى عليه الصلاة والسلام، وقد ثبت أن أم سلمة رمت قبل الفجر -وهو حديثٌ صحيحٌ- بإذنه عليه الصلاة والسلام، وقالت أسماء بنت أبي بكر لما دفعت بعدما غاب القمرُ ورمت الجمرة قالت: \"إن الرسول أذن للظّعن\" يعني: النساء، رواه مسلم، هذا هو الأصل في هذا الباب.\nثم أيضًا أمْرٌ آخر، وهو التَّسهيل والتيسير الذي جاء به الشرعُ، والله يقول سبحانه: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185]، ويقول : وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]، والنبي ﷺ يقول: يسّروا ولا تُعسّروا، وقد سأله رجلٌ فقال: يا رسول الله، أفضت قبل أن أرمي، فقال: لا حرج، إفاضة قبل الرمي، فقال: لا حرج، وهذه الإفاضة تحتمل أنها وقعت في آخر الليل، في النصف الأخير في الفجر؛ لأنَّ الرمي مشروعٌ بعد طلوع الشمس، فالذي أفاض قبل أن يرمي ولم يسأله النبي ولم يستفصله؛ يحتمل أن إفاضته كانت عند طلوع الفجر، أو في أثناء الليل في النصف الأخير، فلو كان هذا ممنوعًا لاستفصله وقال له: هل أفضتَ قبل طلوع الشمس أم لا؟\nفالحاصل أنَّ هذا دليلٌ على أنَّ الأمر فيه سعة، والحمد لله.","link":"https://binbaz.org.sa/fatwas/4710/ما-الصواب-في-وقت-طواف-الافاضة-والرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0438.mp3","categories":["الطواف بالبيت"]},{"id":629,"question":"من كان متمتعًا يلبي وهو يطوف؟","title":"هل تُقطع التلبية عند الشروع في الطواف؟","answer":"الجواب: يقطع التلبية عند الشروع في الطواف، جاء في الحديث أنه ﷺ قطع التلبية لما شرع في طواف  العمرة، عمرة القضاء أو عمرة الجعرانة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6495/هل-تقطع-التلبية-عند-الشروع-في-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/MARAM197 - 03 - .mp3","categories":["الطواف بالبيت"]},{"id":630,"question":"المعتمر إذا وصل إلى البيت ورأى الكعبة لكنه لم يشرع في الطواف يشرع له التلبية قبل الطواف وهو يرى البيت؟","title":"ما حكم التلبيةقبل الطواف؟","answer":"الجواب: لا يلزم، يلبي حتى يصل البيت، أما حديث أنه إذا رأى البيت يرفع يديه ويقول: اللهم زد هذا البيت تعظيمًا وتكريمًا ومهابة فهو حديث منكر، حديث معضل، ليس بصحيح.","link":"https://binbaz.org.sa/fatwas/6496/ما-حكم-التلبية-قبل-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/MARAM198 - 03 - .mp3","categories":["الحكم على الأحاديث","الطواف بالبيت"]},{"id":631,"question":"انقطاع التلبية بالعمرة؟","title":"متي يقطع المعتمر التلبية؟","answer":"الجواب: عند وصوله إلى البيت.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6497/متي-يقطع-المعتمر-التلبية","audio":"https://files.zadapps.info/binbaz.org.sa/maram199 - 03 - .mp3","categories":["الطواف بالبيت"]},{"id":646,"question":"بالنسبة لبعض الناس إذا أراد أن يقبل الحجر الأسود وضع جبهته عليه كالسجود؟","title":"ما كيفية تقبيل الحجر الأسود؟","answer":"الجواب: يروى عن ابن عباس عن النبي ﷺ أنه سجد عليه، لكن في صحته نظر، المعروف عن النبي ﷺ التقبيل والاستلام باليد، هذا هو الأحوط.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6676/ما-كيفية-تقبيل-الحجر-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/maram214 - 03 - .mp3","categories":["الطواف بالبيت"]},{"id":648,"question":"استلام الحجر الأسود بالمحجن أو بالإشارة إليه: عند عدم القدرة، أم مطلقًا يجوز؟","title":"حكم استلام الحجر الأسود والإشارة إليه","answer":"الجواب: الظاهر أنه قد يكون لأسباب الزحمة، لكن الأفضل يباشره، لكن إذا كان يحب أنه لا يزاحم أو أنه عجز.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6678/حكم-استلام-الحجر-الاسود-والاشارة-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/maram216.mp3","categories":["الطواف بالبيت"]},{"id":654,"question":"في الطواف نشاهد ناس معهم كتيبات بدعية دعاء الشوط الأول، أو الشوط الثاني، هل ينصحهم أو يشتغل بالأذكار ويدعو؟","title":"حكم تخصيص أشواط الطواف بأدعية معيّنة","answer":"الجواب: يشتغل بالأذكار ويدعو، وإن علّمهم فلا بأس، إن قال ما لها أذكار خاصة فالأمر واسع؛ لأن هؤلاء عامة يحتاجون إلى من يعلمهم، ما يعرفون شيئًا، ولكن ما هناك ذكر مخصص لكل شوط، إنما هذا يوجد في بعض المناسك تسهيلاً على الناس، ولكن يُعلَّمون: ترى ما في شيء خاص بالشوط الأول أو الثاني، الإنسان يذكر ويدعو الله في جميع الأشواط بما تيسر.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6685/حكم-تخصيص-اشواط-الطواف-بادعية-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/maram223 - 03 - .mp3","categories":["الطواف بالبيت","السعي","الأدعية والأذكار"]},{"id":655,"question":"من الناس من يأتي إلى الحج ولا يأتي إلى الحرم مباشرة، يذهب إلى منِى في اليوم الثامن فلا يطوف طواف القدوم ويؤخّره مع طواف الإفاضة؟","title":"حكم من يأتي لمِنى قبل الحرم لأداء الحج","answer":"الجواب: هذا ما ينبغي، هذا خلاف السُّنة، السنة أن يصل مكة ويطوف طواف القدوم ويرمل ويسعى، ويقدم السعي أيضاً، ثم إذا نزل من مِنى يوم العيد يبقى عليه طواف الإفاضة بس، لكن إذا كان مُحْرمًا بالحج مُفْردًا أو بالقِران يبقى على إحرامه.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6686/حكم-من-ياتي-لمنى-قبل-الحرم-لاداء-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/maram224 - 03 - .mp3","categories":["الطواف بالبيت"]},{"id":677,"question":"عمل أعمال الحاج ولكنه ترك طواف الوداع؟","title":"ما حكم من ترك طواف الوداع؟","answer":"الجواب: عليه دم يُذبح في مكة للفقراء، من ترك طواف الوداع أو شيئًا من الواجبات عليه دم يُذبح في مكة للفقراء، يمكن إنسانًا ثقة يذبح عنه.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6716/ما-حكم-من-ترك-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/maram245 - 03 - .mp3","categories":["الطواف بالبيت"]},{"id":779,"question":"مَن أحدث في الطَّواف هل يستأنف أم يُكمل؟ ومَن قطع الطَّواف لأداء الصلاة هل يستأنف الطَّواف أم يُكمل؟ وما الفرق بين الحالتين؟","title":"حكم مَنْ أحْدَث في طوافه أو قطعه للصلاة","answer":"الجواب: مَن أحدث في الطواف؛ قطع الطوافَ، كالذي أحدث في الصلاة، يُعيده من أوله.  أما إذا أُقيمت وهو يطوف فكمَّل ثم تمم لا بأس؛ لأنه قطعه لعذرٍ شرعيٍّ، وهو على طهارته، قطعه لعذرٍ شرعيٍّ، هذا مثل لو زحم خرج من الطواف ثم عاد إليه؛ يُكْمل طوافه، أما مَن أحدث -خرج منه ريحٌ أو بولٌ- فإنه يتوضأ ويُعيد الطواف من أوله على الصَّحيح.","link":"https://binbaz.org.sa/fatwas/20727/حكم-من-احدث-في-طوافه-او-قطعه-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0609حكم من أحدث هو يطوف هل يستأنف الطواف من جديد أم يكمل؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطواف بالبيت"]},{"id":812,"question":"أدَّيتُ فريضة الحج في هذا العام، وأجلت طوافَ الإفاضة إلى ما بعد أيام التَّشريق لخمسة أيام، فهل عليَّ في ذلك شيءٌ؟","title":"حكم تأجيل طواف الإفاضة بعد أيام التشريق","answer":"الجواب: ليس في ذلك حرجٌ، وليس لطواف الإفاضة حدٌّ محدودٌ، فإذا طافه بعد الحج بعد أيام الحج بأيامٍ أو في آخر الشَّهر فلا بأس، حتى لو أخَّره إلى المحرم أو صفر لا حرج عليه في ذلك، لكن البدار به أفضل، وليس له أن يأتي أهله حتى يطوف، وإن كان امرأةً ليس لها أن يمسَّها زوجُها حتى تطوف، فالبدار به أولى عند زوال الزحمة.","link":"https://binbaz.org.sa/fatwas/20843/حكم-تاجيل-طواف-الافاضة-بعد-ايام-التشريق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0639حكم تأجيل طواف الأفاضة إلى ما بعد أيام التشريق؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطواف بالبيت"]},{"id":1125,"question":"لقد ذهبتُ للعمرة في إجازة الربيع، وعند عودتي اختلفتُ مع أحد زملائي في طواف الوداع: هل هو واجب أو غير واجبٍ؟ واستدللتُ بفتوى الشيخ الحبيب ابن عثيمين حفظه الله، وعند عودتي إلى مكان إقامتي وجدتُ فتوى أخرى لبعض العلماء بعدم الوجوب. هل أخذي فتوى عدم الوجوب مع اعتقادي أنَّ الوجوب هو الأحوط يُعتبر ذلك من تتبع الرخص عند الفقهاء؟ ثم هل لكم جزاكم الله خيرًا التفصيل في المسألة؛ لأنها مهمة لطالب العلم وفَّقكم الله لكلِّ خيرٍ؟","title":"هل يجب طواف الوداع في العمرة؟","answer":"الجواب:\nالوداع في العمرة اختلف فيه العلماء: فمنهم مَن أوجبه كالحج، ومنهم مَن لم يُوجبه، والصواب أنه لا يجب في العمرة؛ لأنَّ الرسول ﷺ لم يأمر به المعتمرين، ولم يُودّع لما اعتمر في عمرة القضاء، ولم يأمر المعتمرين في حجَّة الوداع أن يطوفوا لما خرجوا من مكة، وهم يخرجون إلى خارج مكة، ويرعون الإبل خارج مكة، ولم يأمرهم بالوداع، ولما أحرموا يوم الثامن من مكة لم يأمرهم بالوداع. فليس للعمرة وداعٌ واجب، ومَن ودَّع فلا بأس، الطواف عبادة، خير عظيم، إذا ودَّع طيب، ولكن لا يلزم، إنما الوداع الواجب في الحج؛ لقول النبي ﷺ: لا ينفرنَّ أحدٌ منكم حتى يكون آخر عهده في البيت، قال ابنُ عباس: أمر الناس أن يكون آخر عهدهم بالبيت، يعني: الحجاج، هذا جاء في الحُجَّاج، كانوا ينصرفون من مِنى في كل وجهٍ بغير وداعٍ، فأمرهم أن يُودِّعوا عليه الصلاة والسلام.\nولأن العمرة عبادة مُطلقة في جميع الزمان، وشأنها التَّخفيف والتيسير، فلهذا لم يُشرع فيها إلا الطَّواف والسَّعي والتَّقصير، فهي زيارة للبيت، فلا يلزم فيها الوداع.\nولكن مَن ودَّع فحسنٌ، إذا تيسر له الوداع حسن؛ عملًا بالخير واحتياطًا، وإلا فالدليل يدل على عدم وجوب الوداع في العمرة، والأمر في هذا واسعٌ، والحمد لله.","link":"https://binbaz.org.sa/fatwas/21179/هل-يجب-طواف-الوداع-في-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0975هل طواف الوداع في العمرة واجب أم لا؟.mp3","categories":["الطواف بالبيت"]},{"id":1252,"question":"هل الاضطباع في طواف العمرة يشمل جميع أشواط الطواف أم يقتصر على الأشواط الثلاثة الأول؟","title":"هل سُنة الاضطباع في جميع أشواط الطواف؟","answer":"الجواب:\nالاضطباع في جميع الطواف: طواف القدوم في الحج والعمرة، طواف القدوم، يضطبع في جميع الطواف، وهو أن يجعل وسط ردائه تحت إبطه الأيمن، وأطرافه على عاتقه الأيسر، ويكشف ضبعه الأيمن -منكبه الأيمن-، هذا الاضطباع، يجعل وسط الرداء تحت إبطه الأيمن، وطرفه على عاتقه الأيسر في طواف القدوم خاصةً، من أوله إلى آخره. فإذا فرغ سوَّى الرداء على عاتقيه، وصلَّى صلاة الطواف بعد أن يُسوِّي الرداء على عاتقيه، حتى لا يكشفهما، يُسوي الرداء على عاتقيه بعد فراغه من الطواف، وهذا في طواف  القدوم خاصةً.\nأما طواف الإفاضة وطواف الوداع: ما في اضطباع، ولا فيه رَمَل، والرَّمَل في طواف القدوم أيضًا، الرمل في طواف القدوم في الحج والعمرة.\nوالرَّمَل يكون في الأشواط الثلاثة الأولى فقط، أما الاضطباع ففي السبعة كلها، وأما الرمل -وهو الخبب، أي: السرعة في المشي- ففي الشوط الأول والثاني والثالث خاصةً، في طواف القدوم يخبّ دون الركض وفوق المشي، ويمشي في الأربعة في طواف القدوم خاصةً، في الأول والثاني والثالث. أما الاضطباع فإنه يكون في الأشواط السبعة كلها في طواف القدوم، ولكن لا يفعل هذا في طواف الإفاضة، ولا في طواف الوداع، ولا في الأطواف الأخرى، بل هذا خاصٌّ بطواف القدوم.","link":"https://binbaz.org.sa/fatwas/21302/هل-سنة-الاضطباع-في-جميع-اشواط-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1045هل الاضطباع في جميع أشواط الطوف؟ ابن باز.mp3","categories":["الطواف بالبيت"]},{"id":1290,"question":"طواف الوداع للمُقيمين هل يجوز قبل مغادرة المملكة بعد شهورٍ مثلًا من الحج؟","title":"حكم تأخير طواف الوداع بعد أشهر من الحج","answer":"الجواب:\nنعم، متى أراد المغادرة يُودِّع، ولو في ربيع أول، ولو في ربيع ثانٍ، ولو في رجب، متى أراد السفر، ما دام مُقيمًا ما عليه وداع.\nس: إن كان مقيمًا في الطائف يلزمه أيضًا طواف الوداع؟\nالشيخ: إذا أراد الخروج يُودِّع،ـ الطائف، أو جدة.","link":"https://binbaz.org.sa/fatwas/21345/حكم-تاخير-طواف-الوداع-بعد-اشهر-من-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1088طواف الوداع للمقيمين هل يجوز قبل مغادرة الممكلة بعد شهور من الحج؟.mp3","categories":["الطواف بالبيت"]},{"id":1471,"question":"يقول السائل: ما آخر وقت طواف الإفاضة؟","title":"ما آخر وقت طواف الإفاضة؟","answer":"الجواب:\nالصحيح أنه ليس له حدٌّ، لكن البِدار به في أيام النحر أفضل، ولو ما طاف إلا بعد -لآخر الشهر أو في المحرم أو في صفر- أجزأ، لكن المبادرة به في أيام مِنَى أفضل.","link":"https://binbaz.org.sa/fatwas/21569/ما-اخر-وقت-طواف-الافاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/آخر وقت طواف الإفاضة.mp3","categories":["الطواف بالبيت"]},{"id":1567,"question":"ما رُوي من تقبيل الحجر الأسود والسجود عليه؟","title":"حكم تقبيل الحجر الأسود والسجود عليه","answer":"الجواب:\nورد فيه حديث ابن عباس في البداية يعني: وضع جبهته عليه، لا بأس، المحفوظ عن النبي ﷺ أنه قبَّله واستلمه، لكن ابن عباس ذكر أيضًا أنه سجد عليه، وفي روايته اختلاف، جاء موقوفًا ومرفوعًا، والأمر واسع، والمحفوظ الاستلام والتقبيل فقط، أما السجود فمحل اختلاف.","link":"https://binbaz.org.sa/fatwas/21670/حكم-تقبيل-الحجر-الاسود-والسجود-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تقبيل الحجر الأسود والسجود عليه.mp3","categories":["الطواف بالبيت"]},{"id":1737,"question":"إذا طهرت الحائضُ قبل مفارقة بنيان مكة، هل يلزمها الرجوعُ للبيت لطواف الوداع؟","title":"حكم من حاضت ثم طهرت قبل طواف الوداع","answer":"الجواب:\nلا، ما يلزمها، إذا خرجت وهي حائض ما عليها شيء.\nس: إذا طهرت؟\nج: ولو طهرت، ما دامت فارقت البلد فالحمد لله.\nس: قبل مفارقة البنيان إذا طهرت هل يلزمها الرجوع لطواف الوداع؟\nج: ما يلزمها الرجوع.","link":"https://binbaz.org.sa/fatwas/21844/حكم-من-حاضت-ثم-طهرت-قبل-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا طهرت الحائض قبل خروجها من مكة هل ترجع للبيت لطواف الوداع.mp3","categories":["الطواف بالبيت","الحيض والنفاس","قضايا المرأة"]},{"id":2060,"question":"هل سُنَّة الرَّمَل في الطواف خاصَّة بطواف القُدوم؟","title":"هل سُنَّة الرَّمَل خاصَّة بطواف القُدوم؟","answer":"الجواب:\nنعم، طواف القدوم، في الأشواط الثلاثة الأُوَل بس، في طواف القدوم، سواء كان طواف عمرةٍ أو حجٍّ.","link":"https://binbaz.org.sa/fatwas/22178/هل-سنة-الرمل-خاصة-بطواف-القدوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سنة الرمل خاصَّة بطواف القُدوم.mp3","categories":["الطواف بالبيت"]},{"id":2092,"question":"ما الصواب في دم الحيض؟ هل هو نَجِسٌ أم طاهرٌ؟","title":"هل دم الحيض نَجِسٌ أم طاهرٌ؟","answer":"الجواب:\nهو دم نَجِس؛ فالنبي عليه الصلاة والسلام أمر بغَسْله.","link":"https://binbaz.org.sa/fatwas/22210/هل-دم-الحيض-نجس-ام-طاهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم دم الحيض.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":2397,"question":"إنسان يطوف في البيت وقضى بعض الأشواط ثم حصل عليه حدث، هل يذهب لأجل أن يجدد الوضوء أم يتم الطواف؟","title":"ما حكم مَنْ أحدث أثناء الطواف؟","answer":"الجواب:\nالطواف مثل الصلاة، إذا أحدث ينقطع، يذهب يتوضأ ويعيده من أوله.\nس: هل يبدأ مرة ثانية أم يُكمل؟\nالشيخ: لا، يبدأ من أوله، من الحَجَر، يبدأ الطواف من الحَجَر، الذي ذهب منه لاغٍ.\nس: ولو ستة أشواط؟\nالشيخ: ولو، ولو، يعيده كله، كفارة للذي أحدث فيه، كالصلاة إذا أحدث فيها يعيدها من أولها.","link":"https://binbaz.org.sa/fatwas/22522/ما-حكم-من-احدث-اثناء-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من أحدث أثناء الطواف.mp3","categories":["ما يشرع له الوضوء","الطواف بالبيت"]},{"id":2659,"question":"امرأة حجّت وفي طواف القدوم حاضت..... واستمرت هي في أداء المناسك، وكانت قبل الطواف قد أحست بأعراض الحيض وظنت أنها لم تنزل؛ لأنها كانت تشعر بذلك في أيامها الأخرى ولا يأتيها الحيض إلا بعد يوم، ولكن في الحج اختلف ذلك فما حكم حجها؟","title":"حكم مَن حجّت وفي طواف القدوم حاضت","answer":"الجواب: طواف القدوم بَطَل، ويكفيها طواف الإفاضة، إن شاء الله بعدين تصير قارنة، ما دام أنها دخلت بالحج تصير مفردة، وإن كانت دخلت بعمرة ثم لَبَّت بالحج صارت قارنة، طواف القدوم يكون لاغيًا وسعي القدوم، ويبقى لها طواف الإفاضة بعد الحج.  تكون لها قارنة إن لبت بالحج، وإن كانت دخلت بحج مفرد طوافها بعد الحج يكفيها عن طواف القدوم.  وإن كانت دخلت بعمرة يكفيها طواف الإفاضة ويكون عليها دم إقران، تصير قارنة.  وإن كان زوجها أتاها وهي في العمرة تفسد العمرة، عليها أن تكملها بعد الطهر، وإن كانت ما لها زوج ولا أتاها زوج الحمد لله؛ طواف الحج يكفيها؛ لأنها تختلف: إن كانت ملبية بالعمرة تكون قارنة.  وإن كانت لبت بالحج تكون على حالها حج مفرد، ويكون طوافها لاغيًا الطواف الأول، ويكفيها عن طواف الإفاضة.","link":"https://binbaz.org.sa/fatwas/22795/حكم-من-حجت-وفي-طواف-القدوم-حاضت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من حجت وفي طواف القدوم حاضت.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3155,"question":"الطواف راكبًا لغير حاجة؟","title":"هل يجوز الطواف راكبًا لغير حاجة؟","answer":"الجواب: ما ينبغي إلا من ضرورة كالكِبَر والمرض، النبي ﷺ طاف راكبًا لمّا غشيه الناس وخِيفَ عليه، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23317/هل-يجوز-الطواف-راكبا-لغير-حاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الطواف راكبا لغير حاجة.mp3","categories":["الطواف بالبيت"]},{"id":3156,"question":"رجل في رمضان كان يطوف بالبيت وبعدما أنهى الشوط الثالث أُذن للمغرب ثم توقف وأفطر وصلى المغرب، ورجع وكمل الأربعة الباقية، فهل هذا صحيح؟","title":"حكم قطع الطواف للإفطار والصلاة","answer":"الجواب: إن كان تطوّع الأمر واسع، إن كان تطوّع لا يلزمه الإعادة.\nس: طواف العمرة، طواف القدوم؟\nالشيخ: لا،ـ يلزمه، يعيد الطواف، وأما السعي إن أعاده فحسن وإلا ما يلزم إعادته على الصحيح، لكن يلزمه إعادة الطواف لأنه أكل، كونه يفصله بأنه يصلي مع الناس أو على جنازة لا بأس بهذا.\nس: لكن إذا أفطر بالنية، نيته أنه يفطر؟\nالشيخ: إذا ما أكل ولا شرب؟\nس: أي نعم لا يفوته الأجر يعني؟\nالشيخ: محل نظر؛ لأن نية إبطال الصلاة تبطلها وهو الصواب، فالأقرب -والله أعلم- أنه يشبه ذلك، إذا أراد أبطاله، إذا نوى إبطاله.\nس: لكن الأحكام تعارضت يا شيخ: الصلاة والإفطار؟\nالشيخ: حتى لو تعارض فِطر وصوم ليس له أن يفطر في الفريضة حتى يكمل الصوم بغروب الشمس، أما النافلة فلا بأس له أن يفطر.","link":"https://binbaz.org.sa/fatwas/23319/حكم-قطع-الطواف-للافطار-والصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قطع الطواف للإفطار والصلاة.mp3","categories":["الطواف بالبيت"]},{"id":3205,"question":"في كتيبات في أدعية العُمّار والحُجّاج: لكل شوط دعاء، فهل هذه بدعة؟","title":"حكم تخصيص كل شوط في الطواف بدعاء؟","answer":"الجواب: ما لها أصل، ما لها أصل.\nس: تعتبر بدعة؟\nالشيخ: يذكرون الله، يأتون بما يَسَّرَ الله مِنَ الذكر والدعاء في الأشواط كلها.\nس: ننكر عليهم؟\nالشيخ: تخصيصها للرجال أفضل من تركها.\nس: هل يقال أنها بدعة؟\nالشيخ: الأقرب فيه أنه بدعة؛ تخصيص كل شوط بشيء.\nس: ويَدِينُون بها الله، والعامة إذا ما أتوا بها...؟\nالشيخ: الأقرب أنها بدعة من عمل عملًا ليس عليه أمرنا فهو رد.","link":"https://binbaz.org.sa/fatwas/23368/حكم-تخصيص-كل-شوط-في-الطواف-بدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لكل شوط دعاء.mp3","categories":["الأدعية والأذكار","الطواف بالبيت"]},{"id":3373,"question":"المرأة إذا ركّبت \"لولب\" ثم نزل معها دم يسير تكون استحاضة أم يكون حيضًا؟","title":"حكم الدم اليسير الناتج عن \"اللولب\" للنساء","answer":"الجواب: تُراجِع العادة، ما جاء في وقت العادة تترك الصلاة فيه، وما جاء في غير العادة فهو استحاضة دم فساد.\nس: تضطرب عادتها مع هذا؟\nالشيخ: ولَوْ، تُراعِي العادة.","link":"https://binbaz.org.sa/fatwas/23541/حكم-الدم-اليسير-الناتج-عن-اللولب-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أركبت المرأة لولب ثم نزل معها دم، هل تكون استحاضة أم يكون حيضا.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3375,"question":"تضطرب العادة بين أن تكون سبعة أيام في الشهر أربع سنين، ثم تتنقل إلى خمسة عشر يومًا أربع سنين أخرى، هل يحصل هذا للنساء؟","title":"حكم المرأة التي تضطرب عادتها","answer":"الجواب: الله أعلم، قد يقع، قد تتغير العادة.\nس: ما  ينقص عن هذا، والدم إذا زاد لأربع سنين أخرى...؟\nالشيخ: تلزمها العادة، ولا تفرّط، النبي ﷺ أمر بلزوم العادة، أن تلزم عادتها، وما زاد فهو استحاضة؛ تصلي، وتصوم، والحمد لله.\nس: تجمع بين الصلاتين إذا اغتسلت، أو مطلقًا؟\nالشيخ: تغتسل مثلما أمر حمنة رضي الله عنها تغتسل للصلاتين، هذا سنة، والواجب الوضوء، لكن الغسل مستحب.\nس: لكن الجمع؟\nالشيخ: تجمع وتغتسل أفضل إذا شق عليها الأمر.\nس: لها أن تجمع بدون اغتسال؟\nالشيخ: الأفضل الغسل، السنة الغسل، وإلا ما هو بواجب، الواجب عليها غسل الحيض فقط.\nس: لكن سؤالي -أحسن الله إليك- عن الجمع؟\nالشيخ: الجمع مع الغسل أفضل، ولو جمعت بدون غسل صح.","link":"https://binbaz.org.sa/fatwas/23543/حكم-المراة-التي-تضطرب-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المرأة التي تضطرب عادتها.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3378,"question":"يقول الفقهاء: إذا زادت أيام العادة على المرأة فإنها تُتْبِعها بالعادة فإنْ فَحُشَت الزيادة كانت مستحاضة، إيش الضابط؟","title":"ما ضابط التمييز بين الحيض والاستحاضة؟","answer":"الجواب: النبي ﷺ أمر المرأة أن تمسك العادة مثل ما قال لأم حبيبة: امكثي قدر ما كانت تحبسك حيضتك ثم اغتسلي، وهكذا أمر فاطمة بنت أبي حبيش، وأمر حمنة كذلك تمسك عادتها، والباقي تصلي وتصوم، ولا يسع النساء إلا هكذا؛ لأنهن يضطربن كثيرًا ما يضطرب عليهن الدم اضطرابًا كثيرًا.\nس: لكن أحسن الله إليكم لو زادت عادتها ثم رأت القصة البيضاء بعد الزيادة، عادتها خمس، ثم زادت ثمان، وترى القصة بعد الثمان؟\nالشيخ: هذا محل نظر، قد يقال إن الزيادة المتصلة التي من جنس دم الحيض قد يقال أنها يعفى عنها... يسيرة، لكن ما ينضبط الأمر ما يضبطه إلا مثل ما قال ﷺ لحمنة ولفاطمة بنت أبي حبيش ولأم حبيبة، كلهن قال لهن: امكثن قدر ما كانت تحبسكن حيضتكن ثم اغتسلن؛ لأن هذا هو الذي يضبطهن.","link":"https://binbaz.org.sa/fatwas/23546/ما-ضابط-التمييز-بين-الحيض-والاستحاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الضابط في الحيض والاستحاضة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3379,"question":"إذا طهرت قبل الفجر بنصف ساعة هل يلزمها أن تصلي المغرب والعشاء؟","title":"حكم المغرب والعشاء لمن طَهُرت قبل الفجر","answer":"الجواب: هذا أفتى به جماعة من الصحابة رضي الله عنهم وأرضاهم، مثل لو طَهُرَت في العصر تصلي الظهر والعصر. هذا، وقت الضرورة، وقت العشاء، وقت الضرورة بعد النصف، من جنس العصر.\nس: فتواكم أنتم فيها؟\nالشيخ: تصلي المغرب والعشاء.","link":"https://binbaz.org.sa/fatwas/23547/حكم-المغرب-والعشاء-لمن-طهرت-قبل-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طهرت قبل الفجر، فهل تصلي المغرب، والعشاء.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3380,"question":"المرأة: الدم الذي تراه بعد الحيضة، هل يُعتدّ به؟","title":"هل تَعْتَدُّ المرأة بالدم الذي تراه بعد الحيضة؟","answer":"الجواب: لا، يصير دم فساد، بعد العادة؛ تتوضأ لكل صلاة.\nس: ولو كان دم حيض؟\nالشيخ: إذا كان بعد العادة هذه تُبتلى النساء بالدماء، والنبي ﷺ حكم بمراعاة العادة؛ حتى يستريح النساء.","link":"https://binbaz.org.sa/fatwas/23548/هل-تعتد-المراة-بالدم-الذي-تراه-بعد-الحيضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تعتد المرأة بالدم الذي تراه بعد الحيضة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3381,"question":"قول عائشة: لا تَعْجَلْنَ حتى تَرَيْنَ القَّصَّة البيضاء...؟","title":"هل القَّصَّة البيضاء علامة للطُّهر من الحيض؟","answer":"الجواب: لا، ما هو بلازم، القَّصَّة البيضاء غالبًا، وإلا المرأة إذا طَهُرَت يكفي، ولو ما جاءتها القصة البيضاء، بعض النساء ما يرين القصة البيضاء....\nإذا رأت الطهر يكفي، ما بقي شيء، إذا رأت... القطنة ونحوها ما رأت فيها شيئًا؛ فالحمد لله.","link":"https://binbaz.org.sa/fatwas/23549/هل-القصة-البيضاء-علامة-للطهر-من-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العبرة برؤية الطهر في الحيض.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3382,"question":"قال بعض فقهاء الشافعية أن الحائض يجري عليها أجر الصلاة في زمن عادتها لعموم حديث أبي موسى: إذا مرض العبد، أو سافر..؟","title":"هل يَجْرِي للحائض أجر الصلاة فترة عادتها؟","answer":"الجواب: ما هو بعيد، ظاهر الأدلة على ذلك، إذا علم الله مِنْ قلبها أنها لولا الحيض لصلت؛ لها أجر المصلين مثل إذا مرض العبد أو سافر كتب الله له ما كان يعمله وهو صحيح مقيم، ومثل قوله في الصحابة الذين تخلفوا يوم تبوك: ما سلكتم واديًا ولا قطعتم شعبًا إلا وهم معكم، وفي اللفظ الآخر: إلا شركوكم في الأجر، حبسهم العذر، فإذا علم الله من قلب الحائض، والنفساء أنه ما منعها إلا هذا فيرجى لها الأجر الكامل.\nس: حديث: ناقصات دين.\nالشيخ: حديث ناقصات عقل ودين ثابت، لكن ما يَمْنَع.","link":"https://binbaz.org.sa/fatwas/23550/هل-يجري-للحاىض-اجر-الصلاة-فترة-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجري للحائض أجر الصلاة في زمن عادتها.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3383,"question":"قول البخاري: باب من اتخذ ثياب الحيض سوى ثياب الطهر؟","title":"حكم اتخاذ ثياب للحيض غير ثياب الطُّهر","answer":"الجواب: لا بأس، من باب النظافة والعناية، ثياب جيدة نظيفة حتى لا يصيبها الدماء.\nس : ما يقال أنه سُنَّة لإقرار النبي ﷺ؟\nالشيخ: مُحْتَمِل.","link":"https://binbaz.org.sa/fatwas/23551/حكم-اتخاذ-ثياب-للحيض-غير-ثياب-الطهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اتخاذ ثياب الحيض سوى ثياب الطهر.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3384,"question":"هل (المستحاضة) يكفيها الوضوء لكل صلاة؟","title":"هل تتوضأ المستحاضة لكل صلاة؟","answer":"الجواب: نعم؛ يكفيها الوضوء لكل صلاة.","link":"https://binbaz.org.sa/fatwas/23552/هل-تتوضا-المستحاضة-لكل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تتوضأ المستحاضة لكل صلاة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3385,"question":"إذا كان الإنسان مصابًا بمرض خطير فهل يَنْفِر بدون طواف؟","title":"حكم الطواف لمن كان مصابًا بمرض خطير","answer":"الجواب: لا، يُحْمَل، يُطاف به محمولًا.\nس: لكن إذا كان في العناية، أو كذا...؟\nالشيخ: الظاهر، والله أعلم، أنه يكون عليه دم، فيجوز له الترك مثل ما يترك الشيء الذي عجز عنه، أو يقال لا شيء عليه لأجل العجز، معذور كما عذرت الحائض، والنفساء، محتمل، ومثل ما يسقط المبيت في منى عن الرعاة والسقاة، قد يقال في حق المريض العاجز مرة الذي ما يُستطاع أن يُطاف به، قد يقال لا شيء عليه كما لا شيء على من عجز عن المبيت، وقد يُقال بوجوب الدم كما يُقال في حق من ترك الرمي ولو عاجزًا؛ لأن في إمكانه التوكيل، أما الطواف لا يُوكل فيه؛ فالأقرب، والله أعلم، أنه يسقط عنه إذا عجز عن الطواف لا راكبًا، ولا ماشيًا، ولا محمولاً، وإن فَدَى من باب الاحتياط إذا كان يعجز محمولاً فهذا من باب الاحتياط، وإلا فيُطاف به محمولا.\nس: هذا في طواف...؟\nالشيخ: طواف الوداع.","link":"https://binbaz.org.sa/fatwas/23553/حكم-الطواف-لمن-كان-مصابا-بمرض-خطير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ينفر بدون طواف من كان مصابًا بمرض خطير.mp3","categories":["الطواف بالبيت"]},{"id":3389,"question":"قول ابن عباس: (تغتسل وتصلي، ولو ساعة) يعني ولو طهرت ساعة واحدة بس؟","title":"معنى (تغتسل وتصلي ولو ساعة) للحائض","answer":"الجواب: متى رأت الطهارة يعني، الطهارة العادية.\nس: ولو ساعة؟\nالشيخ: ولو، إذا رأت الطهارة تغتسل وتصلي، هذا المراد.\nس: وإذا عاودها الدم يعني؟\nالشيخ: في العادة تجلس ثم إن كان في غير العادة لا، دم استحاضة.","link":"https://binbaz.org.sa/fatwas/23557/معنى-تغتسل-وتصلي-ولو-ساعة-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقول بن عباس (تغتسل وتصلي، ولو ساعة).mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3390,"question":"رأت المرأة الطهر في أيام عادتها: هل تجلس وتصلي؟","title":"حكم رؤية المرأة الطُّهر في أيام عادتها","answer":"الجواب: تصلي وتصوم إذا رأت الطهر.  مَنْ عَادَتُها ست، وبعد ثلاثٍ رأت الطهارة؛ تغتسل وتصلي وتصوم، فإذا عاد في الست؛ تجلس.","link":"https://binbaz.org.sa/fatwas/23559/حكم-روية-المراة-الطهر-في-ايام-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إذا رأت المرأة الطهر في أيام عادتها.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3392,"question":"سائل يسأل يقول: امرأة يأتيها دم أسود يستمر معها ستة أيام قبل حيضها، ثم يأتيها حيضها لمدة سبعة أيام، فهل تصلي وتصوم في الأيام الأُوَل؟","title":"حكم مَنْ يأتيها دم أسود قبل حيضها متصل به","answer":"الجواب: وهو منفصل؟ عادة لها يأتيها هذا متصل مع الحيض؟\nالطالب: الدم أسود ستة أيام قل حيضها، ثم يأتيها حيضها سبعة أيام.\nالشيخ: بينهما فاصل؟\nس: ظاهر سؤاله أنه متصل.\nالشيخ: يأتي يسألني، يحتاج تأمل هذا، إن كان عادة لها كذا فهو عادة لها، وإن كان عارضًا لا، العمدة على عادتها، فإن كان عادة لها مستقيمة: أول الست أسود، ثم بقيته أحمر، مدة مستمرة، تكون عادة لها.\nس: طيب، وإذا كان منفصلًا؟\nالشيخ: إذا كان عارضًا لا، ما يصير عادة لها إذا كان عارض يكون من الاستحاضة.\nس: العارض يصلح عندكم، لو زادت العارض يوم؟\nالشيخ: الذي ما هو بعادة لها يعني.  \nس: أقول عادتها سبعة، ولكن في مرة اتصلت ثمانية، أو ...؟\nالشيخ: ما يضر إذا كان متصل ما بان شيء الأمر سهل لأن عادة النساء تزيد وتنقص كما قالت عائشة: \"لا تَعْجَلن\" لما عرضوا عليها الآثار.","link":"https://binbaz.org.sa/fatwas/23561/حكم-من-ياتيها-دم-اسود-قبل-حيضها-متصل-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المرأة التي يأتيها دم أسود قبل حيضها ثم يأتيها حيضها.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3393,"question":"وطء الحائض إذا طهرت قبل الاغتسال؟","title":"حكم وطء الحائض إذا طهرت قبل الاغتسال","answer":"الجواب: لا ما يجوز فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ [البقرة: 222] حتى تطهر فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ [البقرة: 222].\nس: والحالة هذه يلزمها الكفارة؟\nالشيخ: إذا وطأها قبل الغسل نعم.","link":"https://binbaz.org.sa/fatwas/23562/حكم-وطء-الحاىض-اذا-طهرت-قبل-الاغتسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وطء الحائض إذا طهرت قبل الاغتسال.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3559,"question":"هل يجوز لأحد أن يطوف والصلاة قائمة؟","title":"ما حكم الطواف والصلاة قائمة؟","answer":"الجواب: نعم، إذا كان في متسع مثل النساء، أما الرجل لا،ـ يصلي مع الناس.","link":"https://binbaz.org.sa/fatwas/23741/ما-حكم-الطواف-والصلاة-قاىمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الطواف والصلاة قائمة.mp3","categories":["الطواف بالبيت"]},{"id":3774,"question":"من قال بوجوب الوضوء للجُنُب قبل النوم؟","title":"حكم الوضوء للجُنُب قبل النوم؟","answer":"الجواب: قول جيد؛ لأن الرسول ﷺ قال لعمر توضأ ثم نم أمره بالوضوء، ظاهره الوجوب.\nس: وإذا نام، ولم يتوضأ هل يأثم؟\nالشيخ: يُخشى عليه.\nس: كيف يُحمل هذا الحديث \"كان يَجْنُب ثم ينام، ولا يمس ماء\"؟\nالشيخ: هذا حديث معلول، ولو صح المراد ماء الغسل يعني، ولكنه حديث معلول ضعيف.","link":"https://binbaz.org.sa/fatwas/23970/حكم-الوضوء-للجنب-قبل-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الوضوء للجنب قبل النوم.mp3","categories":["ما يشرع له الوضوء","الطواف بالبيت"]},{"id":4262,"question":"الحجر الأسود إذا حَبّه [قَبّلَه] الواحد، أنا أشوف ناس يحطون جبهتهم عليه؟","title":"حكم وضع الجبهة على الحجر الأسود","answer":"الجواب:\nلا، السجود عليه لا بأس والتقبيل يكفي، السجود جاء من حديث ابن عباس وسجد عليه النبي ﷺ فإن سجد فلا بأس، وإن اكتفى بالتقبيل كفى إن شاء الله مع اللمس باليد، مع الاستلام باليد إن تيسر، وإلا فيشير إليه ويكبّر.","link":"https://binbaz.org.sa/fatwas/24532/حكم-وضع-الجبهة-على-الحجر-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تقبيل الحجر الأسود ووضع الجبهة عليه.mp3","categories":["الطواف بالبيت"]},{"id":4366,"question":"تقبيل الحجر الأسود في غير الطواف؟","title":"هل يُشرع تقبيل الحجر الأسود دون طواف؟","answer":"الجواب: ما له أصل، إلا في الطواف.","link":"https://binbaz.org.sa/fatwas/24643/هل-يشرع-تقبيل-الحجر-الاسود-دون-طواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تقبيل الحجر الأسود في غير الطواف.mp3","categories":["الطواف بالبيت"]},{"id":4415,"question":"المقدار الذي يُتجاوز عنه في الحيض؟","title":"هل يُعفى عن شيء في غسل دم الحيض؟","answer":"الجواب: ما في شيء، النبي ﷺ أمر بغسله كله، ولهذا قال المؤلفُ نبَّه أنه لا يُجزئ عن شيءٍ، بل يجب غسله كله ولو قليلًا، التي مع الحيض يجب غسلها.  إنما يُعفى عن الشيء القليل، مثل: الرعاف، مثل: دم الأسنان، مثل: ما يحصل من العين فيها بعض السيل قليلًا، جراحات قليلة، يُعفى عن اليسير، أما الحيض فأمر النبي بغسله كله.","link":"https://binbaz.org.sa/fatwas/24692/هل-يعفى-عن-شيء-في-غسل-دم-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعفى عن شيء من دم الحيض.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4472,"question":"جلوس الحائض في الحرم للضَّرورة؟","title":"حكم جلوس الحائض في الحرم للضَّرورة","answer":"الجواب: الضرورة لها أحكامها، إذا كانت مثلًا ضاعت عن أهلها وتخشى...\nس: إذا كان جماعة معهم حائض، ويأتون الحرم ويتركونها...؟\nج: إذا كانت ضرورةً لا حرج إن شاء الله.","link":"https://binbaz.org.sa/fatwas/24750/حكم-جلوس-الحاىض-في-الحرم-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جلوس الحائض في الحرم للضَّرورة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4475,"question":"المُستحاضة إذا كانت لها عادة مكثت حسب عادتها، وإن لم تكن لها عادة تمكث؟","title":"كم تمكث المستحاضة إذا لم تكن لها عادة؟","answer":"الجواب: ستة أيام، أو سبعة أيام .....؛ لأنَّ عادة النساء غالبًا ستّ، سبع، هذا الغالب.","link":"https://binbaz.org.sa/fatwas/24754/كم-تمكث-المستحاضة-اذا-لم-تكن-لها-عادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المستحاضة إذا لم تكن لها عادة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4486,"question":"إذا كانت المرأةُ عادةً تحيض سبعًا... ثم خالفت فحاضت في شهرٍ ؟","title":"ما تفعل من اختلف عدد أيام حيضها عن عادتها","answer":"الجواب: لا، تجلس لا تُصلي ولا تصوم، تجلس لأجل الزيادة لا تُصلي ولا تصوم .....، وهكذا لو كانت عادتها سبعًا ثم رأت الطَّهارة بعد خمسٍ تغتسل.","link":"https://binbaz.org.sa/fatwas/24766/ما-تفعل-من-اختلف-عدد-ايام-حيضها-عن-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من اختلف عدد أيام حيضها زيادةً أو نقصانًا.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4487,"question":"مباشرة الحائض الأولى تركه؟","title":"حكم مباشرة الحائض","answer":"الجواب: لا بأس بمُباشرتها، كان النبيُّ يُباشرها ﷺ، كانت تنام معه.\nس: كأن الأصل الترك؟\nج: ذاك ما تحت الإزار، ترك ما تحت الإزار أولى، يعني: ينام معها وتلبس الإزار أو السراويل من غير تعرية كاملة.","link":"https://binbaz.org.sa/fatwas/24767/حكم-مباشرة-الحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مباشرة الحائض.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4690,"question":"قوله: فاستقبله وهلِّل وكبِّر؟","title":"هل يُشرع التهليل والتكبير عند الحجر الأسود؟","answer":"الجواب: أما قوله لعمر: إنَّك رجلٌ قوي فلا تُزاحم عند الحجر فهو حديث ضعيف، في إسناده شيخ مجهول، ولكن معناه صحيح، معناه: أن السنة أن لا يُزاحم ولا يُؤذي الناس، إن وجد فجوةً استلم، وإن لم يجد فجوةً أشار له إشارةً، لا يُزاحم ولا يُؤذي الناس، ولا سيما أن بعض الناس قد يكون قويًّا فيُؤذي، فالسنة أن يُشير ويمشي ولا يُؤذي أحدًا ولا يُزاحم.\nوهذا الحديث يُؤيد ذلك وإن كان ضعيفًا، لكن يُؤيد المعنى، والسنة أن النبي كان يقول: الله أكبر.\nس: زيادة: وهلِّل وكبِّر؟\nج: هذا حديث ضعيف، المعروف عن النبي ﷺ أنه كان يُكبِّر.","link":"https://binbaz.org.sa/fatwas/24982/هل-يشرع-التهليل-والتكبير-عند-الحجر-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله فاستقبله وهلِّل وكبِّر؟.mp3","categories":["الطواف بالبيت"]},{"id":4691,"question":"يستقبل الحجر بكل ......؟","title":"ما يصح وما لا يصح في استقبال الحجر الأسود","answer":"الجواب: يُقابله، يستقبل الحجر ويستلمه إذا تيسر، وإن أعطاه جنبه واستلمه ما في شيء، الأمر واسع.\nس: زيادة بسم الله؟\nج: كان يفعله ابنُ عمر : بسم الله، والله أكبر، الأمر واسع، ما أعرف شيئًا صحيحًا ثابتًا، إنما هو من فعل ابن عمر.\nس: في كل الأشواط أو في الأول؟\nج: في جميع الأشواط، أولها وآخرها، حتى الشوط الأخير، كلما حاذى يُكبر ثم ينتهي.\nس: السجود على الحجر ورد في هذا شيء؟\nج: السجود على الحجر ورد في بعض الأحاديث، لا بأس به، فيه مرفوع وموقوف على ابن عباسٍ، ولكن الأحاديث الثابتة فيها التَّقبيل، يكفي التَّقبيل.\nس:  التَّسمية في الشوط الأول من فعل ابن عمر؟\nج: نعم، كان يفعله ابنُ عمر، والظاهر أنه يفعله عند كل شوطٍ، وأما الأحاديث الثابتة فيها التَّكبير.","link":"https://binbaz.org.sa/fatwas/24983/ما-يصح-وما-لا-يصح-في-استقبال-الحجر-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استقبال الحجر الأسود والسجود عليه.mp3","categories":["الطواف بالبيت"]},{"id":4692,"question":"هل يُشير  ويُكَبّر عند الركن اليماني مَنْ لم يستلمه؟","title":"هل يُشار للركن اليماني إذا لم يتيسر استلامه؟","answer":"الجواب: يشير إلى الحجر الأسود فقط. ما ثبت عنه ﷺ إلى اليماني، اليماني ما يُشير إليه، إن تيسر استلمه وإلا مشى، ما ثبتت عن النبي الإشارة إلا عند الحجر الأسود.\nس: هل يُكبر في الركن اليماني؟\nج: يُكبر إذا استلمه، وإذا ما استلمه يمشي، ورد عند الطبراني بسندٍ جيدٍ: أنه كان إذا استلم الركن اليماني قال: بسم الله، والله أكبر.","link":"https://binbaz.org.sa/fatwas/24984/هل-يشار-للركن-اليماني-اذا-لم-يتيسر-استلامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُشير للركن اليماني إذا لم يتيسر استلامه، ويُكبر.mp3","categories":["الطواف بالبيت"]},{"id":4693,"question":"لو بدا شيء من العورة مع الزحام في الطواف.. هل يُؤثر على الطَّواف؟","title":"حكم انكشاف شيء من العورة في الطواف","answer":"الجواب: الشيء القليل يُعفى عنه ... مثل الصلاة.","link":"https://binbaz.org.sa/fatwas/24985/حكم-انكشاف-شيء-من-العورة-في-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/انكشاف شيء من العورة في الطواف هل يُؤثر على الطَّواف.mp3","categories":["الطواف بالبيت"]},{"id":4696,"question":"في الطواف والسعي بعض الناس يأخذون كتيبات ويُرددونها بصوتٍ جماعي ..؟","title":"حكم الدعاء جهرًا من كتاب في الطواف والسعي","answer":"الجواب: الأحسن أن الإنسان يدعو ربَّه بينه وبين نفسه، لا يُشوش على الناس، ولو معه كتاب يقرأه بينه وبين نفسه، لا يُشوش على الطائفين .......، فإذا تيسر أن يقرأ من نفسه، من كتاب، من شيء بيده، أو يقرأ ما تيسر من حفظه: سبحان الله، والحمد لله، ولا إله إلا الله، أولى من التشويش على الناس، ويكفي: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، إذا كرر هذه في الطواف هذا خير عظيم، أو دعا: اللهم اغفر لي، اللهم ارحمني، اللهم أعتقني من النار، اللهم اغفر لي ولوالدي، اللهم انصر دينك وكتابك وعبادك المؤمنين، يدعو ولا يتكلَّف والحمد لله، ما له حاجة إلى الدَّعوات الكثيرة التي يكتبونها هم ويشغلون بها الناس في الطواف، ما تيسر يكفي من ذكر الله.\nس: يكون هذا الشيء بدعةً؟\nج: الأمر واسع.","link":"https://binbaz.org.sa/fatwas/24988/حكم-الدعاء-جهرا-من-كتاب-في-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء من كتاب في الطواف والسعي، وبصوت جماعي.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":4698,"question":"يلزمه إعادة الوضوء مع الزحام الشَّديد؟","title":"هل يجب الوضوء على من أحدث أثناء الطواف؟","answer":"الجواب: لماذا؟\nس: أحدث.\nج: يُعيد الوضوء، سواء زحام أو ما هو بزحام يُعيد الوضوء، مثل الذي أحدث في الصلاة يُعيد الصلاة.","link":"https://binbaz.org.sa/fatwas/24990/هل-يجب-الوضوء-على-من-احدث-اثناء-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أحدث أثناء الطواف، فيلزم إعادة الوضوء.mp3","categories":["ما يشرع له الوضوء","الطواف بالبيت"]},{"id":4699,"question":"إذا لم يتيسر له استلام الحجر؟","title":"ما يفعل مَنْ لم يتيسر له استلام الحَجَر؟","answer":"الجواب: يُشير ويُكبر بيده أو بعصا، كما فعل النبيُّ ﷺ.","link":"https://binbaz.org.sa/fatwas/24991/ما-يفعل-من-لم-يتيسر-له-استلام-الحجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا لم يتيسر استلام الحجر.mp3","categories":["الطواف بالبيت"]},{"id":4700,"question":"ركعتا الطواف تُجزئ عنها الرَّاتبة؟","title":"هل تُجزئ الرَّاتبة عن ركعتي الطواف؟","answer":"الجواب: لا، سنة مستقلة؛ ولهذا قال الزهري: السنة أفضل مما قال بعضُ الناس....، السنة أن يُصلي ركعتين مُستقلتين.\nس: ... واجبة أم سنة؟\nج: المعروف عند العلماء أنهما سنة، والقول بالوجوب قول قوي، لكن المعروف عند أهل العلم أنهما سنة؛ لقول النبي ﷺ لما سأله بعضُ الصحابة لما ذكر الصَّلوات الخمس قال: هل عليَّ غيرها؟ قال: لا، إلا أن تطوع.","link":"https://binbaz.org.sa/fatwas/24992/هل-تجزى-الراتبة-عن-ركعتي-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُجزئ الرَّاتبة عن ركعتي الطواف.mp3","categories":["الطواف بالبيت"]},{"id":4701,"question":"مَن ركب حال السعي والطواف من غير حاجةٍ ماذا عليه؟","title":"حكم الركوب في السعي والطواف بغير حاجةٍ","answer":"الجواب: الطواف صحيح، والسعي صحيح؛ لأنَّ النبي طاف وهو صحيح، أما حديث ابن عباسٍ أنه اشتكى فهو ضعيف، حديث ابن عباس أنه اشتكى فركب ضعيف، فيه يزيد بن أبي زياد، والصواب أنه ركب لدفع المشقَّة عن الناس؛ لئلا يتأذَّوا أو يُؤذوه.\nس: الشخص العادي الذي يطوف راكبًا من غير سببٍ؟\nج: يُعلَّم أن السنة الطواف ماشيًا.\nوفيه من الفوائد: طهارة البعير، وأنَّ روثه طاهر، وبوله طاهر، البعير لا حرج فيه، ولكن إذا تيسر أن يطوف ماشيًا فهذا هو السنة كما طاف النبيُّ عليه الصلاة والسلام ماشيًا.","link":"https://binbaz.org.sa/fatwas/24993/حكم-الركوب-في-السعي-والطواف-بغير-حاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الركوب حال السعي والطواف من غير حاجةٍ.mp3","categories":["الطواف بالبيت","السعي","الأدعية والأذكار"]},{"id":4703,"question":"رفع اليدين والدعاء حتى في آخر شوطٍ؟","title":"حكم رفع اليدين في الدعاء بالطواف والسعي","answer":"الجواب: نعم، حتى في آخر شوطٍ في الطواف والسعي، كله، في الطواف يرفع يديه ويُكبر في آخر شوطٍ عند الخاتمة، وفي السعي كذلك عند المروة في آخر شوطٍ يرفع يديه ويدعو.","link":"https://binbaz.org.sa/fatwas/24995/حكم-رفع-اليدين-في-الدعاء-بالطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع اليدين والدعاء في الطواف والسعي.mp3","categories":["الطواف بالبيت","السعي","الأدعية والأذكار"]},{"id":4844,"question":"قلتُم في الدرس الأحد الماضي أنه لا يجوز الطواف على ما يجوز أكل لحمه: من إبل، أو بقر، أو أحصنة، لا يجوز الطواف على الحمار؟","title":"ما صفة الحيوان الذي يجوز الطواف فوقه؟","answer":"لا، لا، يطوف على البعير، والبقرة، والفرس، التي بولها طاهر، أما الحمار فقد يبول وينجس المسجد.","link":"https://binbaz.org.sa/fatwas/25287/ما-صفة-الحيوان-الذي-يجوز-الطواف-فوقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الطواف على ما يجوز أكل لحمه.mp3","categories":["الطواف بالبيت"]},{"id":5190,"question":"هل على أهل جدة طواف وداع؟ وما الدليل؟","title":"هل على أهل جدة طواف وداع؟ وما الدليل؟","answer":"الجواب: نعم؛ لأنَّهم ليسوا من أهل الحرم، وليسوا في حكم أهل الحرم، والنبي عليه الصلاة والسلام يقول: لا يَنْفِرَنَّ أحدٌ منكم حتى يكون آخر عهده بالبيت رواه مسلم، ويقول ابن عباس: \"أُمر الناس أن يكون آخر عهدهم بالبيت، إلَّا أنه خفَّف عن المرأة الحائض\". فأهل جدة وأهل الطائف ليسوا من أهل مكة، ليسوا من أهل الحرم، فإذا أرادوا النَّفير من الحج فعليهم الوداع، أما العمرة فأمرها أوسع وأسهل، إن ودَّعوا فهو أحسن، وإن لم يُودعوا فالصواب أنه لا يجب الوداع في العمرة، ولكنه يجب في الحج على الصحيح.","link":"https://binbaz.org.sa/fatwas/30132/هل-على-اهل-جدة-طواف-وداع-وما-الدليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 159.mp3","categories":["الطواف بالبيت"]},{"id":5616,"question":"رجل اعتمر وبدأ بالطواف من الركن اليماني وانتهى عنده، فماذا عليه؟","title":"حكم مَن بدأ طوافه مِن الركن اليماني وانتهى به","answer":"الجواب: عليه أن يُعيد الطواف إن كان طال الفصل، وإن كان الفصل قليلًا يزيد شوطًا بدل الشوط الذي تركه ما بين الركنين، أما إن طال الفصل فعليه أن يُعيد الطواف؛ لأنه ما طاف إلا ستة. س: لكن لو سافر؟ ج: يرجع، عليه أن يرجع إذا كان الطواف واجبًا لعمرةٍ أو حجٍّ، أما إن كان الطواف تطوعًا فأمره سهل. س: طواف عمرة؟ ج: إن كان طواف عمرةٍ أو طواف حجٍّ عليه أن يرجع، لا يزال مُحرمًا حتى يرجع، وإن جامع عليه كفَّارة الجماع، لا يزال مُحرمًا حتى يرجع. س: وإن سافر فعليه الرجوع؟ ج: ولو، الله أوجب عليه: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196]. س: ولو كان في بلدٍ خارج؟ ج: ولو أنه في أمريكا يرجع. س: أو يُنيب إذا لم يستطع؟ ج: لا، يكون محصرًا، يكون من باب المحصر، إذا لم يتيسر يكون محصرًا، يستعمل ما يستعمله المحصر؛ ينحر هديًا، ويقصر أو يحلق ويحلّ، ويبقى الحجُّ في ذمته أو العمرة إن كانت عمرة الإسلام، أو حج الإسلام. س: ينحر الهدي في محلِّه؟ ج: في محله، النبي ﷺ نحره في محلِّه في الحلِّ.[1]","link":"https://binbaz.org.sa/fatwas/31585/حكم-من-بدا-طوافه-من-الركن-اليماني-وانتهى-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 056.mp3","categories":["الطواف بالبيت"]},{"id":5753,"question":"امرأة حجت متمتعة، وبعد أن قضت العمرة حاضت، وبعد الإفاضة من عرفات طافت بالبيت وهي حائض، فماذا عليها وهي في الثامنة عشرة من عمرها؟","title":"من طافت الإفاضة وهي حائض","answer":"الجواب: عليها أن تعيد الطواف، إذا طافت الحائض تعيد الطواف بنية الحج السابق، تعود إلى مكة مع محرمها، وتطوف طواف الحج بنية الحج السابق الذي مضى، تطوف بطهارة.","link":"https://binbaz.org.sa/fatwas/1095/من-طافت-الافاضة-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_101.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":5765,"question":"رجل حج، وبعد فراغه من رمي الجمرات في يوم العيد، واليوم الحادي عشر، والثاني عشر، والثالث عشر ذهب إلى الحرم، وطاف وسعى بالحج، وخرج مباشرة دون أن يودع؛ معتقدًا جواز اكتفائه بطواف الحج، فما حكم ذلك؟","title":"من ترك طواف الوداع للحاج","answer":"الجواب: قد صرح العلماء بأن الرجل إذا طاف آخر الليل كفاه عن طواف الوداع، إذا أخر طواف الزيارة، وطاف بعد فراغه من الرمي كله، ثم سافر في الحال؛ أجزأه ذلك، لعموم قول النبي ﷺ: لا ينفرن أحد منكم حتى يكون آخر عهده بالبيت رواه مسلم في الصحيح.  وللحديث الثاني: حديث ابن عباس، الثاني قال: \"أمر الناس -يعني أمرهم النبي- أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فإذا كان آخر عهده بالبيت فلا بأس. والحائض لا وداع عليها، والنفساء كذلك لا وداع عليها، لكن هو إذا طاف، أو طافت المرأة غير الحائض، والنفساء، طافت عند الخروج، طواف الخروج، طواف الإفاضة، طواف الحج، ولو كان معه السعي؛ فإنه يجزئه، ولا يحتاج إلى وداع ثاني، وإن طافت للوداع طواف آخر، طواف الحج، ثم الوداع؛ كان أكمل، وأفضل.","link":"https://binbaz.org.sa/fatwas/1096/من-ترك-طواف-الوداع-للحاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_102.mp3","categories":["الطواف بالبيت"]},{"id":5769,"question":"امرأة حجت متمتعة، وبعد أن قضت العمرة حاضت، وبعد الإفاضة من عرفات طافت بالبيت وهي حائض، فماذا عليها وهي في الثامنة عشرة من عمرها؟","title":"من طافت الإفاضة وهي حائض","answer":"الجواب: عليها أن تعيد الطواف، إذا طافت الحائض تعيد الطواف بنية الحج السابق، تعود إلى مكة مع محرمها، وتطوف طواف الحج بنية الحج السابق الذي مضى، تطوف بطهارة.","link":"https://binbaz.org.sa/fatwas/1095/من-طافت-الافاضة-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_101.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":5780,"question":"ما حكم دعاء الملتزم، والتشبث بأستار الكعبة؟","title":"حكم الدعاء في الملتزم والتشبث بأستار الكعبة","answer":"الجواب: دعاء الملتزم لا بأس به، فعله كثير من الصحابة، وروي عن النبي ﷺ أنه فعله، ولكن في سنده نظر، ولكن فعله بعض الصحابة، وهو ما بين الركن، والباب إن كان يقف فيه، ويدعو ربه لا بأس بهذا، ترجى فيه الإجابة. أما التشبث بأستار الكعبة فلا نعلم له أصلًا، والذي ينبغي ترك ذلك، إنما فعل النبي ﷺ في داخل الكعبة لما دخلها ألصق صدره ويديه في جدارها، ودعا ربه، وكبر.  كما روى أسامة بن زيد وروى ابن عباس أنه دار فيها وكبر ودعا، وروى ابن عمر أنه صلى فيها ركعتين عن بلال، صلى فيها ركعتين، هذا سنة من داخلها صلى فيها ودعا وكبر فعله النبي ﷺ.  أما من خارج فلا نعلم له أصلًا إلا عند الملتزم، وإذا دعا في أي منحى فلا بأس، أما كونه يتشبث بالكسوة، أو يتمسك بالكسوة، ويظن أن هذا فيه بركة، فهذا لا أصل له، لا نعلم له أصلًا.","link":"https://binbaz.org.sa/fatwas/1106/حكم-الدعاء-في-الملتزم-والتشبث-باستار-الكعبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_112.mp3","categories":["الأدعية والأذكار","الطواف بالبيت"]},{"id":5792,"question":"يا شيخ، عفا الله عنك، صليت المغرب، وذهبت في سيارة أنا وربع معي، وجاء علينا وقت المغرب، فقلت لهم وقفوا نصلي، فوقفنا نصلي، وصليت، وبعد أن صليت تذكرت أني لست على وضوء، وبعد أن رجعت إلى البيت توضأت وصليت، فقال لي أناس: لا تصلي حتى يأتي المغرب عليك، وصلي، وأنا عصيتهم وصليت، وقدمت المغرب؟","title":"من صلى ثم تذكر بعدها أنه على غير طهارة","answer":"الجواب: أحسنت وأخطؤوا، من قال لك: أن ما تصلي المغرب إلا في المغرب الآخر، وما بين الوقتين صلاة، فهذا غلط، فإذا صليت مع الناس، ثم تبين لك... تعيدها في الحال، تتوضأ، وتعيدها في الحال، النبي ﷺ قال: من نام عن الصلاة، أو نسيها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك هذا فرض، والله قال: وَأَقِمِ الصَّلَاةَ لِذِكْرِي [طه:14].  فالحاصل: أن الإنسان إذا صلى وهو على حدث، ثم تنبه؛ يبادر بالصلاة، يتوضأ ويبادر، أو استيقظ وقد خرج الوقت يبادر، ثم يصلي، ولا يؤخر ولا يؤجل. لكن المسافرين إذا حضر وقت المغرب، وهم في السيارة مسافرون، الأفضل ما ينزلون، الأفضل أن يؤجلوا المغرب مع العشاء هذا الأفضل، كان النبي ﷺ إذا ارتحل قبل دخول المغرب أجل المغرب مع العشاء، وإذا ارتحل قبل الزوال أجل الظهر مع العصر، يجمعها مع العصر.  وهكذا المغرب إذا ارتحل إنسان من مكانه على السيارة، أو على الدابة قبل الغروب يؤجل صلاة المغرب، ما ينزلون ويصلوا المغرب لا، يأجلها مع العشاء هذا السنة.","link":"https://binbaz.org.sa/fatwas/1118/من-صلى-ثم-تذكر-بعدها-انه-على-غير-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_125.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":6273,"question":"ترك طواف الوداع جاهلاً؟","title":"حكم من ترك طواف الوداع جاهلاً","answer":"الجواب:  عليه أن يرجع، فيطوف للوداع، أو يذبح شاة في مكة للفقراء، والمساكين عن ترك الواجب؛ لأن طواف الوداع واجب من واجبات الحج، فإذا تركه إما أن يعود، ويجزئه -إن شاء الله- على أرجح القولين، وإن فدى، وذبح في مكة عن تركه الوداع  كذلك يجزئه، كما لو ترك الجمار، وذبح الدم أجزأه.  لكن لا يتعمد تركه، لا يجوز له تعمد تركه، بل يأثم إذا تعمد ترك الجمار، أو ترك شيء منها، أو ترك الوداع، لا يجوز له ذلك، يأثم، لكن لو فعل، وفات الوقت؛ فإنه عليه الدم. وهكذا لو ترك الوداع عامدًا فإنه يأثم، أو جاهلاً، أو ناسيًا؛ فإنه يرجع، فيأتي به، أو يفدي عن ذلك شاة معز قد تم لها سنة، أو من الضأن تم له ستة أشهر مثل الضحية.","link":"https://binbaz.org.sa/fatwas/1778/حكم-من-ترك-طواف-الوداع-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_617.mp3","categories":["الأدعية والأذكار","الطواف بالبيت"]},{"id":6310,"question":"هل يجوز لرجل كان عليه غسل جنابة أن يتيمم، ويترك الصلاة، ويوجد الماء، مع العلم أنه إذا اغتسل؛ سوف تفوته صلاة الجماعة، ولم يفته وقت الصلاة؟","title":"حكم تيمم الجنب مع وجود الماء لكي يدرك الجماعة","answer":"الجواب: إذا كان عليه غسل الجنابة؛ يغتسل، ولا يتيمم، ولا يجوز له التيمم، بل يبطل التيمم إذا كان الماء موجودًا، وهو يقدر على استعماله، فيلزمه الغسل، ولو فاتته الجماعة، لو قدر أنه كان .. إذا اغتسل تفوته الجماعة، وإذا تيمم لا تفوته الجماعة لا، لا يتيمم، يغتسل بالماء، ويصلي، ولو في بيته إن ما تيسر له الجماعة. ولكن يجب عليه أن يجعل هناك وقتًا واسعًا، أو يضبط الساعة على وقت واسع، أو يقول للذين يوقظونه قبل الفجر حتى يتمكن من الغسل، والصلاة مع الجماعة، لا يتساهل، والناس -بحمد الله- عندهم ساعات، الآن تيسرت الساعات، يوقتها على الوقت المناسب؛ حتى يقوم في وقت مبكر، ويغتسل على هدوء، ويصلي ما كتب الله له، ثم يتوجه لصلاة الجماعة، هذا الواجب عليه، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1871/حكم-تيمم-الجنب-مع-وجود-الماء-لكي-يدرك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_661.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":6330,"question":"هل يجوز لرجل كان عليه غسل جنابة أن يتيمم، ويترك الصلاة، ويوجد الماء، مع العلم أنه إذا اغتسل؛ سوف تفوته صلاة الجماعة، ولم يفته وقت الصلاة؟","title":"حكم تيمم الجنب مع وجود الماء لكي يدرك الجماعة","answer":"الجواب: إذا كان عليه غسل الجنابة؛ يغتسل، ولا يتيمم، ولا يجوز له التيمم، بل يبطل التيمم إذا كان الماء موجودًا، وهو يقدر على استعماله، فيلزمه الغسل، ولو فاتته الجماعة، لو قدر أنه كان .. إذا اغتسل تفوته الجماعة، وإذا تيمم لا تفوته الجماعة لا، لا يتيمم، يغتسل بالماء، ويصلي، ولو في بيته إن ما تيسر له الجماعة. ولكن يجب عليه أن يجعل هناك وقتًا واسعًا، أو يضبط الساعة على وقت واسع، أو يقول للذين يوقظونه قبل الفجر حتى يتمكن من الغسل، والصلاة مع الجماعة، لا يتساهل، والناس -بحمد الله- عندهم ساعات، الآن تيسرت الساعات، يوقتها على الوقت المناسب؛ حتى يقوم في وقت مبكر، ويغتسل على هدوء، ويصلي ما كتب الله له، ثم يتوجه لصلاة الجماعة، هذا الواجب عليه، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1871/حكم-تيمم-الجنب-مع-وجود-الماء-لكي-يدرك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_661.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":6724,"question":"ما رأي سماحتكم فيمن أدى فريضة الحج، ولم يطف طواف الوداع، وكان هذا في العام الماضي؟","title":"حكم حج ولم يطف طواف الوداع","answer":"الجواب: الذي حج، ولم يطف طواف الوداع؛ عليه دم يذبح في مكة للفقراء؛ لأن طواف الوداع واجب للحج، فإذا ضيعه، ولم يأت به، وسافر؛ يذبح عنه ذبيحة من الغنم، أو سبع من الإبل، أو البقر في مكة، يقسم بين الفقراء هناك.","link":"https://binbaz.org.sa/fatwas/2596/حكم-حج-ولم-يطف-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1092.mp3","categories":["الأدعية والأذكار","الطواف بالبيت"]},{"id":6997,"question":"امرأة ذهبت لأداء العمرة، وقبل أن تأتي مكة أتتها الدورة الشهرية، وطافت، وسعت وهي بهذا، فهل عليها كفارة، وهل عمرتها صحيحة، وإذا كان عليها كفارة، فما نوعها؟","title":"حكم طواف العمرة للحائض","answer":"الجواب:\n\nلا زالت في العمرة حتى ترجع، وتطوف، وتسعى، لا زالت في العمرة؛ لأن الطواف لا يكون مع الحيض، فإذا جاءت العمرة، وأصابها الحيض؛ تبقى حتى تطهر، ثم تطوف، ثم تسعى، وتؤدي العمرة بذلك، تقصر من رأسها، وتمت العمرة، العمرة طواف، وسعي، بعد الإحرام طواف، وسعي، وتقصير من رأسها، والرجل إن شاء قصر، وإن شاء حلق، هذه العمرة، فإذا وصلت إلى مكة، وجاءتها الدورة؛ تبقى حتى تطهر، فإذا طهرت؛ طافت، وسعت، وقصرت من رأسها، وتمت عمرتها.\n\nالسؤال: يعني الطواف هذا لا يقبل؟\n\nالجواب: ما يقبل لا، عليها أن ترجع إلى مكة، وتؤدي الطواف، ثم التقصير، وأما السعي فيجزئها -إن شاء الله-.\n\nالسؤال: يعني ليس عليها دم؟ \n\nالجواب: ما عليها دم، عليها أن ترجع.\n\nالسؤال: ولو كان أتاها الزوج؟\n\nالجواب: إذا أتاها زوجها؛ فسدت العمرة، وعليها أن ترجع، وتؤدي العمرة كاملة، وعليها أن تقضي عمرة جديدة، زيادة من إحرامها من الميقات الذي أحرمت منه، إذا أتاها الزوج؛ بطلت العمرة، فسدت، ولكن عليها مع هذا أن تكملها عمرة فاسدة، عليها أن ترجع، وتطوف، وتكمل عمرتها، ثم بعد ذلك تقضي عمرة جديدة ليس فيها وطء بطواف، وسعي، وتقصير بدلًا من عمرتها التي فسدت بالجماع، كما أفتى بهذا أصحاب النبي -عليه الصلاة والسلام-.\n\nالسؤال: ما عليها دم في العمرة الأولى؟\n\nالجواب: عليها شاة، دم شاة تذبح في مكة للفقراء، عليها دم عن الجماع.\n\nالسؤال: بعض النساء ..؟\n\nالجواب: تغتسل، أو تتعاطى دواء يزيل الدم، إذا انقطع الدم، أو انقطعت الدورة تغتسل، وتطوف -والحمد لله- وتصلي. \n\nالسؤال: لا العمرة الوقت فيها؟\n\nالجواب: حتى العمرة، والحج\n\nالسؤال: خارج العمرة، وخارج الحج في الأيام العادية؟","link":"https://binbaz.org.sa/fatwas/2922/حكم-طواف-العمرة-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1370.mp3","categories":["الطواف بالبيت","الحيض والنفاس","قضايا المرأة"]},{"id":7112,"question":"طواف الحج بدون وضوء؟","title":"حكم الطواف في الحج بدون وضوء","answer":"الجواب:\n\nالذي طاف بدون وضوء عليه أن يعيد الطواف إن كان الطواف واجبًا، مثل طواف الإفاضة، أو طواف الوداع، أو طواف العمرة، عليه دم إذا كان طواف الوداع، عليه أن يعيد، يرجع إلى مكة، ويطوف طواف الحج، يطوف بنية الحج الذي أحدث في طوافه، وعليه دم إن كان عنده زوجة وأتاها، يذبح في مكة، وإن كان ما عنده زوجة ،ولا فعل شيئًا؛ فعليه أن يعود بدون إحرام؛ لأنه قد حل برمي الجمرة والتقصير، ليس عليه إحرام؛ لأنه قد حل بالرمي والحلق أو التقصير، لكن لو أحرم، وأتى بعمرة طيب، لو أحرم، وأتى بعمرة، وطاف في الحج بنية الحج السابق.\n\nالسؤال: يبدل العمرة؟\n\nالجواب: إن بدل العمرة فلا بأس، وإن بدل طواف الحج فلا بأس، الأمر واحد.\n\nالسؤال: لو أنه رمى الجمرة، ثم نزل للطواف مباشرة، عاكسًا الترتيب، ما يلزمه أن ..؟ \n\nالجواب: لا، ما يلزمه، ما دام قصر؛ حل التحلل الأول.\n\nالسؤال: لعله لم يكن قصر، أو بدأ بالطواف؟\n\nالجواب: ما عندنا قول بأن الجمرة الواحدة تكفي، تكفي عند جمع من أهل العلم، جاء في أحاديث، على كل حال مادام رمى الجمرة إنما يأتي بغير إحرام، وإذا كان رمى، وقصر، وحلق؛ كذلك من باب أولى.","link":"https://binbaz.org.sa/fatwas/3141/حكم-الطواف-في-الحج-بدون-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1499.mp3","categories":["الأدعية والأذكار","الطواف بالبيت"]},{"id":7425,"question":"الطواف عن الميت هل هو جائز؟","title":"حكم الطواف عن الميت أو الحي","answer":"الجواب: ما له أصل، لا، مثل الصلاة عن الميت الأظهر أنه لا يصلح، أما عمرة تامة وحج تام فلا بأس. السؤال: والحي؟ الجواب: والحي كذلك، ذكره بعض الفقهاء، ولكن ما عليه دليل، والطواف من جنس الصلاة، فلا يطاف إلا بدليل، ولا يصلى إلا بدليل، لا يطاف عنه، لا يصل أحد عن أحد، لكن لو اعتمر عنه عمرة كاملة أو حج عنه حجًا كاملًا وهو ميت، أو عاجز كالشيخ الهرم، والعجوز الهرمة.","link":"https://binbaz.org.sa/fatwas/3511/حكم-الطواف-عن-الميت-او-الحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1815.mp3","categories":["الأدعية والأذكار","الطواف بالبيت"]},{"id":7534,"question":"سؤاله الأخير يقول: هل العمرة للمتمتع والقارن هي نفس طواف القدوم؟ أعتقد أنه يريد هل الطواف للعمرة للمتمتع والقارن هل هو نفس طواف القدوم؟","title":"هل الطواف للمتمتع والقارن هل هو نفس طواف القدوم؟","answer":"الجواب: إذا كان قارناً فطوافه طواف قدوم، والعمرة قد دخلت في الحج، كما قال النبي ﷺ: دخلت العمرة في الحج إلى يوم القيامة، فإذا أحرم بهما جميعاً وقدم يطوف ويسعى، ويعتبر الطواف طواف القدوم، والسعي سعي الحج، ويبقى على إحرامه إذا كان معه هدي؛ من إبل، أو بقر، أو غنم، يبقى على إحرامه إلى الحج، فإذا جاء يوم عرفة فوقف بعرفات، ثم يوم العيد يرمي الجمرة؛ جمرة العقبة، ويحلق أو يقصر، ويحصل التحلل الأول، ثم يطوف حينئذ، ويكون بذلك قد أدى الحج والعمرة جميعاً، وأجزأه السعي السابق، وطوافه الأول طواف قدوم، هذا إذا كان قارناً؛ وهو الذي أحرم بالحج والعمرة جميعاً، وبقي على إحرامه، إما لأنه ساق الهدي، أو لأنه رأى أن هذا جائز ففعله واستمر على إحرامه، فإن هذا طوافه الأول يعتبر طواف قدوم، والعمرة دخلت في الحج، وصار الحكم للحج، والسعي هو سعي الحج مقدماً، وطواف الحج يكون بعد عرفات يوم العيد متأخراً طواف الحج، يوم العيد أو بعده، هذا طواف الحج، بخلاف من أحرم بالعمرة وحدها، فإن طواف القدوم هو طواف العمرة يجزئه، يكون طواف قدوم وطواف عمرة واحداً، فيطوف سبعة أشواط ويكفيه عن العمرة وعن القدوم، ولا يحتاج إلى طوافين: طواف القدوم، وطواف العمرة، إذا كانت العمرة مفردة. نعم.\nالمقدم: طيب إذا اعتمر متمتعاً، ... حج متمتعاً؟\nالشيخ: إذا كان اعتمر متمتعاً فكذلك عمرة مفردة، طوافها هو طواف القدوم يكفي.","link":"https://binbaz.org.sa/fatwas/4520/هل-الطواف-للمتمتع-والقارن-هل-هو-نفس-طواف-القدوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_011/01105.mp3","categories":["الطواف بالبيت"]},{"id":7538,"question":"هذه الرسالة لم يذكر صاحبها اسمه يقول: ما حكم الشك في الطواف، هل هو كامل أو ناقص أو زائد، أفيدونا وفقكم الله؟","title":"الشك في عدد الطواف","answer":"الجواب: الشك في الطواف مثل الشك في الصلاة، فإذا شك هل طاف شوطين أو ثلاثة؟ يجعلها شوطين، وإذا شك هل طاف ثلاثة أو أربعة؟ يجعلها ثلاثة، وإذا شك هل هلي ستة أو سبعة؟ يجعلها ستة ويأتي بالسابع، يعني: يبني على اليقين، حتى يكمل السبع بيقين، هذا الواجب عليه.","link":"https://binbaz.org.sa/fatwas/4524/الشك-في-عدد-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_011/01108.mp3","categories":["الطواف بالبيت"]},{"id":7544,"question":"الآن نحب أن نعرض هذه الأسئلة التي تتعلق بالحج، هذه الرسالة من ثامر السلوي، والسيد عواد البيشي، وسلطان الجادي، وكلهم من الرياض، يقولون: سمعنا أن تحية المسجد الحرام هو الطواف حول البيت، ونحن نقيم عدة أيام بعد العمرة وقبل الحج، ونكثر زيارة البيت لكن يشق علينا الطواف كلما دخلنا البيت؛ لأننا نكرر دخوله في اليوم الواحد، والبيت مزدحم أحياناً، فهل نكتفي بركعتين كتحية للمسجد، أفيدونا أفادكم الله؟","title":"حكم من شق عليه الطواف كلما دخل الحرم","answer":"الجواب: نعم، الطواف هو تحية المسجد، المسجد الحرام إذا تيسر ذلك، فإذا لم يتيسر ذلك بأن كان زحام، وكان الرجل ليس عنده النشاط الكافي إنما يصلي ركعتين مثل بقية المساجد، يصلي ركعتين تحية المسجد يكفي، وليس هناك حاجة إلى الطواف، لكن إذا تيسر الطواف فهو أفضل، يعني كونه يطوف كلما دخل حتى يدرك فضل الطواف هذا خير كثير، ولكن إذا شق عليه ذلك، أو وجد الزحام، أو كان عنده فتور، أو لم ينشط لهذا الشيء، المقصود ما هو بواجب ليس بلازم، إنما الواجب طواف العمرة، وطواف الحج، وطواف الوداع، بس، هذه ثلاثة:\nطواف العمرة أول ما يقدم.\nطواف الحج بعد النزول من عرفات يوم العيد وبعده.\nوالثالث: طواف الوداع عند الخروج.\nهذه الأطوفة الواجبة الثلاثة، أما بقية الأطوفة فهي مستحبة ليست بواجبة، فإذا جاء دخل المسجد يصلي الظهر أو العصر أو المغرب، إن تيسر له الطواف طاف وإلا صلى ركعتين، ليس بلازم أن يطوف، يصلي ركعتين مثل بقية المساجد. نعم.","link":"https://binbaz.org.sa/fatwas/4530/حكم-من-شق-عليه-الطواف-كلما-دخل-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_012/01203.mp3","categories":["الطواف بالبيت"]},{"id":7545,"question":"بالنسبة للطواف، لو طاف طواف الوداع وبات في مكة، هل يلزمه أن يعيد الطواف، أو يخرج بدون إعادة؟","title":"حكم من طاف للوداع وبات في مكة","answer":"الجواب: إذا طاف في أول الليل وبات، الأولى له أن يعيد الطواف خروجاً من خلاف العلماء، ينبغي أن يعيد الطواف، فإن جهل وخرج لا شيء عليه إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/4531/حكم-من-طاف-للوداع-وبات-في-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_012/01204.mp3","categories":["الطواف بالبيت"]},{"id":7548,"question":"سؤال زين الدين الثاني يقول: إذا طاف الإنسان طواف الوداع لا يجوز له أن يشتري شيئاً، لكن ما المقصود بهذا الشيء، هل هو المخصص للتجارة، أو يشمل حاجة الإنسان من هدايا للأهل والأصدقاء، وما يلزمه من أثاث للسفر؟","title":"شراء الهدايا ولوازم السفر بعد طواف الوداع","answer":"الجواب: السنة أن يكون طواف الوداع بعد كل شيء إذا انتهى من كل شيء وفرغ من أشغاله كلها، يطوف للوداع، هذا هو الأفضل، يكون هو آخر شيء، يودع البيت ثم يمشي، يسافر، لكن لو ودع ثم اشترى بعض الحاجات كزاد السفر، أو هدايا، أو ما أشبه ذلك، لا حرج عليه، وإن اتجر، بعض أهل العلم يرى أنه يعيد الطواف ولكن ليس بجيد، لو اشترى سلعة للتجارة ولم تعقه بل هو في طريقه، فالصواب أن هذا لا يؤثر عليه، كما لو اشترى حاجة لنفسه أو هدايا، كل هذا لا يؤثر، ما دام في الطريق أو بعد مدة يسيرة من الطواف ما تأخر كثيراً، فهذا لا يضره وطوافه ماشي، وليس عليه إعادة الطواف. نعم.","link":"https://binbaz.org.sa/fatwas/4535/شراء-الهدايا-ولوازم-السفر-بعد-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_012/01207.mp3","categories":["الطواف بالبيت"]},{"id":7549,"question":"أيضاً عنده ملحوظة يقول: هل لطواف الوداع من سنة عند المقام أم لا؟","title":"سنة الطواف","answer":"الجواب: مثل غيره، طواف الوداع مثل غيره، كل طواف له سنة، كل طواف له سنة ركعتين خلف المقام إن تيسر، وإلا في بقية المسجد تكفي إذا صلاها في بقية المسجد؛ في الأروقة، أو في نهاية المطاف، لا بأس، هذا كل طواف، ما يخص طواف القدوم ولا طواف الحج ولا طواف الوداع، كل الطوافات كلها. نعم.","link":"https://binbaz.org.sa/fatwas/4536/سنة-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_012/01208.mp3","categories":["الطواف بالبيت"]},{"id":7822,"question":"يقول السائل يا سماحة الشيخ: هل يجوز بعد نفرة عرفة والمبيت في المزدلفة ومغادرتها بعد منتصف الليل الذهاب إلى مكة المسجد الحرام لأداء طواف الإفاضة، أي: طواف الإفاضة قبل رمي جمرة العقبة الكبرى؟","title":"حكم طواف الإفاضة قبل رمي جمرة العقبة الكبرى","answer":"الجواب: لا حرج في ذلك، إذا انصرفوا من مزدلفة في النصف الأخير من الليل لا بأس أن يذهب إلى مكة للطواف كما فعلت أم سلمة بأمر النبي ﷺ، فإنها بعد المزدلفة ذهبت إلى مكة وطافت ثم رجعت إلى منى ورمت الجمرة، فلا حرج في ذلك، لكن الأفضل أن يبدأ بالرمي ثم الحلق أو التقصير، والمرأة ليس عليها إلا التقصير ثم الطواف بعده، هذا هو الأفضل.\nولكن لو ذهب إلى مكة وطاف قبل أن يرمي وقبل أن يحلق لا حرج في ذلك والحمد لله.\nالمقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/5207/حكم-طواف-الافاضة-قبل-رمي-جمرة-العقبة-الكبرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05125.mp3","categories":["الطواف بالبيت"]},{"id":7853,"question":"نبدأ برسالة عتيق بن سلمان العتيق من الرياض، يقول: حججنا ومعنا طالب علم، وكنا نثق به وتمتعنا في حجنا من السيل فطفنا وسعينا وبعد طواف الإفاضة لم نسع، فهل حجنا هذا صحيح أم لا، جزاكم الله عن المسلمين خير الجزاء؟","title":"من تمتع بالعمرة إلى الحج واكتفى بسعي العمرة فقط","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: المتمتع وهو الذي يحرم بالعمرة من الميقات ويفرغ منها ثم يحج من عامه هذا يسمى متمتع في اصطلاح العلماء، وهكذا من أحرم بهما جميعاً بالعمرة والحج جميعاً وبقي على إحرامه حتى حج يسمى متمتعاً أيضاً ويسمى قارناً عند أهل العلم، فهذان عليهما الهدي، هذا الذي أحرم بالعمرة من الميقات وتحلل منها ثم أحرم بالحج يسمى متمتعاً، وذاك الذي أحرم بهما جميعاً من الميقات، ميقات المدينة أو ميقات أهل نجد أو غيرهما واستمر على إحرامه حتى فرغ من حجه كلاهما عليه هدي، والسعي على الذي حل سعي ثاني، والذي لم يحل بل بقي على إحرامه حكمه حكم المفرد الذي حج حجاً مفرداً ليس عليه إلا سعي واحد، والحاصل أن الذي تمتع بالعمرة إلى الحج وتحلل من عمرته يسعى سعياً ثانياً لحجه والسعي الأول يكون لعمرته، هذا هو المشروع، والذي أفتاكم بأنكم لا تسعون أفتى بقول قاله بعض العلماء، ونسأل الله له العفو والمغفرة، ولكن الذي عليه جمهور أهل العلم وهو أرجح القولين أن المتمتع الذي فرغ من عمرته في أشهر الحج ثم أحرم بالحج في عامه أن عليه سعياً ثانياً لحجه والسعي الأول لعمرته، هذا هو المشروع وهذا هو الأرجح، هو أرجح القولين وعليه أكثر أهل العلم، فإذا سمعت -أيها السائل- هذا فعليك أن تسعى عن حجك السابق في هذا الوقت، لا بأس في هذا الوقت أو بعده، عليك أن تسعى عن حجك السابق، وعليك أن تذبح احتياطاً هدي عن جماعك لأهلك إذا كان عندك زوجة وجامعتها بعد الحج، تذبح هدياً في مكة عن جماعك لها قبل أن تسعى صدقة عن إتيانك لزوجتك، تكون في مكة في فقراء الحرم، هذا هو المشروع على سبيل الاحتياط والخروج من خلاف العلماء، وهو الذي دلت عليه السنة، فإن النبي ﷺ لما حج كان أصحابه ثلاثة أقسام: منهم من أحرم بالعمرة وتحلل منها، ومنهم من أحرم بالحج والعمرة جميعاً قارناً، ومنهم من أحرم بالحج وحده، فأمر النبي ﷺ الذين أحرموا بالحج وحده أو بالحج والعمرة جميعاً أن يجعلوها عمرة وأن يتحللوا فأجابوا وسمعوا وأطاعوا وتحللوا، إلا من كان معه الهدي فإنه بقي على إحرامه، وأمر الذين تحللوا من عمرتهم أن يسعوا سعياً ثانياً لحجهم بعدما رجعوا من منى كما رواه البخاري عن ابن عباس رضي الله عنهما، وكما جاء في الصحيحين من حديث عائشة رضي الله عنها أنها قالت: «وأما الذين حلوا من عمرتهم فطافوا طوافاً آخر لحجهم -يعني بين الصفا والمروة» فهذا هو المعتمد. نعم.","link":"https://binbaz.org.sa/fatwas/5243/من-تمتع-بالعمرة-الى-الحج-واكتفى-بسعي-العمرة-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_054/05401.mp3","categories":["الطواف بالبيت","السعي"]},{"id":8353,"question":"هذه رسالة وصلت إلى البرنامج من الأخ عوض بن سرور المطيري من مهد الذهب، أخونا يقول: أنا مواطن في المملكة العربية السعودية وأسكن في مكان قريباً بين مكة والمدينة، وقد قمت بأداء العمرة في شهر رمضان الفائت، وكان الوقت حول منتصف النهار، وبعد أن ذهبت لأحد أصدقائي بمكة وبقيت حتى أفطرت ثم عدت عائداً إلى مسكني، بعد رجوعي أخبرني مجموعة من إخواني بأنه كان يتوجب علي أن أعود مرة أخرى لوداع البيت الحرام، فما رأي أهل العلم في ذلك؟ وما الحكم؟","title":"حكم طواف الوداع للعمرة","answer":"الجواب: في وجوب الوداع على المعتمر خلاف بين أهل العلم، والذي عليه جمهور أهل العلم أنه لا يجب الوداع في العمرة، إنما هو في الحج، والصواب أنه لا يجب، وقد حكى ابن عبد البر إجماع أهل العلم على أنه لا يجب على المعتمر وداع، وهذا هو الأرجح والأقوى، وإن وادع فهو حسن، ولكن لا يجب عليه ذلك ولا حرج عليه في ترك الوداع، في موضوع العمرة. نعم.","link":"https://binbaz.org.sa/fatwas/6202/حكم-طواف-الوداع-للعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11310.mp3","categories":["الطواف بالبيت"]},{"id":8723,"question":"يسأل أحد الإخوة ويقول: إذا لم أمس الكعبة أو الحجر الأسود أو الركن اليماني أو لم أشرب من زمزم هل يتأثر حجي؟","title":"حكم استلام الحجر الأسود وتقبيله واستلام الركن اليماني","answer":"الجواب: لا، ليس عليه في هذا شيء، إنما شرع الله لنا عند الطواف أن نستلم الحجر الأسود باليد اليمنى ونقبله إذا تيسر ذلك هذا هو الأفضل؛ لأن الرسول ﷺ فعل ذلك استلمه وقبله عليه الصلاة والسلام قال: الله أكبر فهذا هو السنة، وهكذا الركن اليماني إن تيسر له استلامه استلمه بيمينه وقال: باسم الله والله أكبر، وأما بقية أجزاء الكعبة فلا يستحب مسها ولا تقبيلها ولا غير ذلك، إنما يطوف على الكعبة وعلى الحجر من وراء الحجر حتى يكمل السبعة الأشواط، كلما حاذى الحجر الأسود قبله واستلمه إذا تيسر من دون زحام ولا مشقة، وكلما حاذى الركن اليماني كذلك استلمه من دون تقبيل، الركن اليماني لا يقبل ولكن يستلم باليد ويقول: باسم الله والله أكبر، والحجر الأسود إذا وصل إليه استلمه بيده وقبله، وإن لم يتيسر استلمه بيده وقبلها أو بعصا معه وقبلها، فإن لم يتيسر ذلك أشار من بعيد وكبر ويكفيه، ولا يزاحم الناس ولا يؤذي الناس لا عند هذا ولا عند هذا، بل يمشي في طوافه حتى يكمل إن تيسر له من دون مزاحمة ولا مشقة استلم الحجر الأسود وقبله واستلم الركن اليماني ولم يقبله اتباعًا للنبي ﷺ وسيرًا على منهجه عليه الصلاة والسلام، فإن شق ذلك بسبب كثرة الناس فإنه يشير إلى الحجر الأسود وهو ماش في طوافه.\nوأما اليماني فلم يرد أنه يشار إليه بل يمر ويكفيه، ويقول بين الركنين: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ، في آخر كل شوط كما فعله النبي عليه الصلاة والسلام، وبقية الكعبة لا يمسها عند الطواف لا الركن الشامي ولا غيره -العراقي- كلها ولا جدار الحجر ما هو بمشروع لو مسها ما يضر لو مسها بيده وهو ماشي ما يضر، لكن ما يشرع أنه يمس هذا للتقرب والطاعة، إنما يشرع مس الحجر الأسود وتقبيله أو مس اليماني هذا هو المشروع، وأما بقية أجزاء الكعبة فلا يشرع له تقبيلها ولا استلامها ولا استلام جدار الحجر المعروف ولا غير ذلك، والنبي لما دخل الكعبة عليه الصلاة والسلام في وسطها دار في نواحيها ودعا وكبر ووضع يديه على جدارها من داخل ودعا ربه عليه الصلاة والسلام وضع يديه وصدره عليها ودعا ربه، أما من خارج فلم يثبت عنه ﷺ أنه فعل ذلك، وروي عنه أنه وقف في الملتزم ودعا وألصق صدره ويديه في الجدار ولكنه ليس بثابت، لم يثبت من طريق صحيحة وإنما يقف عند الملتزم إذا تيسر ويدعو بين الركن والباب؛ فعله بعض الصحابة رضي الله عنهم وأرضاهم، والأمر في ذلك واسع بين الركن والباب بعد الطواف الأول أو غيره يدعو ويسأل ربه من فضله سبحانه وتعالى لا بأس بذلك، يضع يديه وذراعيه وخده على جدار الكعبة بين الركن والباب ويدعو ربه، وإن ترك ذلك فلا بأس؛ لأنه ليس فيه سنة ثابتة عن النبي ﷺ، وإنما جاء من فعل بعض الصحابة وروي فيه حديث مرفوع لكن في سنده ضعف، فالأمر فيه واسع إن شاء الله، وأما بقية جدار الكعبة فلا يستحب للطائف أن يستلمها أو يلصق صدره فيها أو في الكسوة كل هذا غير مشروع. نعم.\nالمقدم: إذًا الزحام الشديد الذي يصوره سماحتكم يعتبر غير مشروع وذلك من أجل تقبيل الحجر الأسود أو لمسه؟\nالشيخ: يعني عذر، يكون عذرًا في ترك السنة ولاسيما النساء، النساء أخطر فلا يزاحمن لا عند الركن اليماني ولا عند الحجر الأسود؛ بل يكن في أطراف المطاف حتى لا يزاحمن الناس؛ لأنهن فتنة وعورة فالأمر في حقهن أشد، فلا يزاحمن الرجال لا عند الركن اليماني ولا عند الحجر الأسود ولا في غير ذلك؛ بل يكن في أطراف المطاف يكون ذلك أسلم لهن وأسلم للناس، والزحام عذر للجميع، لا يزاحم الزحام الذي يشق عليه وعلى الناس، بل يمشي مع الناس بالهدوء ولا يؤذي أحدًا لا من الرجال ولا من النساء، كل واحد من الحجاج يتحرى ذلك ....... يحرص جدًا على أنه لا يؤذي أحدًا من الناس لا في الطواف ولا في السعي، لا عند الحجر الأسود ولا عند اليماني، يحرص جدًا أنه لا يؤذي أحدًا؛ ولو لم يقبل الحجر، ولو لم يستلم الركن اليماني، يكفيه ذلك والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6873/حكم-استلام-الحجر-الاسود-وتقبيله-واستلام-الركن-اليماني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_160/16004.mp3","categories":["الطواف بالبيت"]},{"id":8731,"question":"رسالة وصلت إلى البرنامج من أختنا أم أحمد عبده من تعز، أختنا رسالتها مطولة بعض الشيء وتقول فيها: إني أضع مشكلتي هذه التي سببت لي القلق والحيرة آملة عدم إهمال الرد على مشكلتي وهي: ذهبت إلى الحج وقد خرجت من بيتي ومعي أربع نساء من الحي مع إخوانهن وكذلك كان ابني برفقتي من بيتي إلى المطار إلى أن وصلت إلى جماعة النساء واللائي كان معهن إخوانهن، واستقبلني زوجي في المطار وبعد ذلك قمنا بالبدء بأداء شعائر الحج، وحل وقت العيد ورميت الجمرات يوم العيد وثاني العيد وكلت زوجي، وثالث العيد قلت لزوجي: أريد أن أرمي الجمرات فمانع لشدة الزحام، وعلى إثر ذلك وقع بيننا شيء من الخصام فلم أوكله ولم أرم الجمرة ولم أطف أيضًا طواف الوداع نتيجة ما حصل بيننا، والآن أنا قلقة على ذلك النقص الذي حصل مني، أرجو أن توجهوني جزاكم الله خيرا؟","title":"حكم من حج وترك رمي الجمرات وطواف الوداع","answer":"الجواب: الحج صحيح والحمد لله، ولكن عليك فديتان:\nإحداهما: عن ترك الرمي تذبح في مكة ذبيحة من الغنم كالضحية؛ إما جذع ضأن أو ثني معز تذبح في الحرم في مكة وتوزع بين الفقراء.\nوالفدية الثانية: عن طواف الوداع؛ لأنك سافرت ولم تودعي، وظاهر كلامك أنك سافرت بدون محرم من بلدك إلى مطار جدة، وأن ابنك معك إلى المطار ثم تلقاك زوجك في المطار في جدة، وأنت معك نسوة، وهذا إن كان صحيحًا ما ظهر من سؤالك هو لا يجوز، ليس للمرأة أن تسافر إلا مع ذي محرم، ولو أن معها من يصحبها إلى المطار ويتلقاها في المطار؛ الرسول عليه السلام قال: لا تسافر امرأة إلا مع ذي محرم فإن كان هذا هو الواقع وأنك سافرت بدون محرم فعليك التوبة إلى الله والاستغفار وعدم العود إلى مثل هذا، والحج صحيح والحمد لله، وعليك ما ذكرنا من الفديتين: ذبيحة عن ترك الرمي، وذبيحة أخرى عن ترك الوداع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6882/حكم-من-حج-وترك-رمي-الجمرات-وطواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_161/16104.mp3","categories":["الطواف بالبيت","السعي","رمي الجمار"]},{"id":9103,"question":"السؤال الثالث في رسالة المستمع الحاج آدم عثمان علي من السنغال يقول فيه: عند طوافه بالبيت الحرام طواف الإفاضة لم يستطع استلام الحجر الأسود من شدة الزحام، وكاد أن يختنق من مزاحمة الأقوياء للضعفاء، فهل يلزمه شيء؟ و ما حكم من يزاحم ويؤذي الضعفاء؟ أفيدونا أفادكم الله.","title":"عدم مشروعية الزحام لتقبيل الحجر الأسود وغيره","answer":"الجواب: ليس عليه شيء، وليس له أن يزاحم، بل إذا وازن الحجر حاذاه كبر من بعيد، أشار إليه وكبر، كما كان النبي يفعل ﷺ كان ربما طاف ﷺ فأشار للحجر من بعيد وكبر ﷺ، فلا ينبغي للمؤمن أن يزاحم ولاسيما القوي مع الضعفاء فإنه يضرهم ويؤذيهم، فالسنة للمؤمن أن لا يزاحم، بل إن تيسر له تقبيل الحجر قبل الحجر واستلمه وقال: باسم الله والله أكبر، أو قال: الله أكبر، فإن لم يتيسر له ذلك، إلا بالمزاحمة أشار إليه من بعيد وهو يطوف وكبر عند محاذاته والحمد لله، ولا تنبغي المزاحمة؛ لأن فيها مضرة على الناس، لا في الطواف ولا في السعي، ولا عند الحجر الأسود ولا عند الركن اليماني، ولا عند مقام إبراهيم للصلاة، بل يصلي في الأماكن التي ليس فيها زحمة بعد الطواف، ولا ينبغي له أن يزاحم لا عند صلاة الطواف، ولا في الطواف ولا في السعي، ولا عند محاذاة الحجر الأسود، ولا عند محاذاة اليماني، نسأل الله للجميع التوفيق والهداية. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7270/عدم-مشروعية-الزحام-لتقبيل-الحجر-الاسود-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22712.mp3","categories":["الطواف بالبيت"]},{"id":9120,"question":"السؤال الثالث في رسالة الإخوة: علي محمد فارع اليماني وعلي حسن عبده وعبد الرحمن محمد علي صالح من الجمهورية العربية اليمنية، يقولون فيه:أهل مكة والمتمتع هل يجوز لهم الطواف والسعي قبل الصعود إلى عرفات دون الخروج إلى الحِلْ، أم أنه لا بد من الذهاب إلى الحِلْ والإحرام منه ليتسنى لهم أداء طواف القدوم وسعي الحج قبل الحج، وما حكم من فعل ذلك دون خروج إلى الحل أفيدونا أفادكم الله؟","title":"حكم الطواف والسعي لأهل مكة والمتمتعين إذا أرادوا الحج","answer":"الجواب: أهل مكة وغيرهم من المتحللين من العمرة في مكة السنة لهم إذا أحرموا أن يتوجهوا إلى منى، سواء كان إحرامهم من الحِل أو من الحرم.\nالسنة لهم أن يتوجهوا إلى منى كما توجه النبي ﷺ وأصحابه رضي الله عنهم إلى منى يوم الثامن، فالنبي ﷺ أمر الصحابة أن يتوجهوا إلى منى يوم الثامن وأن يحرموا بالحج، ولم يقل لهم: ادخلوا إلى مكة فطوفوا واسعوا أو طوفوا فقط بل أمرهم بأن يتوجهوا إلى منى ملبين، فدل ذلك على أن المتحلل في مكة من العمرة وهكذا أهل مكة إذا أرادوا الحج وهكذا المقيمون بها إذا جاء يوم الثامن وهم يريدون الحج يحرمون من منازلهم أو من أي مكان ويتوجهون إلى منى، ولا يشرع لهم دخول مكة للطواف والسعي، وإنما هذا للأفقي الذي قدم.. الذي يقدم من بعيد هذا يشرع له أن يبدأ بالطواف والسعي ثم يتحلل بالعمرة إن كان الوقت فيه سعة، وإن كان الوقت ضيقاً ذهب إلى منى على إحرامه، سواء كان محرماً بالحج أو بالقران، أما إن كان محرماً بالعمرة فقط وهو المتمتع فإنه بعد الطواف والسعي يقصر أو يحلق، والسنة التقصير إذا كانت العمرة قريبة من الحج حتى يتوفر الحلق للحج.\nوبعدما يقصر من عمرته يلبي بالحج ثم يتوجه إلى منى ولا يطوف ويسعى بعد تلبيته بالحج، بل يلبي بالحج ويخرج حالاً إلى جهة منى من غير طواف ولا سعي وهذا الطواف والسعي الذي يفعله المحرم من مكة في الحج، لا يجزئه إذا طاف وسعى بعدما أحرم في مكة بالحج لا يجزئه؛ لأنه غير مشروع وإنما الطواف والسعي يكون بعد ذلك بعد نزوله من عرفات يوم العيد أو بعده هذا هو الطواف المشروع لمن أحرم من مكة من أهلها أو المقيمين فيها أو المتحللين والله ولي التوفيق.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7278/حكم-الطواف-والسعي-لاهل-مكة-والمتمتعين-اذا-ارادوا-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_228/22803.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":9467,"question":"ورد سؤال من الأخ عيسى عبدالوهاب من السودان يقول فيه: قرأت في بعض المناسك: لو سعى قبل أن يطوف جهلًا أو ناسيًا فلا شيء عليه مستدلًا بحديث: سعيت قبل أن أطوف، قال: افعل ولا حرج فهل هذا صحيح؟ وما مدى صحة هذا الحديث، أفيدونا وفقكم الله؟","title":"حكم تقديم السعي على الطواف","answer":"الجواب: نعم صحيح، وقد بيناه في المنسك منسكنا (التحقيق والإيضاح في كثير من مسائل الحج والعمرة والزيارة)، والحديث في الصحيح عن النبي ﷺ أنه سأله سائل، فقال: سعيت قبل أن أطوف؟ قال: طف ولا حرج ولم يأمره بإعادة السعي، فدل ذلك على أنه لا حرج في ذلك ولاسيما إذا كان جاهلًا أو ناسيًا، فالأمر فيه أوضح وقال في الحديث: ولو عامدًا، وهذا أيضًا يعمه قوله ﷺ في الحديث الصحيح لما سئل يوم النحر: قال له: يا رسول الله! حلقت قبل أن أذبح؟ قال: اذبح ولا حرج، وقال آخر: نحرت قبل أن أرمي؟ قال: لا حرج، وقال آخر: أفضت قبل أن أرمي؟ قال: لا حرج، قال الراوي: فما سئل يومئذ عن شيء قدم ولا أخر إلا قال: افعل ولا حرج.\nفهذا العموم يعم من سعى قبل أن يطوف، وأنه يجزئه ذلك كما يجزئه لو نحر قبل أن يرمي أو طاف قبل أن يرمي، مع أن النبي ﷺ رمى ثم نحر ثم حلق ثم طاف، رتب هكذا، رمى ثم نحر ثم حلق ثم طاف، ولكن هذا الترتيب بين ﷺ أنه ليس بواجب، ولكنه هو الأفضل، فمن قدم بعض على بعض فلا حرج، سواء كان عامدًا أو جاهلًا أو ناسيًا، فيدخل في ذلك الطواف والسعي أيضًا، فإذا سعى قبل أن يطوف ناسيًا أو جاهلًا فلا حرج بلا شك، وهكذا لو كان عامدًا على الصحيح لعموم قوله ﷺ للرجل لما سأله: سعيت قبل أن أطوف؟ قال: لا حرج ولم يسأله يقول: هل أنت ناسي؟! هل أنت جاهل؟! بل أطلق، والإطلاق يدل على التعميم. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7629/حكم-تقديم-السعي-على-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19110.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":9691,"question":"تقول هذه الأخت لي أخ قدم من اليمن لأداء مناسك العمرة، وذهب إلى مكة واعتمر، وذهب بعد ذلك لزيارة المسجد النبوي الشريف، وعندما حان وقت سفره عاد مرة أخرى إلى مكة المكرمة وأدى العمرة بطواف واحد، أي: لم يطف طواف الوداع لجهله بذلك، وسافر في نفس ذلك اليوم الذي اعتمر فيه، ماذا يلزمه الآن وهو في اليمن؟","title":"طواف الوداع للعمرة ليس بواجب","answer":"الجواب: العمرة ليس لها طواف وداع، وليس عليه شيء، إن طاف للوداع فهو أفضل وإلا ليس هناك شيء واجب، هذا هو الصحيح وهو الذي عليه جمهور أهل العلم أن العمرة ليس لها وداع، وإنما الوداع الواجب للحج خاصة، فليس على أخيك شيء والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7893/طواف-الوداع-للعمرة-ليس-بواجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25402.mp3","categories":["الطواف بالبيت"]},{"id":10061,"question":"إذا كنت لا أحفظ كثيراً من الأدعية، فهل يجوز أن أتناول كتاباً يحتوي على بعض الأدعية وأقرأ منه وأنا أطوف بالبيت الحرام وفي المسعى مثلاً؟","title":"حكم قراءة الأدعية أثناء الطواف والسعي من كتاب","answer":"الجواب: لا حرج في ذلك الحمد لله، لا حرج، أن تأخذ كتاباً فيه دعوات طيبة من مؤلف معروف موثوق به من العلماء لا بأس، أو تدعو على أن تدعو من قلبك يعني: عن ظهر قلب مما يسر الله لك قد يكون هذا أجمع لقلبك قد يكون هذا أخشع وإن دعوت من ورقة أو كتاب فلا بأس. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8232/حكم-قراءة-الادعية-اثناء-الطواف-والسعي-من-كتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30314.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":10120,"question":"هل صحيح أن الصلاة التي نصليها في مسجد الميقات لنية العمرة أو الحج هي من البدع؟","title":"حكم صلاة ركعتين عند الإحرام من الميقات","answer":"الجواب: ليست من البدع، بل عند الجمهور أنها سنة، عند أكثر أهل العلم أنها سنة، صلاة ركعتين قبل أن يحرم، ولكن ليس عليها دليل واضح، بل بعض أهل العلم لا يراها سنة، والأمر فيها واسع وليست بدعة، من توضأ وصلى ركعتين وأحرم فلا بأس، ومن أحرم بدون ركعتين فلا بأس، الأمر في هذا واسع، وقد ثبت عنه ﷺ أنه أتاه آت من ربه فقال: صل في هذا الوادي المبارك وقل: عمرة في حجة يعني: في وادي ذي الحليفة ميقات أهل المدينة، فاحتج بهذا بعض أهل العلم على أنه يصلى عند الإحرام، لقوله ﷺ إن الآتي الذي أتاه من ربه قال: صل في هذا الوادي المبارك وقل: عمرة في حجة، ولأنه أحرم بعد الصلاة، بعد صلاة الظهر في حجة الوداع عليه الصلاة والسلام، فمن توضأ وصلى ركعتين سنة الوضوء وأحرم بعدها فهذا حسن، قول الجمهور يقولون.. جمهور أهل العلم يقولون: يستحب أن يصلي ركعتين، يعني: قبل أن يحرم، ويحتجون بحديث..\nالمقدم: قبل أن يحرم.\nالشيخ: إيه.. قبل أن يلبي يعني، وإن كان بعد غسل الإحرام يلبس إزاره ورداءه ويتأهب ويتطيب ويصلي ركعتين ثم يلبي بعد ركوبه الدابة أو السيارة، النبي ﷺ ما أحرم إلا بعدما ركب دابته، فالسنة للمؤمن ألا يلبي وألا ينوي العمرة والحج إلا بعد ركوب السيارة، إذا ركب واستقر فيها يلبي بما نواه من حج أو عمرة أو كليهما، هذا هو الأفضل له، ما دام في الأرض لا ينوي ولا يلبي هذا هو الأفضل، فإذا لبس إزاره ورداءه وفرغ من غسله وطيبه ركب ثم لبى بحجه أو عمرته، وهكذا المرأة إذا فرغت من كل شيء تركب السيارة ثم تلبي كفعل النبي عليه الصلاة والسلام، ومن صلى قبل ذلك صلى ركعتين في الميقات أو في بيته إذا كان قريبًا من الميقات كأهل الطائف ونحوهم أو الذين يحرمون من جدة ونحوهم ممن كان دون الميقات إذا توضأ وصلى ركعتين فهذا حسن، سنة الوضوء ويوافق بهذا رأي الجمهور، ويوافق فعل ﷺ فإنه أحرم بعد ما صلى في حجة الوداع، صلى الظهر ثم أحرم عليه الصلاة والسلام، وكذلك عموم أنه أتاه آت من ربه فقال له: صل في هذا الوادي المبارك وقل: عمرة في حجة هذا فيه متمسك لمن قال بشرعية الركعتين قبل الإحرام. وبكل حال فالأمر في هذا واسع إن شاء الله، وإن كان الحديث غير صريح لكنه فيه متمسك لمن قال بذلك، فلا ينبغي القول بأنها بدعة.\nالمقدم: طيب! يجوز أن تسمى ركعتي الإحرام؟\nالشيخ: يسميها العلماء ركعتي الإحرام، وإذا سميت ركعتي الوضوء إذا توضأ وصلى ركعتين سميت ركعتي الوضوء، يعني يسن لمن توضأ أن يصلي ركعتين، فإذا توضأ وعمل بالسنة وصلى ركعتين أحرم بعدهما فجمع بين السنتين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8291/حكم-صلاة-ركعتين-عند-الاحرام-من-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33408.mp3","categories":["الطواف بالبيت"]},{"id":10537,"question":"السائلات مقيمات في منطقة جدة يقلن في هذا  نرجو الإفادة الحكم لمن لم يتم العمرة وذلك في شهر رمضان في اليوم السابع والعشرين من الشهر الكريم، فقد أدينا الطواف كاملًا ولكننا لم نستطع إتمام السعي؛ وذلك لشدة الزحام فما الحكم في ذلك؟ وهل هناك فدية، وما نوع الفدية وأين ذبحها سماحة الشيخ؟","title":"حكم من لم يتم السعي في العمرة لشدة الزحام","answer":"الجواب: الواجب تكميل العمرة بعد تلك الليلة، يسعى ويقصر ويحلق هذا هو الواجب على الجميع الرجال والنساء، لا بأس .. بأن يكون بين الطواف والسعي فجوة، فإذا طاف مثلاً في النهار وصعب عليه السعي، أو طاف في الليل وصعب عليه السعي، أجل السعي إلى وقت آخر وسعى والحمد لله، والذي ما سعى مثلاً إلى الآن يسعى يذهب ويسعى يكمل عمرته ويقصر؛ لأنه ما زال في إحرام العمرة، إذا كان لم يسع ولم يقصر لا يزال في إحرام العمرة إلى أن يرجع إلى مكة ويسعى ويقصر ويتحلل والحمد لله.\nوإن كان أتى زوجته إذا كان رجل أو امرأة أتاها زوجها فهي تفسد العمرة، وتكملها عمرة فاسدة وتأتي بعمرة جديدة من الميقات الذي أحرمت بالأولى منه، وهذه العمرة التي وقع فيها جماع تكمل فاسدة، ثم يؤتى بعمرة عوضاً منها من الميقات الذي أحرم بالأولى منه، نعم.\nالمقدم: سماحة الشيخ الحقيقة استوقفني مقطع من هذا السؤال، وهو التزاحم يوم السابع والعشرين من شهر رمضان هل من كلمة حول هذا سماحة الشيخ؟\nالشيخ: نعم، لا شك أن هذا أمر يحصل به مضرة كبيرة، والذي ينبغي للمؤمنين في هذا عدم التزاحم، وإذا كان مشقة يؤجل يطوف في النهار، يسعى في النهار، ليس من اللازم أن يسعى في الليل، يشق على نفسه وعلى غيره، والحمد لله يجتهد فيها بالتسبيح والتهليل والدعاء وأنواع الخير والذكر والقراءة ويكفي، ولا يؤذي نفسه ولا يؤذي الناس، الرجل والمرأة جميعاً، فلا حاجة إلى الزحام الذي يضرهم جميعاً، يبقى على إحرامه ويطوف ويسعى في النهار والحمد لله، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8712/حكم-من-لم-يتم-السعي-في-العمرة-لشدة-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28409.mp3","categories":["الطواف بالبيت","السعي"]},{"id":10857,"question":"يقول: والدتي كبيرة في السن، طافت بالبيت العتيق، وأرادت أن تسعى، لكنها لا تستطيع، فركبت عربية وحينئذ غفت عينها، ولم تستيقظ إلا بعد انتهاء السعي، فهل سعيها صحيح؟","title":"حكم من عجز عن السعي فحُمل ونام ولم يستيقظ إلا بعده","answer":"الجواب: \n\nلا يصح إذا كان نامت، لا يصح سعيها، أما إذا كان نعاسًا لكن ما ذهب شعورها، فالنعاس لا يضر، كما قد يقع للإنسان في الصلاة أيضًا، أما إذا قد ذهب يعني نامت نومًا يزيل الشعور فإن النية تزول ما تمت النية، لا بد من أن تسعى بنية السعي، وهي عاقلة، شعورها معها، فإذا فاتها شوطٌ أو شوطان في النوم تعيد الشوط والشوطين الذي نامت فيهما، وإن كان السعي كله ذهب في النوم تعيده كله. \n\nالمقصود: أنه إذا كان نعاسًا وشعورها باقيًا فلا بأس، أما إذا كانت نامت في الأشواط كلها تعيدها، أو نامت في شوط، أو شوطين، أو ثلاثة تعيد الشوط الذي نامت فيه نومًا ثقيلًا، نومًا أفقدها الشعور. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9040/حكم-من-عجز-عن-السعي-فحمل-ونام-ولم-يستيقظ-الا-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35708.mp3","categories":["الطواف بالبيت","السعي"]},{"id":10908,"question":"تسأل وتقول: ما حكم من ذهب لأداء فريضة العمرة، وبعد أن أنهى فريضة العمرة ذهب إلى المدينة بدون طواف وداع للزيارة والعودة مرة أخرى إلى مكة لطواف الوداع، وعندما رجع من المدينة إلى مكة أحرم ونوى عمرة أخرى؟","title":"طواف الوداع للمعتمر","answer":"الجواب:  العمرة ليس لها وداع في أصح قولي العلماء، ليس لها وداع واجب، والنبي ﷺ لم يأمر المعتمرين بأن يودعوا، ولا الذين حجوا معه لما أحلوا من عمرتهم لم يأمرهم أن يودعوا إذا أرادوا الخروج من مكة، وفيهم الرعاة الذين يخرجون مسافات بعيدة، ولم يأمرهم بالوداع قبل الحج، وإنما الوداع للحج. أما العمرة فأمرها واسع، مشروعة في كل وقت، فلا يجب لها الوداع، لكن من ودع فذلك حسن، وفيه خروج من الخلاف، وإلا فليس بواجب، والذين خرجوا إلى المدينة، ولم يودعوا لا شيء عليهم، وإذا رجعوا بعمرة فقد أحسنوا ويكون إحرامهم بها من ذي الحليفة، إذا كانوا أرادوا عمرة، وهم في المدينة أحرموا من ذي الحليفة من ميقات المدينة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9076/طواف-الوداع-للمعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36003.mp3","categories":["الطواف بالبيت"]},{"id":10937,"question":"يقول: في حج الإفراد في طواف القدوم طفنا الشوط السادس من داخل الحطيم لعذر، ولكن نسينا أن نكمل السبع بالشوط الثامن، فما الحكم؟ جزاكم الله خيرًا.","title":"حكم طواف الشوط السادس من داخل الحجر","answer":"الجواب:  يكون الطواف غير صحيح، ما طفتم إلا ستة؛ لأن الطواف من داخل الحجر لا يجزي ولا يصح، لابد أن يكون الطواف من وراء الحجر، فهذا الطواف الذي فعلتم لا يجزي، وإذا كان هو طواف الوداع فعليكم دم عن ترككم طواف الوداع، يذبح بمكة للفقراء نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9105/حكم-طواف-الشوط-السادس-من-داخل-الحجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36202.mp3","categories":["الطواف بالبيت"]},{"id":10979,"question":"له سؤال أخير يقول: سماحة الشيخ! بالنسبة لطواف الوداع في العمرة إذا أتى به الإنسان هل في ذلك بأس؟","title":"هل يستحب طواف الوداع في العمرة؟","answer":"الجواب:  يستحب أن يأتي بالوداع لأنه في خلاف، بعض أهل العلم يراه واجبًا، فإذا طاف للوداع في العمرة يكون أفضل وأحوط؛ إلا إذا كان خروجه في الحال، اعتمر ومشى ما يحتاج وداعًا، طاف وسعى، ثم مشى ما يحتاج وداعًا، لكن لو تأخر يومًا يومين، يعني تأخر وقتًا طويلًا يستحب له أن يودع. نعم.","link":"https://binbaz.org.sa/fatwas/9157/هل-يستحب-طواف-الوداع-في-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28623.mp3","categories":["الطواف بالبيت"]},{"id":11270,"question":"يسأل يقول: هل يصح للحائض أن تؤخر طواف الإفاضة إلى حج آخر؟","title":"حكم تأخير الحائض طواف الإفاضة إلى عام آخر","answer":"الجواب:  ليس لها ذلك، بل الواجب عليها أن تبادر وتطوف الإفاضة قبل أن تسافر، ولهذا لما حاضت صفية قال رسول الله ﷺ أحابستنا هي؟ قالوا له: إنها قد أفاضت قال: انفروا.  فالمقصود أن عليها أن تطوف للإفاضة قبل أن تغادر مكة، إلا إذا كان هناك ضرورة والمحل قريب كجدة والطائف والرفقة لا يسمحون لها تذهب معهم ثم ترجع ولا تؤخر. نعم. المقدم: هل تنصحونها بالالتزام بأحكام معينة حتى تطوف طواف الإفاضة؟  الشيخ: نعم، لا تحل لزوجها، إذا كان لها زوج لا يقربها زوجها حتى تطوف، أما الطيب وقص الأظفار لا حرج في ذلك، نعم. المقدم: المهم أنها إذا كانت ذات زوج فإنها تبتعد عن زوجها. الشيخ: نعم، لا يقربها حتى تطوف. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9453/حكم-تاخير-الحاىض-طواف-الافاضة-الى-عام-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37504.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":11287,"question":"امرأة جاءتها العادة أثناء الطواف فكيف تتصرف؟","title":"حكم من طرأت عليها العادة أثناء الطواف","answer":"الجواب:  تخرج من المطاف وتبقى حتى تطهر والحمد لله، إذا جاءتها في أثناء الطواف تخرج يعني من المسجد حتى يذهب بها وليها، وإن كان في السعي تكمل السعي لا يشترط فيه الطهارة، لكن في الطواف نفسه الذي حول البيت إذا جاءتها العادة في الشوط الثالث أو الرابع أو الخامس تخرج، وعلى وليها أن يخرج بها من المسجد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9468/حكم-من-طرات-عليها-العادة-اثناء-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37519.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":11296,"question":"يقول في سؤال ثانٍ: أديت فريضة الحج منذ ثلاث سنوات وطفت طواف القدوم وسعيت بين الصفا والمروة، وأيضًا طفت طواف الوداع ولم أسع بين الصفا والمروة لأني كنت لا أعلم ذلك، وعندما توجهت إلى المدينة المنورة لزيارة الحرم النبوي الشريف علمت من الإخوة بأن المفروض علي السعي بين الصفا والمروة بعد طواف الوداع، وبعض منهم نصحني بفدية، والبعض الآخر قال بأنه لا شيء عليك إذا كنت تجهل ذلك، هل حجي صحيح أم أن علي فدية أم ماذا أفعل؟ جزاكم الله خيرًا. الشيخ: تعيده. نعم.المقدم: يقول: أديت فريضة الحج منذ ثلاث سنوات وطفت طواف القدوم وسعيت بين الصفا والمروة، وأيضًا طفت طواف الوداع ولم أسع بين الصفا والمروة لأني كنت لا أعلم ذلك، وعندما توجهت إلى المدينة المنورة لزيارة الحرم النبوي الشريف علمت من الإخوة بأن المفروض علي السعي بين الصفا والمروة بعد طواف الوداع، وبعض منهم نصحني بالفدية، والبعض الآخر قال بأنه لا شيء عليك إذا كنت تجهل، هل حجي صحيح أم أن علي فدية أم ماذا أفعل؟ جزاكم الله خيرًا.","title":"حكم من ترك السعي في الحج مكتفياً به في العمرة","answer":"الجواب:  سؤالك فيه إجمال وعدم تفصيل، لكن نفصل لك حتى تعرف الواقع، إذا كنت لبيت بالعمرة ودخلت بالعمرة وطفت وسعيت وقصرت وحليت من العمرة متمتعًا، ثم لبيت بالحج وحججت مع الناس، وطفت طواف الإفاضة، وطفت طواف الوداع ولكن لم تسع، فهذا غلط منك عليك أن تسعى ولو الآن، عليك أن تذهب إلى مكة تسعى بنية الحج السابق ولا حرج عليك تسعى بنية الحج السابق، وعليك فدية إذا كنت جامعت المرأة بعد ذلك، ذبيحة تذبح في مكة للفقراء؛ لأنك أتيت المرأة قبل أن تسعى بفعل الحج والسعي الأول للعمرة، أما السعي الثاني فهو عليك للحج مع طواف الإفاضة الذي تأتي به بعد قدومك من منى يوم العيد أو بعده، أما طواف الوداع فمستقل عند الخروج من مكة، طواف الوداع هذا مستقل واجب لتوديع البيت عند الخروج من مكة، وعليك أن تمتنع من الجماع حتى تأتي بالسعي. أما إذا كنت لبيت بالحج أو بالحج والعمرة جميعًا بقيت على إحرامك، طفت وسعيت وبقيت على إحرامك ما حللت حتى خرجت إلى منى وأنت محرم فلا عليك شيء، يكفيك الطواف طواف الإفاضة غير طواف الوداع، طواف الإفاضة ثم طواف الوداع عند الخروج، وإن طفت طواف الإفاضة عند الخروج كفى عن الوداع، إذا كنت طفت عند الخروج طوافًا واحدًا سبعة أشواط كفى عن الوداع، وليس عليك السعي، السعي الأول كافي إذا كنت أحرمت بالحج مفردًا أو بالحج والعمرة جميعًا ولم تحل بل بقيت على إحرامك حتى ذهبت إلى منى وحتى أديت الحج فليس عليك إلا السعي الأول، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9473/حكم-من-ترك-السعي-في-الحج-مكتفيا-به-في-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37605.mp3","categories":["الطواف بالبيت","السعي"]},{"id":11309,"question":"يسأل في قضية يقول: هل يجوز للمرأة أن تقبل الحجر الأسود وتستلم الركن اليماني؟","title":"حكم تقبيل المرأة للحجر الأسود واستلام الركن اليماني","answer":"الجواب:  إذا تيسر ذلك من دون مزاحمة للرجال ولا فتنة، إذا تيسر في وقت خلوة ..... بين الرجال فلا بأس وإلا فإنها تطوف من وراء الناس في أطراف المطاف بعدًا عن الفتنة، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9497/حكم-تقبيل-المراة-للحجر-الاسود-واستلام-الركن-اليماني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37708.mp3","categories":["الطواف بالبيت","السعي","قضايا المرأة"]},{"id":11324,"question":"يسأل في قضية يقول: هل يجوز للمرأة أن تقبل الحجر الأسود وتستلم الركن اليماني؟","title":"حكم تقبيل المرأة للحجر الأسود واستلام الركن اليماني","answer":"الجواب:  إذا تيسر ذلك من دون مزاحمة للرجال ولا فتنة، إذا تيسر في وقت خلوة ..... بين الرجال فلا بأس وإلا فإنها تطوف من وراء الناس في أطراف المطاف بعدًا عن الفتنة، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9497/حكم-تقبيل-المراة-للحجر-الاسود-واستلام-الركن-اليماني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37708.mp3","categories":["الطواف بالبيت","السعي","قضايا المرأة"]},{"id":11369,"question":"أخونا يقول: الحمد لله قد أديت فريضة الحج واعتمرت، لكنني كنت أسعى من الصفا إلى المروة وأعود فأعتبر هذا شوطًا واحدًا، وهكذا قضيت الأشواط السبعة، فهل في هذه الزيادة شيء؟ أفيدوني جزاكم الله خيرًا.","title":"حكم الزيادة في أشواط السعي بين الصفا والمروة","answer":"الجواب:  السعي صحيح والسبعة الزائدة لا تضرك، السعي المشروع من الصفا إلى المروة شوط والعودة من المروة إلى الصفا شوط ثاني وهكذا، فإذا سعى أربعة عشر فالمشروع منها سبعة والزائد لا يضره لأنه وقع خطأً منه وجهلًا منه فلا يضره. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9567/حكم-الزيادة-في-اشواط-السعي-بين-الصفا-والمروة","audio":"","categories":["الطواف بالبيت","السعي"]},{"id":11377,"question":"أخونا يقول: الحمد لله قد أديت فريضة الحج واعتمرت، لكنني كنت أسعى من الصفا إلى المروة وأعود فأعتبر هذا شوطًا واحدًا، وهكذا قضيت الأشواط السبعة، فهل في هذه الزيادة شيء؟ أفيدوني جزاكم الله خيرًا.","title":"حكم الزيادة في أشواط السعي بين الصفا والمروة","answer":"الجواب:  السعي صحيح والسبعة الزائدة لا تضرك، السعي المشروع من الصفا إلى المروة شوط والعودة من المروة إلى الصفا شوط ثاني وهكذا، فإذا سعى أربعة عشر فالمشروع منها سبعة والزائد لا يضره لأنه وقع خطأً منه وجهلًا منه فلا يضره. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9567/حكم-الزيادة-في-اشواط-السعي-بين-الصفا-والمروة","audio":"","categories":["الطواف بالبيت","السعي"]},{"id":11387,"question":"يسأل سماحتكم عن فضل تقبيل الحجر الأسود؟ ولاسيما وأنه يكون هناك زحام شديد جزاكم الله خيرًا.","title":"حكم تقبيل الحجر الأسود مع الزحام","answer":"الجواب:  يستحب تقبيل الحجر الأسود في الحج والعمرة في الطواف، يستحب للمسلم في طواف الفريضة وطواف النافلة في الحج والعمرة يستحب له التقبيل إذا تيسر من دون مزاحمة ولا مشقة، فأما مع المزاحمة والمشقة يتركه، يشير إشارة من بعيد ويقول الله أكبر ويكفي ولا حاجة إلى المزاحمة. المقدم: بارك الله فيكم جزاكم الله خير الجزاء وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9553/حكم-تقبيل-الحجر-الاسود-مع-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37903.mp3","categories":["الطواف بالبيت"]},{"id":11673,"question":"إحدى الأخوات تسأل وتقول: المرسلة (م. أ) تسأل وتقول: ما حكم المرأة الحائض إذا تركت مكة المكرمة قبل أن تطوف طواف الإفاضة، وذلك لارتباط زوجها بالعمل عند كفيل، ولم تتمكن من الاستمرار في مكة حتى الطهر؟ وهل يمكن العودة لعمل الطواف أم لا؟ ولقد تم فك الإحرام بعد فتوى لي من أهل العلم، ولكن غير راضية عن هذه الفتوى وعن ذلكم الحج، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"حكم من تركت طواف الإفاضة بسبب الحيض وسافرت","answer":"الجواب:  الواجب على من لم تطف طواف الإفاضة إذا سافرت من أجل علة أوجبت ذلك، فإن الواجب عليها الرجوع، ترجع مع محرمها للطواف، ولا يقربها زوجها حتى تطوف، فإذا ذهبت مع زوجها للبلد فعليه أن يرجع بها في الأوقات المناسبة، أو يرجع بها أخوها، أو أبوها، أو غيرهما من محارمها إلى مكة، حتى تطوف طواف الإفاضة، وتسعى إذا كان عليها سعي، إذا كانت متمتعة فسعيها الأول للعمرة، وعليها أن تسعى ثانٍ مع طواف الإفاضة للحج، وليس لزوجها قربانها يعني: جماعها حتى ترجع وتطوف، فإن فعل زوجها وجامعها؛ فعليها دم يذبح بمكة للفقراء، وحجها صحيح، الحج صحيح، والحمد لله، لكن إذا جامعها فعليها التوبة، وتأثم ويأثم هو أيضًا، وعليها ذبيحة تذبح في مكة للفقراء لكونه جامعها قبل الطواف، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، لها كلمة بودي لو تفضلتم بالتعليق عليها سماحة الشيخ! ألا وهي قولها: إنها فكت الإحرام بناء على فتوى من أهل العلم، لكنها غير راضية عن تلكم الفتوى، وعن ذلكم الحج؟ الشيخ: إن كان فك الإحرام بالطيب وغطاء الوجه ونحو ذلك؛ فهذا لا بأس به، قلم الأظفار، كد الشعر كل هذا لا بأس به، لأن هذا يحل بعد الرمي والتقصير يحل هذا كله، ما يبقى إلا التحريم للجماع فقط، فحلها الإحرام في هذه الأمور، كد الشعر قلم الأظفار نتف الإبط، وشبه ذلك هذا لا بأس به. فإن كان قصدها فك الإحرام أنها جامعها زوجها فقد بينا أن عليها دم، وعليها أن تمتنع حتى تطوف، لا يعود إلى جماعها حتى تطوف. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9855/حكم-من-تركت-طواف-الافاضة-بسبب-الحيض-وسافرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39005.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":12007,"question":"رسالة بعث بها مستمع، يقول: (أ. م. ع. س) من جمهورية مصر العربية، يقول: أديت عمرة في شعبان، وكانت الأولى والحمد لله، ثم أديت عمرة لوالدي المتوفى، ولكن أثناء دخولي الحرم وجدت نفسي دون أن أدري في الدور الثاني، وكان ذلك أثناء صلاة التراويح، والكل يصلي، فدخلت الصف، وصليت معهم، وكنت أعتقد ألا طواف أثناء الصلاة، ونظرت بطرف عيني أثناء الصلاة؛ فوجدت الناس يطوفون، فتركت الصلاة، ونزلت للطواف سبعة أشواط، ثم السعي بين الصفا والمروة، ثم قصرت شعري، هل العمرة صحيحة بدخولي أولًا في الصلاة، أم يجب علي إعادتها؟ جزاكم الله خيرًا.","title":"حكم الطواف أثناء صلاة التراويح","answer":"الجواب:  لا حرج، العمرة الصحيحة، سواءً طفت قبل الصلاة، أو بعد الصلاة، أو وهم يصلون، كله لا يضر، الحمد لله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10192/حكم-الطواف-اثناء-صلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43121.mp3","categories":["الطواف بالبيت"]},{"id":12161,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، رمزت إلى اسمها بالحروف: (م. أ. س) أختنا تقول: من جعل طواف الإفاضة والوداع طوافًا واحدًا لأسباب معينة، هل يجزئه ذلك، أو لا يجزئ؟","title":"حكم جعل طواف الإفاضة والوداع طوافًا واحدًا","answer":"الجواب:  نعم يجزئه، إذا طاف الإنسان طواف الإفاضة عند خروجه إلى بلده؛ أجزأه، سواءً نوى الوداع، أو ما نوى الوداع؛ يجزئه، وإن نواهما جميعًا؛ أجزأه، فإن طاف عند خروجه، عند سفره طواف الحج؛ كفاه عن الوداع، والحمد لله، وإن نواهما، نواه عن الحج، وعن الوداع؛ كفى، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10346/حكم-جعل-طواف-الافاضة-والوداع-طوافا-واحدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44111.mp3","categories":["الطواف بالبيت"]},{"id":12250,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من الطائف، وقعت في نهاية الرسالة بقولها: أختكم في الله نالة العسيري، الأخت نالة عرضنا بعض أسئلةٍ لها في حلقاتٍ مضت، وفي هذه الحلقة سنعرض لها بعضًا من أسئلتها أيضًا، حيث بعثت بعددٍ كبيرٍ من الأسئلة، فتسأل في هذه الحلقة، وتقول: هل للطواف والسعي بين الصفا والمروة، والوقوف بعرفة، والمبيت بمزدلفة، أدعية مخصصة، أم يدعو الحاج بما شاء من الأدعية؟","title":"الأدعية والأذكار المشروعة في الطواف والسعي","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فليس للطواف والسعي والوقوف بعرفة، وفي مزدلفة أدعية مخصصة، لابد منها، بل يشرع للمؤمن أن يدعو ويذكر الله، وليس هناك حد محدود، فيذكر الله بقوله: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيءٍ قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله وبحمده، سبحان الله العظيم، يردد مثل هذا الذكر، ويدعو بما يسر الله من الدعوات، يسأل ربه أن الله يغفر له ذنوبه، ويدخله الجنة، وينجيه من النار، يسأل الله له ولوالديه المسلمين المغفرة والرحمة، وإن كان والداه مسلمين؛ سأل الله لهما التوفيق في إصابة الحق، والهداية والاستقامة، والثبات على دين الله. وهكذا يسأل الله لولاة أمر المسلمين بالتوفيق والهداية، وصلاح النية والعمل، وصلاح البطانة، ويسأل الله من خير الدنيا والآخرة، في طوافه، وفي سعيه، وفي وقوفه بعرفات، وفي مزدلفة، وفي منى، وفي كل مكان، يسأل ربه من خير الدنيا والآخرة. لكن يشرع له في الطواف أن يختم كل شوط بقوله: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] فعله الرسول ﷺ وهذا مستحب، ولو ترك؛ ما عليه شيء، فهذا مستحب أن يقول هذا الدعاء، ولو ما دعا بذلك، ودعا بغيره؛ فلا حرج عليه، لكن يستحب له في آخر كل شوط بين الركنين، يعني: بين الركن اليماني، والحجر الأسود أن يقول: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] وكلما حاذى الحجر؛ كبر، قال: الله أكبر، أو باسم الله والله أكبر، في كل طوفة، يبدأ بهذا، ويختم بهذا، يبدأ بالتكبير، ويختم بالتكبير، وإن قرأ القرآن في سعيه وطوافه، فلا بأس، وفي السعي يستحب له أن يكثر من الدعاء والذكر والتكبير، على الصفا والمروة، مستقبلًا القبلة ثلاث مرات، يكرر ثلاث مرات، والرسول ﷺ .......... وحد الله وكبره، ودعا، وكرر ثلاث مرات، وكان من ذكره على الصفا والمروة: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيءٍ قدير، لا إله إلا الله وحده، أنجز وعده، ونصر عبده، وهزم الأحزاب وحده. ويدعو بما يسر الله، ويكرر ثلاث مرات، وإذا قال: الله أكبر الله أكبر، لا إله إلا الله، الله أكبر، الله أكبر ولله الحمد، هذا طيب؛ لأن فيه تحميد الله، وتكبيره؛ لأن في هذا تحميد الله وتكبيره . وإن قال: سبحان الله والحمد لله، ولا إله إلا الله، والله أكبر؛ فحسن، أو قال: سبحان الله وبحمده، سبحان الله العظيم؛ فحسن، يدعو بما تيسر، ويدعو ما تيسر، مع الذكر، ويرفع يديه، ويستقبل القبلة حال كونه على الصفا وحال كونه على المروة، يستقبل القبلة رافعًا يديه، ويكبر الله، ويحمده، ويثني عليه، ويدعو، ويذكر الله ثلاث مرات، يكرر، كما كرر النبي، عليه الصلاة والسلام. وهكذا على المروة، في كل شوط، ويختم بالذكر والدعاء على المروة في الشوط السابع، وفي الطريق بينهما يذكر الله، ويدعو أيضًا، بما يسر الله من ذكرٍ وثناء، وحمدٍ ودعاء، حين نزوله من الصفا إلى المروة، وحين رجوعه كذلك من المروة إلى الصفا، يكثر من ذكر الله والدعاء، وليس في ذلك شيء معين واجب، بل ما يسر الله له من الذكر والدعاء الطيب، فهو كافي، لكن يتحرى الدعوات الجامعة، التي تنفعه في الدنيا والآخرة، مثل: اللهم إنك عفو تحب العفو فاعف عني اللهم إني أسألك رضاك والجنة، وأعوذ بك من سخطك والنار اللهم إني أسألك الجنة، وما قرب إليها من قولٍ وعمل، وأعوذ بك من النار، وما قرب إليها من قول وعمل رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] إلى غير هذا، مع ذكر الله، مع قوله: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت وهو على كل شيء قدير سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، الله أكبر الله أكبر، لا إله إلا الله، الله أكبر، الله أكبر ولله الحمد، الله أكبر كبيرًا، والحمد لله كثيرًا، وسبحان الله بكرةً وأصيلًا، يكثر من هذا الذكر، ومن الدعاء، في سعيه وطوافه، وهكذا في يوم عرفة، إذا وقف بعد صلاة الجمع، الظهر العصر، يقف بعرفة مستقبلًا القبلة، ويرفع يديه في أي جزء منها كل عرفة موقف، في أي مكانٍ .... يرفع يديه، ويلح في الدعاء، ويكثر من الدعاء، ويكثر من الصلاة على النبي ﷺ .... في دعائه.  فإن حمد الله، والثناء عليه، والصلاة على النبي ﷺ من أسباب الإجابة، فيكثر في دعواته من الصلاة على النبي ﷺ، مع حمد الله، مع الثناء على الله، يصلي على النبي ﷺ في الصفا وفي المروة وفي عرفة وفي مزدلفة، وفي جميع أدعيته، في كل مكان، والبداءة بالحمد والثناء مع الصلاة على النبي ﷺ من أسباب الإجابة، كما في حديث فضالة بن عبيد : أن النبي ﷺ سمع رجلًا دعا، ولم يحمد الله، ولم يصل على النبي ﷺ قال: عجل هذا ثم قال: إذا دعا أحدكم؛ فليبدأ بتحميد ربه، والثناء عليه، ثم يصلي على النبي ﷺ ثم يدعو بما شاء فدل ذلك على أنه إذا بدأ بالحمد، والتمجيد، والثناء على الله، ثم بالصلاة على النبي ﷺ كان هذا من أسباب الإجابة. ومن ذلك: الخشوع والإقبال على الله، حضور القلب، كونه يدعو بقلبٍ حاضر، يعظم الله، ويخضع له، ويعلم أنه مجيب الدعاء، وأنه جواد كريم، وأن العبد فقير إليه، وأنه الغني الحميد سبحانه، إحضار القلب، والشعور بأنك عبد ذليل، وأن الله هو الحكيم العليم، وهو العلي الكبير، مستحق لأن تعبده، وتخضع له، هذا من أسباب الإجابة. وهكذا في صلاتك، في أيام الحج وغير الحج، تكثر من الدعاء في السجود، وفي آخر الصلاة قبل أن تسلم بعد التشهد، تكثر من الدعاء أيضًا في صلواتك؛ لأنها محل إجابة. هكذا بين الأذان والإقامة، إن أذن تكثر من الدعاء بين الأذان والإقامة، وتحمد الله، وتصلي على النبي ﷺ، ثم تدعو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10450/الادعية-والاذكار-المشروعة-في-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44901.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":12256,"question":"إحدى الأخوات المستمعات بعثت بسؤالين إلى البرنامج، أحدهما يقول: ذهبت لأداء العمرة، وقبل خروجي من مكة المكرمة، اغتسلت من الدورة الشهرية قبل رؤية الطهارة جهلًا مني، وطفت طواف الوداع، فهل علي دم أو كفارة لفعلي هذا؟ أرشدوني جزاكم الله خيرًا.","title":"حكم طواف المرأة للوداع أثناء حيضها جهلاً منها","answer":"الجواب:  ليس عليك شيء سوى التوبة إلى الله؛ لأنه لا يجوز لك أن تطوفي ومعك الدم؛ لأن الطواف صلاة، وليس عليك وداع، الحائض ما عليها وداع، لا في الحج، ولا في العمرة، التي معها دم الحيض ليس عليها وداع، لا في الحج ولا في العمرة. ثم العمرة ليس لها وداع واجب، من شاء ودع، ومن شاء ترك، الوداع في العمرة مستحب، وليس بواجب على الصحيح، أما في الحج فيجب الوداع، ولكن الحائض لا وداع عليها، لا في الحج، ولا في العمرة حتى تطهر، فإذا خرجت من مكة وهي حائض؛ فلا وداع عليها، وليس لها أن تطوف وهي حائض، هذا لا يجوز، فعليك التوبة إلى الله من ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10456/حكم-طواف-المراة-للوداع-اثناء-حيضها-جهلا-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44907.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":12308,"question":"المستمع (ع. ع. المصري) من جمهورية مصر العربية بعث برسالة يقول فيها: حجيت العام الماضي، وقد طفت طواف الوداع، وأنا غير متوضئ، كنت ناسيًا الوضوء، ولم أتذكر إلا فيما بعد، لكنني لم أعد الطواف، هل علي شيء في ذلك؟ وهل يعتبر حجي صحيحًا، أم لا؟ أرجو التوجيه، جزاكم الله خيرًا.","title":"حكم من طاف للوداع وهو غير متوضئ ناسياً","answer":"الجواب:  نعم حجك صحيح، ولكنه ناقص؛ لعدم طواف الوداع، وعليك دم يذبح في مكة عن ترك الوداع؛ لأنه واجب من واجبات الحج، فتوصي بعض الثقات أن يذبحوا عنك شاة في مكة للفقراء؛ جبرًا لحجك، بدلًا من طواف الوداع الذي تركته. فإن كنت عاجزًا؛ تصم عشرة أيام بدلًا من الذبيحة في بلدك، أما الذبيحة تكون في مكة، أما الصوم ولو في بلدك لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10508/حكم-من-طاف-للوداع-وهو-غير-متوضى-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45314.mp3","categories":["الطواف بالبيت"]},{"id":12351,"question":"هل يصح كشف الوجه للمرأة في المسجد الحرام، أو في السعي، أو أثناء الطواف؟","title":"حكم كشف المرأة وجهها أثناء الطواف والسعي","answer":"الجواب:  ليس لها ذلك، عليها الحجاب في الطواف والسعي وفي جميع الأوقات، إذا كان حولها رجال أجناب، أما إذا كان ما عندها أجنبي؛ فيجوز أن تكشف، الأفضل لها تكشف في صلاتها، لكن إذا كانت في الطواف في السعي الرجال عندها؛ عليها أن تحتجب، وهكذا في مواضع الرجال، ولو رجلًا واحدًا، لقوله -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وقوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، والوجه من أعظم الزينة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10552/حكم-كشف-المراة-وجهها-اثناء-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39911.mp3","categories":["الطواف بالبيت","السعي"]},{"id":12977,"question":"المستمع (ع. ص. س) بعث يسأل ويقول: حجيت وقمت بالطواف أكثر من سبعة أشواط، وكذلك السعي، ورميت الجمرات أكثر من سبع حصيات، فهل حجي صحيح؟","title":"حكم الزيادة في الطواف والسعي والرمي في الحج","answer":"الجواب:  نعم الحج صحيح، إذا كان ما فعلت شيئًا يبطله، أما الزيادة فلا تضر، إذا كنت تعمدت الزيادة هذا غلط، عليك التوبة والاستغفار؛ لأن السنة سبع في الجمار، وسبع في الطواف، وسبع في السعي. فالزيادة التي فعلتها إن كان عن احتياط، شكيت أو احتطت؛ فلا بأس، أما إذا كان تعمدًا منك فهذا لا يجوز الزيادة على ما شرعه الله، ولكن لا يبطل الطواف، ولا السعي، ولا الرمي، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11194/حكم-الزيادة-في-الطواف-والسعي-والرمي-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47009.mp3","categories":["الطواف بالبيت","السعي"]},{"id":13043,"question":"هذا السائل علي عبدالرحمن يقول: هل عليَّ سعي بعد طواف الإفاضة، علمًا بأنني قارن، وسعيت بعد طواف القدوم، فأفيدوني بذلك؟","title":"حكم السعي بعد الإفاضة لمن سعى مع طواف القدوم","answer":"الجواب:  القارن والمفرد ليس عليه إلا سعي واحد، إذا قدم مكة، وطاف، وسعى، وبقي على إحرامه حتى حج؛ ليس عليه شيء آخر، طوافه وسعيه الأول يكفيان عن السعي، يبقى عليه طواف الإفاضة، إذا كان القارن، أو المفرد سعيا مع طواف القدوم، كفاهم السعي الأول، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/11260/حكم-السعي-بعد-الافاضة-لمن-سعى-مع-طواف-القدوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50503.mp3","categories":["الطواف بالبيت","السعي"]},{"id":13074,"question":"هل من يقضي فترة من الزمن في مكة المكرمة بعد الحج لمدة أكثر من شهرين لا بد أن يطوف طواف الوداع، وهل عليه شيء إذا لم يفعل هذا الركن؟","title":"حكم طواف الوداع","answer":"الجواب:  إذا أراد السفر يطوف للوداع وهو واجب، هو واجب، ليس بركن، ولكنه واجب، إذا تركه؛ عليه دم، يذبح في مكة للفقراء، سواء أقام أيامًا قليلة، أو شهرًا، أو شهرين، أو أكثر، إذا أراد السفر؛ يطوف للوداع سبعة أشواط بالبيت من دون سعي، يطوف سبعة أشواط، ويصلي ركعتين عند السفر، يقول النبي ﷺ: لا ينفرن أحد منكم - يعني: الحجاج - حتى يكون آخر عهده بالبيت اللهم صل عليه وسلم.. إلا الحائض والنفساء إذا صادف وقت السفر وهي في الحيض، أو في النفاس؛ لا وداع عليها.","link":"https://binbaz.org.sa/fatwas/11291/حكم-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50706.mp3","categories":["الطواف بالبيت"]},{"id":13150,"question":"سماحة الشيخ! هذا السائل مصري، ومقيم بجدة يقول في سؤاله: لقد وفقني الله  من أداء فريضة الحج هذا العام، ولكن هناك خطأ وقعت فيه، وهو أنني انتقض وضوئي في الشوط الخامس من طواف الوداع بخروج ريح، وذلك لعدم تمكني من التحكم في خروج الريح لمدة طويلة، وقمت بإتمام باقي الأشواط بدون تجديد الوضوء، وعندما رجعت، وسألت علمت بأنه لابد للطواف من وضوء، ماذا أفعل حتى يكتمل حجي، ويصبح صحيحًا -إن شاء الله-؟وجزيتم خيرًا.","title":"حكم من طاف طواف الوداع على غير طهارة","answer":"الجواب: من شرط الطواف الطهارة كالصلاة، هذا هو الذي عليه جمهور أهل العلم، فإذا أحدث الإنسان في الطواف؛ وجب عليه أن يعيده من أوله، فإن ذهب إلى بلاده، ولم يعد طواف الوداع؛ فعليه دم يذبح في مكة للفقراء، إذا كنت ذهبت إلى وطنك، ولم تعد الطواف؛ فإن عليك دمًا، يعني: شاة، رأسًا من الغنم، جذع ضأن، أو ثني ماعز، أو سبع بدنة، أو سبع بقرة؛ يجزئ في الضحية، يذبح في مكة للفقراء، ويوزع على الفقراء؛ لأن طواف الوداع ذهب، وهو واجب من الواجبات، فيجب عليك دم يذبح في مكة للفقراء، نعم. المقدم: يوصي -يا سماحة الشيخ- أحد الإخوان مثلًا في مكة؟  الشيخ: يوكل من يراه إذا وصى كفى، إذا وكل إنسانًا ثقة؛ كفى. المقدم: طيب، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11404/حكم-من-طاف-طواف-الوداع-على-غير-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51010.mp3","categories":["الطواف بالبيت"]},{"id":13246,"question":"السائل يقول: إذا دخلت الحرم، ولم أطف، هل علي شيء؟","title":"حكم الطواف لداخلي المسجد الحرام","answer":"الجواب:  لا حرج، إن طاف؛ فهو أفضل، إذا تيسر ذلك، وإلا فيصل ركعتين تحية المسجد؛ لقوله ﷺ: إذا دخل أحدكم المسجد؛ فلا يجلس حتى يصلي ركعتين إذا دخل المسجد الحرام، إن تيسر له الطواف؛ فهو أفضل، ثم يصلي ركعتين بعد الطواف، فإن كان عنده كسل، أو زحام، وأحب أن يجلس؛ فلا بأس، لكن يصلي ركعتين قبل أن يجلس تحية المسجد، هذا هو السنة في المسجد الحرام، وغيره من المساجد. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/11531/حكم-الطواف-لداخلي-المسجد-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51312%20.mp3","categories":["الطواف بالبيت"]},{"id":13271,"question":"يقول هذا السائل: هل يلزم الطهارة في السعي والطواف؟","title":"حكم اشتراط الطهارة في الطواف والسعي","answer":"الجواب:  الطهارة لابد منها في الطواف، الطواف صلاة كما قال ابن عباس -رضي الله عنهما-: الطواف بالبيت صلاة إلا أن الله أباح فيه الكلام تقول عائشة -رضي الله عنها-: لما قدم النبي مكة -عليه الصلاة والسلام- وأتى المسجد الحرام، توضأ ثم طاف فالطواف بالبيت صلاة، يتوضأ ثم يطوف. أما السعي لا، إن طاف بطهارة؛ فهو أفضل، وإن سعى على غير طهارة؛ فلا حرج، أما الطواف بالكعبة لابد من الطهارة كالصلاة، يطوف متطهرًا، ثم يصلي ركعتين. أما السعي بين الصفا والمروة فهذا إن تطهر فهو أفضل، وإن سعى على غير طهارة؛ فلا حرج؛ ولهذا لو سعت الحائض والنفساء؛ صح سعيها، بخلاف الطواف، فلو طافت المرأة وهي طاهرة، ثم حاضت بعد الطواف؛ سعت ولا حرج. نعم.","link":"https://binbaz.org.sa/fatwas/11555/حكم-اشتراط-الطهارة-في-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51407.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":13365,"question":"هذا السائل يقول في هذا  ما هو القول الصحيح سماحة الشيخ في طواف الوداع بالنسبة للعمرة، هل هو واجب؟","title":"ما هو القول الصحيح في طواف الوداع بالنسبة للعمرة؟","answer":"الجواب: الأظهر من أقوال العلماء أنه مستحب، وليس بواجب؛ لأنه ليس هناك دليل في وجوب طواف العمرة، إنما أمر النبي ﷺ الحجاج أن يطوفوا للوداع، فقال للحجاج: لا ينفرن أحد منكم حتى يكون آخر عهده بالبيت وقال ابن عباس: \"أمر الناس-يعني الحجاج- أن يكون آخر عهدهم بالبيت\" ولم يأت أنه أمر العمار أن يطوفوا بالبيت للوداع. ولما اعتمر أهل الجعرانة لم يودع، وهكذا لما اعتمر عمرة القضاء لم يودع فيما علمنا من السنة، فهذا لبيان الجواز، وأنه لا وداع على معتمر، والمعتمرون لما أحلوا من عمرتهم في رابع ذي الحجة، وخرجوا مع إبلهم؛ لم يأمرهم بالوداع، الذين خرجوا بعد العمرة مع إبلهم .. ومع أنها مسافات بعيدة للراعي. المقصود: أن الأفضل الوداع، لكن ليس عليه دليل، ثم العمرة مشروعة دائمًا، وتتكرر في السنة، وقد يأتي مرات كثيرة، فأمرها واسع، ليس فيه تشديد. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11652/ما-هو-القول-الصحيح-في-طواف-الوداع-بالنسبة-للعمرة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52407.mp3","categories":["الطواف بالبيت"]},{"id":13407,"question":"السائلة نورة من الرياض لها مجموعة من الأسئلة تقول: أخذت عمرة في شهر رمضان المبارك، ولم أطف طواف الوداع بحجة الزحام، هل علي شيء في ذلك؟","title":"حكم من اعتمر ولم يطف طواف الوداع","answer":"الجواب: العمرة ليس لها طواف وداع، الحمد لله، إن طاف للوداع؛ فهو مستحب، وإلا فليس بلازم، طواف الوداع واجب للحج، أما العمرة فلا يجب لها طواف وداع، ولكن إذا طاف للوداع؛ حسن إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/11698/حكم-من-اعتمر-ولم-يطف-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52605.mp3","categories":["الطواف بالبيت","قضايا المرأة"]},{"id":13742,"question":"في ثاني أسئلته يقول: اختلف الإخوة هل للعمرة طواف وداع، فنرجو من سماحتكم بيان ذلك مأجورين؟","title":"هل للعمرة طواف وداع؟","answer":"الجواب: الصواب: أنه لا وداع لها؛ لأنها تشرع في جميع السنة، فليس لها وداع، لكن إذا وادع؛ لا بأس، حسن -إن شاء الله- إذا مكث بعد العمرة يومًا، يومين، ما سافر في الحال، إذا وادع حسن، أما إذا طاف وسعى وقصر، ثم خرج ما لها وداع. المقدم: إذا كان يكرر العمرة يا شيخ؟  الشيخ: مطلقة، ليس لها وداع ... لكن من ودع؛ فلا حرج، جزاه الله خيرًا، لكن ليس لها وداع؛ لأن الرسول ﷺ ما أمر العمار بالوداع، ولما قدموا معه في حجة الوداع، وأدوا العمرة، ما قال لهم: لا تخرجوا إلا بوداع، وكانوا يخرجون مع الإبل يرعونها في محلات بعيدة، ولم يأمرهم بالوداع، وقد يخرج منهم بعض الناس للطائف، أو جدة، أو غيرها، ولم يقل: لا يخرج أحد إلا مودع، إنما قال للحجاج قال: لا ينفرن أحد منكم كانوا ينصرفون في كل وجه بعد الحج، فقال ﷺ: لا ينفر أحد حتى يكون آخر عهده بالبيت.","link":"https://binbaz.org.sa/fatwas/12120/هل-للعمرة-طواف-وداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53514.mp3","categories":["الطواف بالبيت"]},{"id":13747,"question":"في ثاني أسئلته يقول: اختلف الإخوة هل للعمرة طواف وداع، فنرجو من سماحتكم بيان ذلك مأجورين؟","title":"هل للعمرة طواف وداع؟","answer":"الجواب: الصواب: أنه لا وداع لها؛ لأنها تشرع في جميع السنة، فليس لها وداع، لكن إذا وادع؛ لا بأس، حسن -إن شاء الله- إذا مكث بعد العمرة يومًا، يومين، ما سافر في الحال، إذا وادع حسن، أما إذا طاف وسعى وقصر، ثم خرج ما لها وداع. المقدم: إذا كان يكرر العمرة يا شيخ؟  الشيخ: مطلقة، ليس لها وداع ... لكن من ودع؛ فلا حرج، جزاه الله خيرًا، لكن ليس لها وداع؛ لأن الرسول ﷺ ما أمر العمار بالوداع، ولما قدموا معه في حجة الوداع، وأدوا العمرة، ما قال لهم: لا تخرجوا إلا بوداع، وكانوا يخرجون مع الإبل يرعونها في محلات بعيدة، ولم يأمرهم بالوداع، وقد يخرج منهم بعض الناس للطائف، أو جدة، أو غيرها، ولم يقل: لا يخرج أحد إلا مودع، إنما قال للحجاج قال: لا ينفرن أحد منكم كانوا ينصرفون في كل وجه بعد الحج، فقال ﷺ: لا ينفر أحد حتى يكون آخر عهده بالبيت.","link":"https://binbaz.org.sa/fatwas/12120/هل-للعمرة-طواف-وداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53514.mp3","categories":["الطواف بالبيت"]},{"id":13940,"question":"هل يجوز للمرأة أن ترفع صوتها أثناء الدعاء وهي تطوف حول الكعبة المشرفة؟","title":"حكم رفع المرأة صوتها بالدعاء أثناء الطواف","answer":"الجواب: الأفضل السر لأنها عورة، فالأفضل خفض الصوت؛ لأن الصوت قد يكون فيه رخامة، وقد ربما يفتن بعض الناس، فالأفضل السر بصوتها، ويجوز لها أن تحدث مع الناس بصوتها العادي، ولكن لا تخفض الخفض الذي يطمع الناس فيها؛ لأن الله قال جل وعلا: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] لا تخضع تكسر صوتها، لكن تتكلم كلامًا متوسط ليس فيه نكارة وليس فيه تغنج ولا خضوع، كلام وسط والسر أفضل، في الطواف والتلبية كونها تسر أفضل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12344/حكم-رفع-المراة-صوتها-بالدعاء-اثناء-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48213.mp3","categories":["الطواف بالبيت"]},{"id":14026,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (س. ع) أخونا له جمع من الأسئلة في أحدها يقول: هل الاضطباع في الطواف في الحج أو في جميع نوافل العمرة؟ نرجو أن توجهونا جزاكم الله خيرًا.","title":"في أي طواف يكون الاضطباع؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالاضطباع مشروع في الطواف الأول، وهو طواف القدوم في حق الحاج والمعتمر جميعًا، أول طواف يأتي به الحاج أو المعتمر أول ما يقدم يستحب له فيه الاضطباع.\nوالاضطباع: هو أن يجعل وسط ردائه تحت إبطه الأيمن، وطرفيه على عاتقه الأيسر هذا هو الاضطباع، الرداء يكون وسطه تحت إبطه الأيمن، ويكون طرفاه على عاتقه الأيسر، ويكون عضده مكشوف، عضده الأيمن يكون مكشوفًا، هكذا فعل النبي عليه الصلاة والسلام، وإذا فرغ من الطواف عدل رداءه، جعله على عاتقيه وجعل طرفيه على صدره قبل أن يصلي ركعتين، حتى يصلي ورداءه قد عدل، يعني: قد جعل على عاتقيه وأسدل على صدره، هذا هو السنة التي فعلها المصطفى عليه الصلاة والسلام. وهكذا في طواف القدوم يستحب له الرمل أيضًا، في طواف القدوم في الحج والعمرة جميعًا، والرمل هو السرعة في الأشواط الثلاثة من طواف القدوم، وأنه يهرول في طواف القدوم في الثلاثة الأولى، ويمشي في الأربعة، هذا يقال له: الرمل، فعله النبي ﷺ في الطواف الأول، في عمرته وفي حجه عليه الصلاة والسلام.. يهرول في الثلاثة الأول، يعني: يخب فيها خبًا، وفي الأربعة الأخيرة يمشي إذا تيسر ذلك، أما إن كان زحمة ما يتيسر فلا حرج تسقط يسقط عنه الرمل، لكن إذا كان في سعة فإنه يرمل في الأشواط الثلاثة الأولى، ويمشي في الأربعة. أما الاضطباع فإنه يكون في جميع الطواف في السبعة كلها، يضطبع في السبعة كلها في طواف القدوم خاصة، وهو أنه يجعل وسط ردائه تحت إبطه الأيمن ويجعل طرفيه على عاتقه الأيسر في جميع الطواف، فإذا فرغ من الطواف جعل رداءه على عاتقيه، وصلى في ردائه هكذا صلاة الطواف وما بعدها نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12446/في-اي-طواف-يكون-الاضطباع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48401.mp3","categories":["الطواف بالبيت"]},{"id":14096,"question":"رسالة وصلت إلى البرنامج من مدينة الطائف باعثتها إحدى الأخوات من هناك تقول: أم عبد الله، أم عبد الله لها تسعة أسئلة.تسأل في سؤالها الأول وتقول: أفيدكم بأنني ذهبت إلى العمرة وأنا امرأة مريضة، وعندما دخلت إلى الحرم وطفت على الكعبة ثلاثة أشواط أصبت بدوخة، ولم أستطع أن أكمل الطواف، ماذا يجب علي أن أفعل؟","title":"ما يعمل من جاءته دوخة وهو في الطواف؟","answer":"الجواب: عليك أن تكملي الطواف، تستريحي ثم تكملي، فإن طال الفصل أعيديه من أوله، إذا طال الفصل وأنت في الدوخة؛ تعيدين الطواف من أوله، أما إذا زالت بسهولة وسرعة؛ تكملي الطواف والحمد لله، فإن طال الفصل؛ تعيدي الطواف من أوله، وإن أحدثت؛ تعيدي الطهارة ثم تبتدئي الطواف من أوله، والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12525/ما-يعمل-من-جاءته-دوخة-وهو-في-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61003.mp3","categories":["الطواف بالبيت"]},{"id":14146,"question":"السائل هذا يقول في سؤاله: بالنسبة لمن طاف طواف الوداع في الصباح هل له أن ينام ثم يسافر في العصر؟","title":"هل يجوز التأخر إلى العصر لمن طاف الوداع صباحًا؟","answer":"الجواب: لا حرج إن شاء الله، .. مثل هذا يسمى مودعًا، فإذا طاف الصبح واستراح الضحى أو الظهر ثم سافر الظهر أو العصر فلا حرج إن شاء الله؛ لأن هذا ما يمنع كونه ودع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12587/هل-يجوز-التاخر-الى-العصر-لمن-طاف-الوداع-صباحا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54611.mp3","categories":["الطواف بالبيت"]},{"id":14465,"question":"المستمع: (م. ع. خ) من الرياض، يقول في رسالة بعث بها إلى البرنامج: قبل فترة اعتمرنا، وقمنا بكل الشعائر المطلوبة للعمرة، إلا أننا لم نقم بطواف الوداع، هل طواف الوداع واجب على المعتمر؟ وهل علينا كفارة؟ وما هي؟أفيدونا، جزاكم الله خيرًا.","title":"حكم طواف الوداع على المعتمر","answer":"الجواب: طواف الوداع ليس بواجب على المعتمر، إنما هو واجب في حق الحجاج، وأما المعتمرون فلم يأمرهم النبي ﷺ بالوداع، وقد اعتمر معه جم غفير فلم يأمرهم بالوداع -عليه الصلاة والسلام-، لا في عمرة القضاء، ولا في عمرة حجه -عليه الصلاة والسلام-، وكانوا يخرجون من مكة مع إبلهم إلى مسافة بعيدة للرعي، ولا يأمرهم بالوداع، فالمعتمر ليس عليه وداع، وإذا ودع من باب التقرب إلى الله فهذا حسن، و لكن ليس بواجب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12956/حكم-طواف-الوداع-على-المعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_632/nour_63205.mp3","categories":["الطواف بالبيت"]},{"id":14574,"question":"هذا سائل للبرنامج رمز لاسمه بـ (أ. أ) يقول: سماحة الشيخ، إذا دخل المصلي للمسجد الحرام في مكة، فهل يصلي ركعتين، أو يطوف حول البيت، وإذا لم يطف بالبيت بسبب قرب الصلاة فهل يصلي ركعتين تحية المسجد، وهل ينطبق الحكم على المعتمر؟","title":"أيهما يقدم الطواف أم ركعتي التحية؟","answer":"الجواب: إذا دخل المسلم المسجد الحرام فالسنة له أن يطوف، ثم يصلي ركعتين، فإن لم يتيسر ذلك، أو كسل عن هذا، أو كانت الصلاة قريبة لتقام، فإنه يصلي ركعتين تحية المسجد، سواء كان حاجًا أو معتمرًا أو مقيمًا في البلد، إن بدأ بالطواف فهو الأفضل، إذا تيسر ذلك، وإن كان هناك أسباب تمنع البداءة بالطواف صلى ركعتين، ثم يطوف لحجه وعمرته بعد ذلك، لكن لا يجلس حتى يصلي ركعتين تحية المسجد، إلا إذا جاء والصلاة قد قامت دخل معهم في الصلاة، والحمد لله، ثم يطوف بعد ذلك، لكن إذا جاء قبل أن تقام الصلاة، فإما أن يبدأ بالطواف، وإما أن يصلي ركعتين، ويجلس ينتظر الصلاة، ثم يطوف بعد ذلك؛ لقوله ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين وهذا عام يعم المسجد الحرام والمسجد النبوي وغيرهما من المساجد، وكان النبي ﷺ في عمره وحجه يبدأ بالطواف، إذا دخل المسجد بدأ بالطواف -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/13071/ايهما-يقدم-الطواف-ام-ركعتي-التحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55612.mp3","categories":["الطواف بالبيت"]},{"id":14612,"question":"السائلة فاطمة عبدالله تقول: من ترك طواف الإفاضة في الحج هل عليه شيء؟وجزاكم الله خيرًا","title":"ما يلزم من ترك طواف الإفاضة؟","answer":"الجواب: طواف الإفاضة ركن، لا بد منه، الذي تركه يعود إذا سافر، ولم يطف طواف الإفاضة، طواف الحج يعود، سواء الرجل وإلا المرأة، ما يتم حجه إلا يعود ويطوف، ولو كانت امرأة وأتاها زوجها قبل أن تطوف يكون عليها دم، يذبح في مكة للفقراء، مع التوبة، وإن كان زوجها ما طاف كذلك عليه دم أيضًا، والتوبة إلى الله. فطواف الإفاضة ركن بإجماع المسلمين لا بد منه؛ لقوله -جل وعلا-: ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ [الحج:29] هذا طواف الإفاضة، وقد طاف النبي ﷺ طواف الإفاضة في يوم العيد وقال: خذوا عني مناسككم اللهم صل عليه وسلم. أما طواف الوداع لو تركه عند الخروج يأثم، وعليه دم، ويصح الحج، أما طواف الإفاضة طواف الحج هذا لا بد منه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13108/ما-يلزم-من-ترك-طواف-الافاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55906.mp3","categories":["الطواف بالبيت"]},{"id":14804,"question":"المستمع: (خ .م . د) بعث برسالة وضمنها عددًا من الأسئلة، له سؤال طويل جدًا يقول فيه:في عام ألف وأربعمائة وسبعة، أديت فريضة الحج مع زوجتي، وهي كانت حامل، وأديت جميع المناسك الحمد لله بيسرٍ وسهولة، ولكن عند رجم الشيطان في اليوم الثاني، لم أتمكن من رمي الجمرة الثالثة، وكانت زوجتي قد وكلتني برمي جميع الجمرات لها؛ لأنها لم تتمكن من رميها، فإني حائر، وسألت عدة أشخاصٍ عن ذلك، بعضهم يقول لي: حجك صحيح، والبعض يقول لي: يتوجب عليك أن تذبح هدي؛ علمًا بأنني ذبحت هديًا واحدًا فقط لي، وهذا كان أول يوم العيد، قبل أن أرمي الجمرة الثانية؛ لأني قلت: يمكن أنني أنقصت شيئًا من المناسك، وحيث أنني لم أتمكن من رمي الجمرة الثالثة في اليوم الثاني، بعد أن ذبحت في اليوم الأول، هل يجوز لي أن أذبح مرةً أخرى، أم أكتفي بالذبح في المرة الأولى؟وهل أذبح لزوجتي التي وكلتني برمي الجمرات لها؟ وإذا ذبحت لها الآن، هل يجوز ذلك أم وقت الحج؟ أرجو أن تفيدوني عن هذه القضايا. جزاكم الله خيرًا.كما أود إفادتكم بأنني سألت أحد الإخوة وهو إمام جامعٍ في أحد المساجد، وقد أفادني وقال لي: يمكنك أن تتصدق بثمن الهدي بشراء أحد التفاسير الدينية، وتتبرع بها بدلًا من أن تذبح، وفي نفس الوقت قال لي: نقرأ الفاتحة على الرسول ﷺ، وذلك باعتباري وعد مني بإرسال هذه التفاسير، بثمن الهدي، وأنا الآن محتار، وأخاف أن أكون قد أخلفت وعدي، وهل قراءة الفاتحة على الرسول ﷺ بهذه الصورة تعتبر وعدًا كما فعل هذا الشخص؟ وهل يجوز إرسال هذه التفاسير له باعتبارها بدلًا عن الهدي؟كما أفيدكم أيضًا بأنني لم أقم بعمل طواف الوداع، عند انتهائي من الحج، وذلك حسب ما سمعته من الإخوان الذين كانوا معي، قالوا لي: باعتبارك مقيم في المملكة؛ فلا يجب عليك طواف الوداع، سواء أديته أو لم تؤده، هل هذا صحيح، أم حجي ناقص؟ وهل يجوز أن أطوف مرةً ثانية بنية طواف الوداع؟ وهل يجوز لي ذبح هديٍ في هذه الحالة؛ لأني سمعت في إحدى الحلقات في برنامج: نور على الدرب، أحد الإخوة يسأل بأنه إذا لم يطف وسافر كانت الإجابة عليه أن يأتي إلى مكة ويطوف ويذبح هدي، إذا جامع زوجته، في طوال هذه المدة هل ينطبق علي ذلك أم يوجد حكم آخر على هذا الطواف؟وجهوني، جزاكم الله خيرًا.","title":"حكم من ترك رمي الجمرة الثالثة وطواف الوداع","answer":"الجواب: ليس عليك إلا فدية عن ترك الرمي، وعلى الزوجة أيضًا، فعليكما فديتان، عنك ذبيحة، وعنها ذبيحة، إذا كانت الذبيحة التي ذبحتها لم تقصد بها ذبيحة ترك الرمي، وإنما قصدت بها شيئًا آخر، فعليك ذبيحة واحدة عن نفسك، وذبيحة أخرى عن زوجتك، بسبب ترك الرمي، وهذه الذبيحة مثل الضحية، جذع ضأن، أو ثني معز، سليم من العيوب، يذبح في مكة للفقراء، والمساكين، سواء توليته بنفسك، أو وكلت ثقةً في مكة يقوم بذلك. وأما طواف الوداع فهو واجب، والذي قال: ليس عليك وداع وأنت في السعودية، هذا غلط، هذا جهل بحت، بل عليك ذبيحة أيضًا عن ترك الوداع؛ لأنه واجب، على الحاج إذا فرغ من حجه، وأراد السفر؛ أن يطوف للوداع؛ لقول النبي ﷺ: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت ولقول ابن عباس -رضي الله عنهما-: \"أمر الناس -يعني: أمرهم النبي- أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فالمرأة الحائض والنفساء ليس عليهما وداع، وأما أنت عليك وداع، فلما تركته، فعليك ذبيحة تذبح في مكة للفقراء، مثل الضحية، جذع ضأن، أو ثني معز. وأما الذي قال لك: تخرج القيمة، فقد غلط، وهذا جهل منه، وهو يدل على عدم بصيرته، وأنه يقول على الله بغير علم، فالثمن لا يجزئ، سواء جعل في كتب للتفسير، أو غيره، إخراج القيمة أو الصدقة بالكتب، كل ذلك لا يقوم مقام الهدي. كذلك قراءة الفاتحة للنبي ﷺ بدعة، لا أساس لها، فنوصيك بالحذر من سؤال من لا يعرف بالعلم، والفضل، والبصيرة في الدين، لا تسأل إلا أهل العلم المعروفين بالورع، والعلم، والبصيرة في دين الله، والسمعة الحسنة؛ لأن كثيراً من الناس يقول على الله بغير علم، ويفتي على غير بصيرة، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13305/حكم-من-ترك-رمي-الجمرة-الثالثة-وطواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64206.mp3","categories":["الطواف بالبيت","السعي","رمي الجمار"]},{"id":14812,"question":"المستمع: (خ .م . د) بعث برسالة وضمنها عددًا من الأسئلة، له سؤال طويل جدًا يقول فيه:في عام ألف وأربعمائة وسبعة، أديت فريضة الحج مع زوجتي، وهي كانت حامل، وأديت جميع المناسك الحمد لله بيسرٍ وسهولة، ولكن عند رجم الشيطان في اليوم الثاني، لم أتمكن من رمي الجمرة الثالثة، وكانت زوجتي قد وكلتني برمي جميع الجمرات لها؛ لأنها لم تتمكن من رميها، فإني حائر، وسألت عدة أشخاصٍ عن ذلك، بعضهم يقول لي: حجك صحيح، والبعض يقول لي: يتوجب عليك أن تذبح هدي؛ علمًا بأنني ذبحت هديًا واحدًا فقط لي، وهذا كان أول يوم العيد، قبل أن أرمي الجمرة الثانية؛ لأني قلت: يمكن أنني أنقصت شيئًا من المناسك، وحيث أنني لم أتمكن من رمي الجمرة الثالثة في اليوم الثاني، بعد أن ذبحت في اليوم الأول، هل يجوز لي أن أذبح مرةً أخرى، أم أكتفي بالذبح في المرة الأولى؟وهل أذبح لزوجتي التي وكلتني برمي الجمرات لها؟ وإذا ذبحت لها الآن، هل يجوز ذلك أم وقت الحج؟ أرجو أن تفيدوني عن هذه القضايا. جزاكم الله خيرًا.كما أود إفادتكم بأنني سألت أحد الإخوة وهو إمام جامعٍ في أحد المساجد، وقد أفادني وقال لي: يمكنك أن تتصدق بثمن الهدي بشراء أحد التفاسير الدينية، وتتبرع بها بدلًا من أن تذبح، وفي نفس الوقت قال لي: نقرأ الفاتحة على الرسول ﷺ، وذلك باعتباري وعد مني بإرسال هذه التفاسير، بثمن الهدي، وأنا الآن محتار، وأخاف أن أكون قد أخلفت وعدي، وهل قراءة الفاتحة على الرسول ﷺ بهذه الصورة تعتبر وعدًا كما فعل هذا الشخص؟ وهل يجوز إرسال هذه التفاسير له باعتبارها بدلًا عن الهدي؟كما أفيدكم أيضًا بأنني لم أقم بعمل طواف الوداع، عند انتهائي من الحج، وذلك حسب ما سمعته من الإخوان الذين كانوا معي، قالوا لي: باعتبارك مقيم في المملكة؛ فلا يجب عليك طواف الوداع، سواء أديته أو لم تؤده، هل هذا صحيح، أم حجي ناقص؟ وهل يجوز أن أطوف مرةً ثانية بنية طواف الوداع؟ وهل يجوز لي ذبح هديٍ في هذه الحالة؛ لأني سمعت في إحدى الحلقات في برنامج: نور على الدرب، أحد الإخوة يسأل بأنه إذا لم يطف وسافر كانت الإجابة عليه أن يأتي إلى مكة ويطوف ويذبح هدي، إذا جامع زوجته، في طوال هذه المدة هل ينطبق علي ذلك أم يوجد حكم آخر على هذا الطواف؟وجهوني، جزاكم الله خيرًا.","title":"حكم من ترك رمي الجمرة الثالثة وطواف الوداع","answer":"الجواب: ليس عليك إلا فدية عن ترك الرمي، وعلى الزوجة أيضًا، فعليكما فديتان، عنك ذبيحة، وعنها ذبيحة، إذا كانت الذبيحة التي ذبحتها لم تقصد بها ذبيحة ترك الرمي، وإنما قصدت بها شيئًا آخر، فعليك ذبيحة واحدة عن نفسك، وذبيحة أخرى عن زوجتك، بسبب ترك الرمي، وهذه الذبيحة مثل الضحية، جذع ضأن، أو ثني معز، سليم من العيوب، يذبح في مكة للفقراء، والمساكين، سواء توليته بنفسك، أو وكلت ثقةً في مكة يقوم بذلك. وأما طواف الوداع فهو واجب، والذي قال: ليس عليك وداع وأنت في السعودية، هذا غلط، هذا جهل بحت، بل عليك ذبيحة أيضًا عن ترك الوداع؛ لأنه واجب، على الحاج إذا فرغ من حجه، وأراد السفر؛ أن يطوف للوداع؛ لقول النبي ﷺ: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت ولقول ابن عباس -رضي الله عنهما-: \"أمر الناس -يعني: أمرهم النبي- أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فالمرأة الحائض والنفساء ليس عليهما وداع، وأما أنت عليك وداع، فلما تركته، فعليك ذبيحة تذبح في مكة للفقراء، مثل الضحية، جذع ضأن، أو ثني معز. وأما الذي قال لك: تخرج القيمة، فقد غلط، وهذا جهل منه، وهو يدل على عدم بصيرته، وأنه يقول على الله بغير علم، فالثمن لا يجزئ، سواء جعل في كتب للتفسير، أو غيره، إخراج القيمة أو الصدقة بالكتب، كل ذلك لا يقوم مقام الهدي. كذلك قراءة الفاتحة للنبي ﷺ بدعة، لا أساس لها، فنوصيك بالحذر من سؤال من لا يعرف بالعلم، والفضل، والبصيرة في الدين، لا تسأل إلا أهل العلم المعروفين بالورع، والعلم، والبصيرة في دين الله، والسمعة الحسنة؛ لأن كثيراً من الناس يقول على الله بغير علم، ويفتي على غير بصيرة، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13305/حكم-من-ترك-رمي-الجمرة-الثالثة-وطواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64206.mp3","categories":["الطواف بالبيت","السعي","رمي الجمار"]},{"id":14939,"question":"من جمهورية مصر العربية، بعث الأخ فتحي أحمد فاضل بهذه الرسالة، يقول: أنه أعرفكم بأني حجيت هذا العام، وفي اليوم الأخير ذهبت لأداء طواف الوداع، وبعد الطواف أذن العصر، فصليت العصر بالحرم، وبعد ذلك ذهبت إلى مزدلفة، فوجدت أحد زملائي لم يحضروا إلى السيارة، فأذن المغرب وصليت المغرب بمزدلفة، وبعد الصلاة سافرت من مزدلفة إلى الرياض، فما الحكم في ذلك؟أفيدوني، جزاكم الله عنا خيرًا، هو في الحقيقة يسأل عن تأخره.","title":"حكم التأخر بمزدلفة بعد طواف الوداع","answer":"الجواب: لا حرج في ذلك، لا حرج في ذلك، إذا ودع الإنسان ثم صلى العصر أو صلى المغرب أو صلى العشاء أو الفجر لا حرج في ذلك، النبي ﷺ ودع البيت آخر الليل، وصلى بالناس الفجر يوم أربعة عشر، ثم توجه إلى المدينة بعد الصلاة -عليه الصلاة والسلام-، وكذلك لو صلى، ثم ذهب إلى إخوانه ورفقائه ووجدهم لم يتجهزوا ينتظرون بعض أصحابهم، وجلس معهم حتى حضر من حضر، لا بأس، كل هذه أعذار شرعية في التأخير، وهكذا لو مثلًا تأخر من أجل يأكل عشاء، أو غداء أو إصلاح سيارة أو التماس سائق، كل هذه أمور معفو عنها، لا يضر لا تضر. ثم المزدلفة خارج مكة إذا وصل إلى المزدلفة فقد انتهى من مكة، لو بات فيها لا يضره؛ لأن منى ومزدلفة خارج مكة، فلو أنه ودع وبات في منى، أو في المزدلفة، أو جلس طويلًا ما يضره هذا؛ لأنه خارج مكة، إنما الذي يوجب عليه العودة للطواف لو جلس في مكة، وأقام بين البنيان حتى طالت المدة، فإنه يرجع ويودع إذا طال الأمر.  أما المدة اليسيرة بأن ودع العصر ومشى بعد المغرب أو بعد العشاء أو ودع بعد العشاء ومثلًا مشى في أثناء الليل، أو طاف في أثناء الليل الوداع، ثم مشى في آخر الليل، أو بعد الفجر، كل هذا في سعة -إن شاء الله-، ولا يضر.","link":"https://binbaz.org.sa/fatwas/13433/حكم-التاخر-بمزدلفة-بعد-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_647/nour_64703.mp3","categories":["الطواف بالبيت"]},{"id":14956,"question":"أولًا نبدأ شيخ عبدالعزيز برسالة المستمع المرسل (ع. م) العسيري، يقول في رسالته: إني شاب أبلغ من العمر ما يقارب ثمانية وعشرين عامًا، وقد حجيت لعام تسعة وتسعين وألف وثلاثمائة، وألف وأربعمائة، يقول: عندما أردت مغادرة مكة المكرمة لم آخذ طواف الوداع، وفي الحقيقة ما أدري ماذا يترتب علي في هذه الحالة؟أفيدوني، جزاكم الله عني ألف خير.","title":"ما يلزم من حج وترك طواف الوداع؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله نبينا محمد وعلى آله وأصحابه، ومن تبعهم بإحسان إلى يوم الدين، أما بعد: فلا ريب أن الله  شرع للحاج أن يودع البيت قبل خروجه إلى وطنه، وقد ثبت عن النبي -عليه الصلاة والسلام- أنه قال: لا ينفرن أحد منكم حتى يكون آخر عهده بالبيت رواه مسلم في الصحيح، وقال ابن عباس -رضي الله عنهما-: \"أمر الناس أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" متفق عليه.  والصحيح أن ذلك واجب؛ لأن الأمر أصله الوجوب، والنهي أصله التحريم، فوجب على كل حاج من رجل وامرأة أن يودع البيت قبل أن يغادر مكة إلى وطنه بعد انتهائه من مناسك الحج، بعدما يرمي الجمرات في اليوم الثاني عشر إن تعجل، أو في اليوم الثالث عشر إن لم يتعجل، فإنه بعد ذلك يطوف للوداع سبعة أشواط بالبيت، وليس فيه سعي. فإذا غادر إلى بلاده، ولم يطف هذا الطواف فإن عليه دمًا، يعني: ذبيحة يذبحها في مكة وتوزع بين الفقراء، سواء ذبحها بنفسه أو وكل من يذبحها بمكة، فإن رجع وطاف للوداع أجزأه عند جمع من أهل العلم، ولكن ذبحه للهدي وتوزيعه بين الفقراء أولى وأحوط؛ خروجًا من خلاف من قال: إنه لا يجزئه العودة، مع التوبة والاستغفار، فإن التارك لطواف الوداع قد ترك واجبًا، وترك الواجب معصية، فالواجب التوبة والاستغفار، والندم وعدم العود إلى مثل هذا، مع الفدية المذكورة، وهي ذبيحة من جنس الضحايا والهدايا، يعني: جذع ضأن أو ثني معز، سليم من العيوب، يذبح في مكة، ويقسم بين الفقراء، نعم.","link":"https://binbaz.org.sa/fatwas/13459/ما-يلزم-من-حج-وترك-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_650/nour_65001.mp3","categories":["الطواف بالبيت"]},{"id":14970,"question":"أيضًا يقول: ما حكم من عكس العمرة، فقدم السعي على الطواف وتحلل؟","title":"ما حكم من قدم السعي على الطواف؟","answer":"الجواب: الصواب أنه لا حرج عليه، ولا حرج في تقديم السعي على الطواف، السنة أن يكون بعد الطواف، كما طاف النبي ﷺ وسعى، هذا السنة، لكن من جهل أو نسي؛ صحت عمرته وصح حجه، فإذا سعى قبل الطواف في العمرة، أو سعى قبل الطواف في الحج؛ أجزأه ذلك لأمرين:\nأحدهما: قول النبي ﷺ لما سئل عن أعمال الحج يوم العيد: افعل ولا حرج، افعل ولا حرج سئل عن التقديم والتأخير فكان يقول: افعل ولا حرج قال الراوي: فما سئل يؤمئذٍ عن شيء قدم ولا أخر إلا قال: افعل ولا حرج وهذا يعم الطواف والسعي، وإذا جاز في الحج جاز في العمرة؛ لأن أحكامهما سواء، والحج أعظم. الأمر الثاني: أنه ثبت عنه -عليه الصلاة والسلام- بإسناد صحيح عند أبي داود أن رجلًا سأل النبي ﷺ فقال: «يا رسول الله، سعيت قبل أن أطوف، قال: افعل ولا حرج لما سأله عن السعي قال: لا حرج يعني: السعي قبل الطواف، قال: لا حرج وهذا نص صحيح صريح يؤيد العموم السابق، وهذا قول جماعة من أهل العلم، والأكثر على أنه لا بد من تقديم الطواف على السعي، ولكن الصحيح هو جواز تقديم السعي وإن كان خلاف قول الأكثر؛ لأن المعول هو الدليل، المعول عليه هو الدليل، والله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ..[النساء:59]الآية، ويقول : وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ[الشورى:10]الآية، نعم. المقدم: شكرًا لفضيلة الشيخ عبدالعزيز .","link":"https://binbaz.org.sa/fatwas/13468/ما-حكم-من-قدم-السعي-على-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_649/nour_64907.mp3","categories":["الطواف بالبيت","السعي"]},{"id":14990,"question":"المستمع عبدالله محمد إبراهيم يسأل ويقول: أفيدكم أنني قمت هذه السنة بأداء العمرة، وقد قمت بأدائها على الوجه الشرعي، إلا أنني حين خروجي من مكة المكرمة لم أطف طواف الوداع، لظني أن طواف الوداع واجب من واجبات الحج فقط، ولا علاقة له بكمال العمرة. أرجو إفتائي في حكم عمرتي هذه، وماذا يجب علي في حالة كونها ناقصة؟ جزاكم الله خيرًا، وأخونا من الأردن عمان.","title":"حكم طواف الوداع على المعتمر","answer":"الجواب: العمرة لا يجب لها الوداع، الوداع من خصائص الحج؛ ولهذا لم يأمر النبي ﷺ المعتمرين أن يودعوا، وإنما أمر الحجاج، فقال -عليه الصلاة والسلام-: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت وهو يخاطب الحجيج، وفي حديث ابن عباس: \"أمر الناس -يعني الحجاج- أن يكون آخر عهدهم بالبيت إلا أنه خفف عن المرأة الحائض\". فالحجاج عليهم الوداع أن يطوفوا سبعة أشواط عند الخروج، إلا الحائض والنفساء فليس عليهما وداع.  وأما العمرة فليس لها وداع، لكن إن ودع عند الخروج فلا حرج، والطواف عبادة وخير، فإذا طاف عند الخروج حسن، لكن ليس عليه وداع واجب، المعتمر، سواء كان في أيام الحج، أو في غيرها، قد اعتمر الناس في عهده ﷺ ولم يأمرهم بطواف الوداع، واعتمر المسلمون معه في حجة الوداع ولم يأمرهم بطواف الوداع؛ لما خرجوا إلى منى وعرفات، ولم يقل: من خرج فليودع، وكانوا يخرجون مع إبلهم يرعونها مسافات طويلة، ولم يأمرهم بالوداع لما فرغوا من عمرتهم، وهكذا في عمرة القضاء خرج ولم يذكر عنه أنه ودع -عليه الصلاة والسلام-، وفي عمرة الجعرانة لما فرغ منها خرج ولم يودع -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13479/حكم-طواف-الوداع-على-المعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49212.mp3","categories":["الطواف بالبيت"]},{"id":15025,"question":"أيضًا يقول: ما حكم من نسي ركعتي الطواف، وصلاها بعد السعي؟","title":"حكم من نسي ركعتي الطواف وصلاها بعد السعي","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/13524/حكم-من-نسي-ركعتي-الطواف-وصلاها-بعد-السعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65302.mp3","categories":["الطواف بالبيت"]},{"id":15048,"question":"يقول أيضًا: ما حكم طواف الوداع في العمرة هل يلزم أم لا؟","title":"حكم طواف الوداع في العمرة هل يلزم أم لا؟","answer":"الجواب: الأولى والأصح أنه ليس بواجب، طواف الوداع في العمرة ليس بواجب، وإنما يستحب فقط، فإذا ودع بعد العمرة هذا أفضل وأولى، ولو خرج ولم يودع؛ فلا شيء عليه. أما في الحج فالطواف واجب، في الحج؛ لأن النبي  قال: لا ينفر أحدكم حتى يكون آخر عهده بالبيت وهذا خاطب به الحجيج -عليه الصلاة والسلام-، وقال ابن عباس: \"أمر الناس - يعني: الحجاج- أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فالحائض ليس عليها وداع، وهكذا النفساء ليس عليها وداع،\nوأما العمرة فليس فيها وداع واجب، ولكن مستحب، نعم.","link":"https://binbaz.org.sa/fatwas/13575/حكم-طواف-الوداع-في-العمرة هل-يلزم-ام-لا ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65408.mp3","categories":["الطواف بالبيت"]},{"id":15051,"question":"يقول أيضًا: ما حكم طواف الوداع في العمرة هل يلزم أم لا؟","title":"حكم طواف الوداع في العمرة هل يلزم أم لا؟","answer":"الجواب: الأولى والأصح أنه ليس بواجب، طواف الوداع في العمرة ليس بواجب، وإنما يستحب فقط، فإذا ودع بعد العمرة هذا أفضل وأولى، ولو خرج ولم يودع؛ فلا شيء عليه. أما في الحج فالطواف واجب، في الحج؛ لأن النبي  قال: لا ينفر أحدكم حتى يكون آخر عهده بالبيت وهذا خاطب به الحجيج -عليه الصلاة والسلام-، وقال ابن عباس: \"أمر الناس - يعني: الحجاج- أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فالحائض ليس عليها وداع، وهكذا النفساء ليس عليها وداع،\nوأما العمرة فليس فيها وداع واجب، ولكن مستحب، نعم.","link":"https://binbaz.org.sa/fatwas/13575/حكم-طواف-الوداع-في-العمرة هل-يلزم-ام-لا ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65408.mp3","categories":["الطواف بالبيت"]},{"id":15074,"question":"سماحة الشيخ هذه السائلة تقول: إذا حاضت المرأة صح لها كل شيء في العمرة أو الحج إلا الطواف، كما في الحديث، فهل إذا جاءت المرأة إلى الميقات وهي حائض، فنوت العمرة، وسعت، وبقي لها الطواف، هل تنتظر حتى تطهر، ثم تطوف وتكمل العمرة أم لا؟","title":"حكم من حاضت قبل الطواف للعمرة","answer":"الجواب: الواجب عليها أنها تنتظر، لا يجوز لها أن تطوف وهي حائض، لكن لا ينبغي لها تقديم السعي، السنة أن تؤخر السعي، النبي ﷺ طاف، ثم سعى، فالسنة لها أن تؤخر السعي مع الطواف، هذا هو السنة، فإذا طهرت طافت وسعت، والحمد لله، نعم. المقدم: سماحة الشيخ، إذا لم تستطع الانتظار في مكة حتى تطهر وسافرت هل عليها شيء؟ الشيخ: عليها أن ترجع، إذا سافرت عليها أن يمتنع زوجها -إن كان لها زوج- وعليها أن ترجع، حتى تؤدي العمرة، إذا لم يتيسر لها الانتظار، نعم.","link":"https://binbaz.org.sa/fatwas/13568/حكم-من-حاضت-قبل-الطواف-للعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56406.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":15133,"question":"نبدأ برسالة المستمع (ع. ل. هـ) من بلاد غامد، يقول في رسالته: حججنا حجًا صحيحًا، وذهبنا إلى مكة نريد طواف الوداع فلم يمكننا؛ لأن السائق كان غشيم، ولم يمكنه بأن يلقى خط الحرم، فماذا ترون في حجنا هذا خاصة حج والدتي التي حجت عن والدها، هل يلزمنا في هذا شيء أم لا، أم حجنا مقبول؟وفقكم الله.","title":"ما حكم من حج ولم يطف للوداع؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: طواف الوداع فرض على الصحيح من أقوال العلماء؛ لقول النبي ﷺ: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت رواه مسلم في الصحيح. ولما ثبت في الصحيحين عن ابن عباس -رضي الله عنهما- قال: \"أمر الناس أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فهذا يدل على أن طواف الوداع في الحج مفترض، ومأمور به، إلا على الحائض، ومثلها النفساء فلا وداع عليهما. فالذي خرج ولم يودع بسبب زحمة، أو بسبب جهل السائق، أو ما أشبه ذلك، كل هذا ليس بعذر، فالواجب عليه أن يرجع فيؤدي طواف الوداع، فإن لم يفعل فعليه فدي، يعني: دم يُذبح في مكة، ويوزع بين الفقراء، في أصح قولي العلماء، والفدي قد استقر عليه في السفر، فإذا فدى كفى، وإن رجع وطاف للوداع نرجو أن يكفيه ذلك كما قاله بعض أهل العلم، نعم. وهذا في الحج، أما العمرة فأمرها أوسع، العمرة أمرها أوسع، ليس الوداع فيها واجبًا على الصحيح، وهو قول الجمهور من نقله أبو عمر بن عبد البر -رحمه الله- إجماع أهل العلم بأنه لا وداع للعمرة، ليس فيها وداع واجب، وذهب بعض أهل العلم إلى أن فيها وداع.  والأقرب والأظهر أنه ليس بواجب الوداع فيها؛ لأن الله شرعها في جميع السنة، ورغب في تكرارها، ومما يعين على ذلك عدم وجوب الوداع فيها؛ ولأنه لم يحفظ عنه ﷺ أنه ودع لما اعتمر في عام القضاء، عمرة القضاء، فدل ذلك على أن المراد بالوداع في الحج خاصة، أما العمرة فأمرها أوسع، إن ودع فحسن؛ لأنها حج أصغر، وإن لم يودع فلا شيء عليه، هذا هو الأفضل، وهذا هو الأرجح والأقوى في هذه المسألة، نعم.","link":"https://binbaz.org.sa/fatwas/13629/ما-حكم-من-حج-ولم-يطف-للوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_657/nour_65701.mp3","categories":["الطواف بالبيت"]},{"id":15380,"question":"في آخر أسئلة السائل، صبري، مقيم بأبها يقول: منذ حوالي سنتين، تم الحج لمجموعة من الرجال والنساء، والحمد لله، تم هذا الحج، وتم عمل طواف الوداع، حوالي الساعة الحادية عشرة إلى الساعة الثانية عشرة مساء، على أنه سوف يتم الذهاب إلى جدة في نفس الليلة، ولكن مجموعة ذهبت، والباقي ظلت حتى بعد صلاة الفجر، فهل على هؤلاء شيء يا سماحة الشيخ؟","title":"حكم التأخر في مكة بعد طواف الوداع","answer":"الجواب: ليس عليهم شيء؛ لأن هذا تأخر لا يضر، شيء خفيف، إذا وادع في الليل، وأصبح، أو وادع في آخر النهار، وسافر بعد العشاء كل هذا لا حرج فيه، التأخر اليسير يعفى عنه -إن شاء الله-، نعم.","link":"https://binbaz.org.sa/fatwas/13884/حكم-التاخر-في-مكة-بعد-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56711.mp3","categories":["الطواف بالبيت"]},{"id":16038,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أرجو أن توضحوا لنا توضيحًا كاملًا، وشاملًا: كيف تبدأ عملية السعي بين الصفا والمروة، من أين نبدأ، ومتى ننتهي؟ هل الشوط الواحد يكون بداية من الصفا والوصول للمروة هذا واحد؟ أم البداية من الصفا والرجوع مرةً أخرى للصفا يعد واحدة؟ أفيدونا أفادكم الله.","title":"كيفية السعي بين الصفا والمروة","answer":"الجواب: السعي يبدأ من الصفا، ويختم من المروة، والسعي شوط واحد من الصفاء للمروة هذا واحد، ومن المروة إلى الصفا شوط ثاني، وهكذا، فالمقصود أنها سبعة أشواط، يبدأ الساعي من الصفا، ويختم بالمروة، فإذا بدأ من الصفا، ووصل المروة هذا واحد، وإذا رجع من المروة إلى الصفا هذا اثنين، وإذا رجع من الصفا للمروة هذا ثلاثة .. وهكذا حتى يكمل السبعة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14681/كيفية-السعي-بين-الصفا-والمروة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74810.mp3","categories":["الطواف بالبيت","السعي"]},{"id":16141,"question":"تسأل أختنا وتقول: ما هو طواف السبع التي يطوفها بعض الناس لوالديهم، أو أقاربهم بعد العمرة، هل ورد عن الرسول ﷺ فعلها؟","title":"حكم الطواف عن الغير","answer":"الجواب: لم يرد -فيما نعلم- فعلها عن النبي ﷺ ولا يستحب فعلها عن الموتى، ولا عن غيرهم، يفعل الإنسان عن نفسه، يطوف عن نفسه بالنية، يتعبد بالطواف بالكعبة سبعة أشواط عن نفسه، يتطوع بذلك طواف عبادة، فيه خير عظيم، ومن أسباب محو الذنوب. ويجب على الحاج، والمعتمر أن يطوف بالبيت طواف الإفاضة، طواف الوداع، طواف العمرة، كل هذه الأطواف واجبة: طواف الإفاضة يوم العيد للحاج، أو بعد العيد كذلك، وطواف الوداع عند الخروج، وطواف العمرة، وسعي العمرة، كل هذه الأطواف واجبة، وإذا طاف تطوعًا؛ فهو عبادة عظيمة، له فيها أجر كبير، ومن أسباب تكفير الذنوب، لكن أن يطوف عن والده، أو عن أخيه، أو عن فلان ليس عليه دليل. بعض أهل العلم يرى أنه لا بأس به أن يطوف عن أخيه، أو غيره ولكن ليس عليه دليل، والطواف صلاة، فكما أنه لا يصلي عن أحد لا يطوف عن أحد، هذا هو الأصل، وهذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا، أما العمرة كاملة، أما الحج كاملًا فجائز سماحة الشيخ؟ الشيخ: نعم الحج كاملًا، والعمرة كاملة عن الميت، أو العاجز الكبير في السن، العاجز الذي ما يستطيع الحج لكبر سنه، وهرمه؛ لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14804/حكم-الطواف-عن-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80405.mp3","categories":["الطواف بالبيت"]},{"id":16218,"question":"هذا السائل عكاشة مقيم في المملكة العربية السعودية خميس مشيط يقول: سماحة الشيخ! أديت الحج في عام مضى -والحمد لله- وعملت كل المناسك: من طواف القدوم، والذهاب إلى منى، والمزدلفة، وإلى عرفات، ثم الذهاب إلى الجمرات، وعملت طواف الوداع، وكانت نية الحج الإفراد، ولكنني لم أعمل طواف الإفاضة جهلًا مني، علمًا.. إلا بعدما ذهبت إلى مقر عملي، علمت بذلك، فماذا يلزمني؟","title":"ما يلزم من حج مفردًا ولم يطف للإفاضة؟","answer":"الجواب: يلزمك أن ترجع، وتطوف طواف الإفاضة، والحمد لله، عليك أن ترجع، وتطوف طواف الإفاضة، ولو بعد مدة، وإن كنت جامعت أهلك؛ عليك ذبيحة تذبح في مكة للفقراء بسبب الجماع، وإن كان ما جامعت، ما عندك زوجة، أو ما جامعت؛ فليس عليك شيء، والحمد لله إنما ترجع، وتطوف سبعة أشواط بنية طواف الحج، والحمد لله، وتصلي ركعتين بعد الطواف، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ! هل من توجيه لأولئك المتساهلين في هذه المناسك، وعدم سؤالهم أهل العلم وعدم التفقه في الدين يا شيخ! الشيخ: نعم، الواجب على المؤمن أن يتفقه في دينه، ويتبصر، وإذا حج، أو اعتمر يسأل أهل العلم حتى يؤدي العمرة على وجهها، والحج على وجهه، الله يقول سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] ويروى عنه  أنه قال: ألا سألوا إذ لم يعلموا إنما شفاء العي السؤال ويقول النبي ﷺ: من يرد الله به خيرًا؛ يفقهه في الدين ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة. فالواجب على المؤمن والمؤمنة السؤال من طريق الهاتف، أو من طريق المكاتبة؛ حتى يستفيد، ومن نعم الله على المسلمين الآن وجود برنامج نور على الدرب هذا، إذاعة القرآن فيها علم عظيم، إذاعة القرآن كون المؤمن والمؤمنة يستمعان لإذاعة القرآن، ويستمعان لنور على الدرب، ومحاضرات العلماء في إذاعة القرآن، وما يقع فيها من الخير العظيم هذا علم عظيم.  فأنا أوصي جميع المستمعين أن يستمعوا لإذاعة القرآن، وأن يستمعوا نورًا على الدرب، ويستمعوا ما يكون في إذاعة القرآن من الفوائد من المحاضرات، والكلمات الطيبة، وقراءة القرآن، وفي هذا علم عظيم. وبكل حال الواجب السؤال على الرجل والمرأة، الواجب على كل إنسان أن يسأل عما أشكل عليه في صلاته، في صومه، في حجه، في عمرته، في أمور بيته مع أهله في بيعه وشرائه في غير ذلك، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14885/ما-يلزم-من-حج-مفردا-ولم-يطف-للافاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58012.mp3","categories":["الطواف بالبيت"]},{"id":16372,"question":"السائلة تقول: فتاة حاضت في الطواف، وكانت قد اغتسلت من الحيض في الميقات، ومدة حيضها من أربعة أيام إلى خمسة أيام، فعاد إليها الحيض في يوم الطواف، وهو الخامس، ولكنها أكملت طوافها على أنها اعتبرت ذلك دم استحاضة، أو من شدة الحر، أو أن ذلك نهاية للطهر؟","title":"ما يجب على من طافت وهي حائض؟","answer":"الجواب: عليها أن تعيد الطواف، تستنجي، وتتوضأ وضوء الصلاة؛ لأنه دم فساد، ما دام بعد طهرها من الحيض يكون دم فساد، تستنجي، وتتوضأ وضوء الصلاة، وتعيد الطواف، والأفضل تعيد السعي أيضًا، ثم تقصر، وإن كانت عند أهلها رجعت، نعم. المقدم: إذًا ما يلزمها دم يا شيخ؟  الجواب: لا، إذا كان ما عندها زوج، إن كان عندها زوج؛ فعليها دم، ذبيحة تذبح في مكة للفقراء، وتكمل العمرة، ثم تقضيها أيضًا من ميقاتها مرة أخرى، تحرم من الميقات الذي أحرمت منه... الأولى، فعليها تمام هذه الطواف والسعي والتقصير والذبيحة، ثم ترجع إلى الميقات، وتأتي بعمرة جديدة، كما أفتى بعض الصحابة بذلك، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15071/ما-يجب-على-من-طافت-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58116.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":16591,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد علي رفاعي يسأل ويقول: هل المقيم في مكة المكرمة إذا أتى بعمرة، أو حج هل عليه أن يطوف طواف الوداع؟","title":"حكم طواف الوداع لمن كان مقيمًا بمكة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالمقيم بمكة ليس عليه طواف وداع، لا بعد العمرة، ولا بعد الحج، إنما طواف الوداع على الأفقي الذي ينتهي من حجه، ثم يرجع إلى بلاده، فهذا إذا انتهى من حجه؛ عليه أن يطوف للوداع، أما المعتمر فليس عليه طواف وداع، لكن إذا ودع فهو أفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15318/حكم-طواف-الوداع-لمن-كان-مقيما-بمكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81701.mp3","categories":["الطواف بالبيت"]},{"id":16602,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد علي رفاعي يسأل ويقول: هل المقيم في مكة المكرمة إذا أتى بعمرة، أو حج هل عليه أن يطوف طواف الوداع؟","title":"حكم طواف الوداع لمن كان مقيمًا بمكة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالمقيم بمكة ليس عليه طواف وداع، لا بعد العمرة، ولا بعد الحج، إنما طواف الوداع على الأفقي الذي ينتهي من حجه، ثم يرجع إلى بلاده، فهذا إذا انتهى من حجه؛ عليه أن يطوف للوداع، أما المعتمر فليس عليه طواف وداع، لكن إذا ودع فهو أفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15318/حكم-طواف-الوداع-لمن-كان-مقيما-بمكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81701.mp3","categories":["الطواف بالبيت"]},{"id":16900,"question":"أخيرًا تسأل سماحتكم عن حكم طواف الوداع في العمرة؟","title":"حكم طواف الوداع للمعتمر","answer":"الجواب: ليس بواجب، الوداع واجب في الحج، طواف الوداع واجب في الحج، أما في العمرة فليس بواجب، لكن إن ودع؛ فحسن، إذا أقام مدة، أقام بعد العمرة وقتًا طويلًا، ثم ودع؛ فهذا حسن، لكن ليس هناك دليل واضح على وجوب الوداع للعمرة، إنما هو في الحج، يقول الرسول ﷺ: أمر الناس أن يكون آخر عهدهم بالبيت هذا في الحج، أمر به الناس يعني: الحجاج، كانوا ينصرفون من منى في كل وجه، فقال لهم ﷺ: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت يعني: النفير من منى يوم الثاني عشر، والثالث عشر، يكون النفير من منى، ومن مكة، يكون بعد الوداع. أما العمرة فلم يأمر العمار أن يودعوا، قد اعتمروا مع النبي ﷺ في حجة الوداع، ولم يقل لهم لما فرغوا: لا ينفر أحد منكم حتى يودع، وكانوا يذهبون بالإبل الأماكن البعيدة يرعونها، ولم يؤمروا بالوداع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15658/حكم-طواف-الوداع-للمعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71907.mp3","categories":["الطواف بالبيت"]},{"id":16929,"question":"يسأل أخونا (ع. ف. غ) ويقول: ما حكم من أجل طواف الإفاضة حتى السادس عشر من ذي الحجة، وهو ملتزم بأحكام التحلل الأكبر؟","title":"حكم تأجيل طواف الإفاضة إلى نصف ذي الحجة","answer":"الجواب: لا مانع من تأجيل طواف الإفاضة، ليس له حد محدود، لكن كل ما تقدم في يوم العيد أفضل في يوم الحادي عشر أفضل من الثالث عشر، وهكذا... كل ما تقدم فهو أفضل، وليس له حد محدود، لكن الأفضل البدار به إذا تيسر الأمر، فإذا كان هناك زحمة شديدة، أو مرض، أو نحو هذا، وأخره؛ لا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15721/حكم-تاجيل-طواف-الافاضة-الى-نصف-ذي-الحجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_827/nour_82704.mp3","categories":["الطواف بالبيت"]},{"id":16948,"question":"إذا كان الإنسان يطوف طواف الإفاضة، وأقيمت الصلاة فهل يقطع الطواف؟ أم يواصل؟","title":"ماذا يصنع من أقيمت الصلاة وهو يطوف؟","answer":"الجواب: السنة أن يقطع الطواف، طواف الإفاضة وغيره، إذا أقيمت الصلاة يقطع الطواف، يصلي ثم يتمم الطواف من مكانه إذا قطعه.. هذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15746/ماذا-يصنع-من-اقيمت-الصلاة-وهو-يطوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82810.mp3","categories":["الطواف بالبيت"]},{"id":16952,"question":"يقول: بعض النساء يكشفن وجوههن أثناء الطواف، ما هو توجيهكم لهن، ولأولياء أمورهن؟","title":"حكم كشف المرأة وجهها أثناء الطواف","answer":"الجواب: الواجب عليهن أن يتحجبن بحجابٍ لا يمنعهن من رؤية الطريق؛ حتى يمشين مع الناس، حجاب ليس بنقاب، لا تنتقب مادامت محرمة، وهو شيء يصنع للوجه فيه نقب للعين، أو نقبان للعينين، هذا لا تلبسه المحرمة؛ لأن الرسول نهى عنه -عليه الصلاة والسلام- لكن تلبس غير ذلك من الخمر التي تستر وجهها، ولا تمنعها رؤية الطريق، كما قالت عائشة -رضي الله عنها-: \"كنا مع النبي ﷺ في حجة الوداع، فكنا إذا دنا منا الرجال؛ سدلت إحدانا خمارها على وجهها من رأسها، فإذا بعدوا؛ كشفنا\". فهذا هو الواجب عند الرجال في السعي، أو غيره، تسدل جلبابها، أو خمارها على وجهها، وإن ............. النساء، أو في بيتها؛ تكشف، مادامت محرمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15747/حكم-كشف-المراة-وجهها-اثناء-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82811.mp3","categories":["الطواف بالبيت","قضايا المرأة"]},{"id":16957,"question":"يقول: بعض النساء يكشفن وجوههن أثناء الطواف، ما هو توجيهكم لهن، ولأولياء أمورهن؟","title":"حكم كشف المرأة وجهها أثناء الطواف","answer":"الجواب: الواجب عليهن أن يتحجبن بحجابٍ لا يمنعهن من رؤية الطريق؛ حتى يمشين مع الناس، حجاب ليس بنقاب، لا تنتقب مادامت محرمة، وهو شيء يصنع للوجه فيه نقب للعين، أو نقبان للعينين، هذا لا تلبسه المحرمة؛ لأن الرسول نهى عنه -عليه الصلاة والسلام- لكن تلبس غير ذلك من الخمر التي تستر وجهها، ولا تمنعها رؤية الطريق، كما قالت عائشة -رضي الله عنها-: \"كنا مع النبي ﷺ في حجة الوداع، فكنا إذا دنا منا الرجال؛ سدلت إحدانا خمارها على وجهها من رأسها، فإذا بعدوا؛ كشفنا\". فهذا هو الواجب عند الرجال في السعي، أو غيره، تسدل جلبابها، أو خمارها على وجهها، وإن ............. النساء، أو في بيتها؛ تكشف، مادامت محرمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15747/حكم-كشف-المراة-وجهها-اثناء-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82811.mp3","categories":["الطواف بالبيت","قضايا المرأة"]},{"id":16961,"question":"حدثونا عن السعي بين الصفا والمروة؟ هل هو واجب على كل حاج؟ أم على صنف دون صنف؟","title":"السعي ركن من أركان الحج والعمرة","answer":"الجواب: السعي واجب على جميع الحجاج، بين الصفا والمروة، واجب، ركن من أركان الحج، والعمرة، مع الطواف، في حق المتمتع، والقارن، والمفرد، لكن في حق المتمتع يلزمه سعي ثان للحج، والأول يكون للعمرة، أما القارن، والمفرد فليس عليه إلا سعي واحد، إن سعاه قبل عرفة؛ أجزأه، وإلا سعاه مع طواف الإفاضة، بعد عرفة، إذا كان أفقيًا جاء من الخارج. أما إذا كان من أهل مكة فإن سعيه وطوافه يكون بعد الحج، يؤخر إلى بعد الحج، لا يقدم، أما من جاء من خارج، من جدة، من الرياض، من أبعد منهما، هذا إذا دخل يطوف للقدوم، ويسعى، إذا كان مفردًا، أو قارنًا، ثم عليه طواف للإفاضة بعد الحج، ويجزيه السعي إن سعى قبل الحج، ويلزمه طواف الإفاضة فقط، مع طواف الوداع، أما المتمتع السعي الأول يكون لعمرته، وعليه أن يسعى سعيًا ثانيًا لحجه، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15743/السعي-ركن-من-اركان-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82808.mp3","categories":["الطواف بالبيت","السعي"]},{"id":17115,"question":"من أسئلة هذه السائلة: (س. ن) من جدة تقول: سماحة الشيخ! ما حكم حمل الطفل أثناء الصلاة، أو الطواف وهو لابس حفاظة، وفيها نجاسة، ولكنها لم تتعد الملابس الخارجية، وجزاكم الله خيرًا.","title":"حكم حمل الطفل أثناء الصلاة والطواف","answer":"الجواب: النبي ﷺ صلى بـأمامة بنت زينب، وهو يصلي بالناس -عليه الصلاة والسلام- فإذا حمل الطفل في الصلاة عند الحاجة، أو في الطواف لا حرج، فالنبي ﷺ صلى بـأمامة بنت زينب وهي صغيرة، والطفل قد لا يسلم من خروج شيء منه، فإذا لم يكن هناك شيء ظاهر، ومحفظ فلا بأس، الحمد لله. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15922/حكم-حمل-الطفل-اثناء-الصلاة-والطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58912.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":17155,"question":"هذا سائل للبرنامج يقول: عندما ذهبنا إلى مكة لأداء العمرة كان معنا اثنين من إخوتي، وبعد أن وصلنا إلى مكة ركبنا سيارة أجرة، وذهبنا إلى الحرم لأداء العمرة، والجميع نساء، ولا يوجد معنا محرم، هل عمرتنا صحيحة؟ أم غير صحيحة؟ وهل إخوتي عليهم إثم في ذلك، أم لا؟","title":"حكم طواف المرأة بغير محرم","answer":"الجواب: العمرة صحيحة، ما هو بشرط المحرم أن يبقى معكم في الطواف والسعي، المحرم في السفر بس، إذا وصلكم مكة الحمد لله، فإذا طفتم بدون محرم، وسعيتم بدون محرم لا حرج، المحرم يراد به أن يرافقكم في السفر، أما إذا وصلكم البلد الحمد لله، انتهى الموضوع. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15973/حكم-طواف-المراة-بغير-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58933.mp3","categories":["الطواف بالبيت","قضايا المرأة"]},{"id":17377,"question":"تقول السائلة: هل يجوز الفصل بين طواف العمرة، وإكمال واجباتها، كالخروج إلى الفندق مثلًا -وهو بجوار الحرم- للضرورة كالنوم والأكل؟","title":"حكم الفصل بين طواف العمرة والسعي","answer":"الجواب: لا بأس، لا بأس بتأخير السعي، مثلًا طاف اليوم، وسعى غدًا، أو طاف في أول النهار، وسعى في آخر النهار، لا حرج في ذلك. المقدم: جزاكم الله عنا، وعن المسلمين خير الجزاء، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16227/حكم-الفصل-بين-طواف-العمرة-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59402.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":17446,"question":"سماحة الشيخ! هذا سائل من اليمن يقول: ما حكم من ترك طواف الإفاضة في الحج، وهو ليس متذكر أنه طاف، أم لم يطف؟","title":"حكم من لم يتيقن أنه طاف طواف الإفاضة","answer":"الجواب: الواجب أن يطوف، الطواف ركن لابد منه، من أركان الحج الطواف بالبيت، فلابد أن يتيقن أنه طاف، وإلا لابد أن يطوف، ووقته بعد الانصراف من عرفات، ومن مزدلفة يطوف، يوم العيد، أو في آخر ليلة العيد، أو ثاني العيد، أو ثالث العيد، أو بعد ذلك، لكن في أيام العيد أفضل في يوم العيد وبعده أفضل، وإن طاف بعد أيام العيد؛ فلا بأس، لكن لابد من طواف، قال -جل وعلا-: ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ [الحج:29] هذا طواف الإفاضة لابد منه، ركن لا يتم الحج إلا به، ولو بعد شهر، أو شهرين، متى ذكر يطوف، ولو في محرم، ولو في صفر، وإذا كان خارج مكة؛ يلزمه العود، يرجع إلى مكة، ويطوف بنية الحج، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16314/حكم-من-لم-يتيقن-انه-طاف-طواف-الافاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77202.mp3","categories":["الطواف بالبيت"]},{"id":17652,"question":"هل طواف القدوم واجب أم سنة؟ وهل هناك دليل على أن الحاج الواقف بعرفة ليس عليه صيام في ذلك اليوم؟","title":"حكم طواف القدوم وصيام عرفة للحاج","answer":"الجواب: طواف القدوم سنة، النبي ﷺ لما قدم طاف ثم سعى، فلو أن إنسانًا جاء مصيف وقصد مكة قصد الحج قصد عرفة ولا طاف القدوم؛ فلا حرج يطوف بعدين، لكن لو قدم قبل ذلك قصد الكعبة وطاف وسعى، ثم توجه إلى عرفة يكون هذا أفضل، وإن كان عنده سعة، طاف وسعى وقصر وحل جعلها عمرة، ثم يحرم بالحج يوم الثامن يكون متمتع هذا أفضل أيضًا.\nالمقدم: هل طواف القدوم واجب أم سنة؟ وهل هناك دليل على أن الحاج الواقف بعرفة ليس عليه صيام في ذلك اليوم؟\nالجواب: نعم الواقف بعرفة لا يصوم، النبي وقف مفطرًا عليه الصلاة والسلام، ونهى عن صوم عرفة بعرفة، فالحاج لا يصوم يوم عرفة، إنما يصوم غير الحاج، وإذا كان عليه صيام يصوم قبل عرفة أو بعد عرفة. نعم.","link":"https://binbaz.org.sa/fatwas/16581/حكم-طواف-القدوم-وصيام-عرفة-للحاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59424.mp3","categories":["الطواف بالبيت","الوقوف بعرفة"]},{"id":17685,"question":"سماحة الشيخ! يسأل عن طواف الوداع هل هو واجب؟ ولماذا سمي بطواف الوداع؟ وهل الحائض والنفساء لهما طواف وداع؟","title":"حكم طواف الوداع وخاصة للحائض والنفساء","answer":"الجواب: طواف الوداع واجب في حق الحجاج عند الخروج من مكة إلى بلادهم؛ سمي وداعًا لأنه آخر شيء؛ لأنه يطوف عند السفر كأنه يودع البيت بذلك كما يودع الإنسان أقاربه عند السفر، فإذا أراد السفر من مكة؛ فإنه يودع البيت يطوف طواف سبعة أشواط بالبيت عند السفر إلى بلاده، هذا خاص بالحجاج. أما العمرة فلا يجب لها وداع، لكن لو طاف لا بأس ولكن لا يجب، والحائض ليس عليها وداع والنفساء ليس عليها وداع يقول ابن عباس: «أمر الناس أن يكون آخر عهدهم بالبيت إلا أنه خفف عن المرأة الحائض» وهكذا النفساء ليس عليهما وداع. نعم.","link":"https://binbaz.org.sa/fatwas/16624/حكم-طواف-الوداع-وخاصة-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59514.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":17765,"question":"هذا سائل للبرنامج أبو عبد الله الشمري من الرياض له مجموعة من الأسئلة يقول سماحة الشيخ: بعد الطواف والانتهاء منه والصلاة والذهاب إلى ماء زمزم ذهبت مباشرة إلى المسعى ولم أرجع إلى الحجر الأسود لعدم علمي بذلك فهل في هذا شيء؟","title":"هل يجب استلام الحجر الأسود للمعتمر؟","answer":"الجواب: ليس في هذا حرج، المرور على الحجر الأسود مستحب وليس بلازم، فإذا طاف وذهب إلى المسعى ولم يمر على الحجر فلا بأس لاسيما والغالب أنه يكون ..... المطاف وفيه مشقة.\nفالحاصل أنه لا حرج إذا لم يمر على الحجر ولو كان فيه سعة، إذا ذهب للسعي رأسًا فلا حرج في ذلك؛ لأنه مستحب فقط. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16761/هل-يجب-استلام-الحجر-الاسود-للمعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77805.mp3","categories":["الطواف بالبيت"]},{"id":17779,"question":"من ضمن أسئلة هذا السائل يقول سماحة الشيخ: ما حكم شراء بعض الأكل والأغراض والهدايا بعد طواف الوداع وقبل الخروج من مكة؟","title":"حكم التسوق بعد طواف الوداع","answer":"الجواب: لا حرج في ذلك إذا اشترى حاجات هدية أو طعام السفر أو ما أشبه ذلك لا حرج في ذلك والحمد لله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16767/حكم-التسوق-بعد-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77808.mp3","categories":["الطواف بالبيت"]},{"id":17799,"question":"هذه سائلة للبرنامج تقول سماحة الشيخ: تذكر بأنها امرأة حجت منذ أعوام، وبعد أيام وأثناء الطواف جاءتها الدورة، ولم تخبر أحدًا حتى زوجها، تقول: هي امرأة كبيرة في السن، وتود من سماحتكم الإفادة، ماذا تعمل؟","title":"حكم من حاضت أثناء الطواف ولم تخبر أحدًا","answer":"الجواب: إذا كان الطواف نافلة فلا شيء عليها، فإن كان الطواف فريضة: طواف عمرة أو حج فريضة طواف الإفاضة طواف العمرة طواف الوداع، هذا عليها إن كان طواف الوداع عليها ذبيحة تذبح بدل طواف الوداع في مكة للفقراء، توكل من يذبحها للفقراء في مكة، وإن كان طواف الإفاضة أو طواف العمرة، لابد من الرجوع، فإن كانت قد رجعت وأدت حجة أخرى أو عمرة أخرى كفى والحمد لله، فإن كان ما أدت عمرة ولا أدت حجًا؛ فعليها أن ترجع حتى تؤدي العمرة التي حاضت .. طوافها، أو تطوف للحج الذي حاضت في طواف الحج، ولو مضى عليها سنون، هي لا تزال عليها الطواف، ترجع إلى مكة وتطوف الطواف اللي عليها طواف الحج، وإن كان عمرة عليها أن تأتي تطوف طواف العمرة وتسعى وتقصر، ولو مضى عليها سنون. وإن كانت أتاها زوجها لها زوج؛ عليها تذبح ذبيحة في مكة للفقراء، في طواف العمرة، وهكذا إذا كان في طواف الحج، وإن كانت في طواف العمرة؛ عليها أن تعيد عمرة، تكمل العمرة هذه ثم تأتي بعمرة جديدة من الميقات التي أحرمت في العمرة الأولى منه. نعم.","link":"https://binbaz.org.sa/fatwas/16780/حكم-من-حاضت-اثناء-الطواف-ولم-تخبر-احدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59710.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":17897,"question":"سؤال من المستمع سعيد سعد الشهراني يقول فيه: لقد حجيت هذا العام وعندما أردت البدء في تأدية طواف الإفاضة تذكرت أنني على غير وضوء ولم أستطع الذهاب للوضوء لوجودي مع عائلة ولكثرة الزحام فاستمريت في إكمال الأشواط ولما انتهيت سألت أحد الإخوان عن عملي هذا فقال: لا يجوز الطواف من غير طهارة ولكن عليك أن تنوي طواف الإفاضة مع طواف الوادع ففعلت ذلك، هل ما فعلته صحيحًا؟","title":"حكم الطواف بنية الإفاضة والوداع","answer":"الجواب: نعم. الطواف الأول غير صحيح، وطوافك الأخير بنية الوداع والإفاضة يجزئ والحمد لله عند ....... نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16923/حكم-الطواف-بنية-الافاضة-والوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84605.mp3","categories":["الطواف بالبيت"]},{"id":17926,"question":"المستمع صابر محمد من جمهورية مصر العربية يقول: أثناء طوافي طواف الوداع في الحج انتقض وضوئي فهل تأثر الحج؟","title":"حكم من انتقض وضوؤه أثناء طواف الوداع","answer":"الجواب: يتأثر الطواف فقط، الطواف يفسد بذلك كالصلاة، إذا أحدث الإنسان في الطواف فسد الطواف كالصلاة، فعليك إعادته، فإن لم تعده فعليك دم يذبح في مكة للفقراء جبرًا للحج، الحج يكون ناقصًا حتى تأتي بالطواف أو تجبره بدم، والدم ذبيحة مثل ذبيحة هدي الأضحية يعني: جذع ضأن أو ثني معز أو سبع بدنة أو سبع بقرة. نعم.\nالمقدم: جزاكم الله خيرًا. إن كان متزوجًا وأتى أهله قبل التسديد هذا سماحة الشيخ؟\nالشيخ: ما يضر، ما يتعلق به، الحل يتعلق بالرمي، والطواف طواف الإفاضة، والسعي. ما له تعلق بطواف الوداع. نعم.\nالمقدم: جزاكم الله خيرًا. كأن هناك فرقًا بين الأركان والواجبات والسنن؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16973/حكم-من-انتقض-وضووه-اثناء-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84713.mp3","categories":["الطواف بالبيت"]},{"id":17934,"question":"المستمع صابر محمد من جمهورية مصر العربية يقول: أثناء طوافي طواف الوداع في الحج انتقض وضوئي فهل تأثر الحج؟","title":"حكم من انتقض وضوؤه أثناء طواف الوداع","answer":"الجواب: يتأثر الطواف فقط، الطواف يفسد بذلك كالصلاة، إذا أحدث الإنسان في الطواف فسد الطواف كالصلاة، فعليك إعادته، فإن لم تعده فعليك دم يذبح في مكة للفقراء جبرًا للحج، الحج يكون ناقصًا حتى تأتي بالطواف أو تجبره بدم، والدم ذبيحة مثل ذبيحة هدي الأضحية يعني: جذع ضأن أو ثني معز أو سبع بدنة أو سبع بقرة. نعم.\nالمقدم: جزاكم الله خيرًا. إن كان متزوجًا وأتى أهله قبل التسديد هذا سماحة الشيخ؟\nالشيخ: ما يضر، ما يتعلق به، الحل يتعلق بالرمي، والطواف طواف الإفاضة، والسعي. ما له تعلق بطواف الوداع. نعم.\nالمقدم: جزاكم الله خيرًا. كأن هناك فرقًا بين الأركان والواجبات والسنن؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16973/حكم-من-انتقض-وضووه-اثناء-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84713.mp3","categories":["الطواف بالبيت"]},{"id":18677,"question":"ما حكم من يرتدي ملابس الإحرام، ويطوف حول الكعبة في الحج أو العمرة، وهو محتلم ناسيًا أو متكاسلًا، هل عليه فدية أو ماذا؟","title":"حكم من اعتمر أو حج وهو محتلم","answer":"الجواب: عليه التوبة إلى الله  وعليه أن يغتسل، ثم يعيد الطواف إن كان فرضًا، وإن كان الطواف نافلة فلا شيء عليه إلا التوبة والاستغفار؛ لأنه متلاعب، الطواف صلاة، فلا يطوف إلا وهو متطهر من الحدثين الأكبر والأصغر، فلا يطوف وهو جنب، ولا تطوف الحائض ولا النفساء، بل على الجميع أن ينتظروا حتى تحصل الطهارة بالغسل. وهكذا من عليه حدث أصغر لا يطوف حتى يتوضأ، وإذا طاف على جنابته أو على حدثه عامدًا؛ فهو آثم يستحق أن يؤدب إذا عرفه ولي الأمر، وعليه التوبة إلى الله . أما إن كان ناسيًا فلا شيء عليه، لكن يعيد الطواف إذا كان واجبًا ولا إثم عليه، لكن يعيده إذا كان طواف عمرة، أو طواف الحج طواف الإفاضة أو طواف الوداع يعيده، إذا تذكر أنه ليس على طهارة يعيد الطواف، أما إذا كان نافلة فالأمر واسع، ليس عليه إعادة، لكن ليس له أن يطوف ولو نافلة وهو على حدث؛ لأن الطواف صلاة، إلا أن الله أباح فيه الكلام، والنبي لما أراد أن يطوف توضأ -عليه الصلاة والسلام-. المقدم: لو قدر أنه ارتكب شيئًا من المحظورات التي تحظر على مثله، فبم تنصحونه شيخ عبد العزيز ؟ الشيخ: إذا كان ما أحرم فلا شيء عليه، أما إذا كان أحرم ولكنه تعاطى بعض المحرمات، مثل: تطيب عمدًا، أو قص أظافره عمدًا؛ عليه الفدية التي بينها أهل العلم، وجاء بها الحديث الشريف من حديث كعب بن عجرة إذا تعمد ذلك فعليه إطعام ستة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو غيره، أو صيام ثلاثة أيام، أو ذبح شاة، والذبح والإطعام يكون لمساكين الحرم، كما لو غطى رأسه أو لبس المخيط كذلك في حال إحرامه، فالذي يقص أظفاره أو يتطيب عامدًا، أو يحلق شعره عامدًا؛ يكون عليه الفدية، أما إذا كان ناسيًا فلا شيء عليه. نعم، حتى إذا كان جاهلًا لا شيء عليه، نعم. المقدم: وإذا أتى أهله شيخ عبد العزيز ؟ الشيخ: هذا فيه خلاف إذا كان ناسيًا، وأما إذا كان عامدًا فهذا تبطل عمرته، ويبطل حجه، إذا كان قبل التحلل الأول، قبل يعني أن يرمي ويحلق ويقصر ويطوف، إما قبل عرفة أو بعد عرفة، لكن قبل أن يتحلل التحلل الأول، يبطل حجه، ويكمل عمره يجعلها عمرة، عمرة فاسدة، وعليه أن يقضيه في المستقبل، بدل الحج الذي أفسده، وعليه بدنة تذبح في مكة للفقراء، وفي العمرة إذا كان أفسد العمرة جامع قبل أن يطوف ويسعى؛ يكون عليه شاة، وتفسد عمرته، فيكملها ثم يقضيها من الميقات الذي أحرم منه في الأولى، يقضي هذه الفاسدة التي جامع فيها، ثم عليه أن يأتي بعمرة جديدة من الميقات الذي أحرم منه بدلًا من هذه العمرة التي أفسدها، نسأل الله العافية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/17830/حكم-من-اعتمر-او-حج-وهو-محتلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87311.mp3","categories":["الطواف بالبيت"]},{"id":18724,"question":"من اعتمر ولم يودع هل عليه شيء؟","title":"حكم العمرة دون طواف الوداع","answer":"الجواب: الوداع في الصحيح ليس واجبًا في حق المعتمر، إنما هو واجب في حق الحاج؛ لقوله ﷺ للحجاج: لا ينفرن أحد منكم حتى يكون آخر عهده بالبيت ولم يقل للمعتمرين شيئًا من ذلك؛ ولأن العمرة مبناها على التخفيف والتيسير؛ لأنها مشروعة في كل وقت، فلا يلزم فيها طواف الوداع. لكن لو ودع كان أفضل، وإلا فليس بلازم، هذا هو الصحيح.","link":"https://binbaz.org.sa/fatwas/17853/حكم-العمرة-دون-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_874/nour_87405.mp3","categories":["الطواف بالبيت"]},{"id":18768,"question":"على بركة الله نبدأ هذا اللقاء برسالة وصلت من مستمع للبرنامج يقول في هذا  هل تجوز الاستراحة بين أشواط الطواف في الحج أو العمرة، أم يجب التتابع؟ وما الحكم فيمن يفصل بين الأشواط من شدة التعب والزحام سماحة الشيخ؟","title":"حكم الاستراحة بين أشواط الطواف","answer":"الجواب:   بسم الله الرحمن الرحيم.    الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: \nفالسنة في الطواف الموالاة، يجب أن يوالي بين الأشواط، لكن الاستراحة القليلة التي لا تضر ولا تعتبر طويلة عرفًا لا تمنع، وكذلك لو أقيمت الصلاة وهو يطوف فإنه يصلي ثم يكمل الطواف من المحل الذي قطعه منه، وهكذا السعي.    أما إذا طال الفصل فإنه يعيده من أوله؛ لأن الموالاة شرط إلا القطع اليسير الذي يعتبر ليس بطويل، أو لعذر شرعي كإقامة الصلاة. \nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17895/حكم-الاستراحة-بين-اشواط-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79101.mp3","categories":["الطواف بالبيت"]},{"id":18780,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من جدة، وباعثها مستمع رمز إلى اسمه بالحروف: (أ. م. أ. ط) أخونا يقول: أحرمت بالحج مفردًا من مكان إقامتي في جدة، ليلة الثامن من ذي الحجة، وطفت طواف القدوم قبل يوم التروية، ثم سعيت سعي الحج بعد صلاة فجر يوم التروية، فهل الترتيب الزمني الذي أديت فيه المناسك المذكورة صحيح؟جزاكم الله خيرًا.","title":"حكم الفصل بين طواف القدوم والسعي في الحج للمفرد","answer":"الجواب: لا حرج في ذلك صحيح، والحمد لله، لكن لو سعيت مع الطواف مبادرة فهو أفضل، ولكن تأخيره كونك طفت في ليلة الثامن، أو في اليوم التاسع، ثم طفت في الليلة الثامنة أو في يوم الثامن، ثم سعيت في صباح يوم التاسع أو في يوم التروية لا بأس. المقصود: الفصل بين السعي وبين الطواف لا يضر، لكن كون السعي يلي الطواف هذا هو الأفضل، فإذا طاف الإنسان في اليوم الثامن، أو في السابع، ثم سعى بعد ذلك في اليوم الذي بعده، أو في الليلة، فلا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17944/حكم-الفصل-بين-طواف-القدوم-والسعي-في-الحج-للمفرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73602.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":18930,"question":"سائل للبرنامج يقول في سؤاله هذا يا فضيلة الشيخ: سماحة الشيخ، كيف يكون التكبير على الصفا والمروة؟","title":"كيفية التكبير على الصفا والمروة","answer":"الجواب: كان النبي ﷺ إذا صعد الصفا كبر عليها، وذكر الله ثلاثًا، ودعا ثلاثًا، وكرر، يقول: لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، يحيي ويميت وهو على كل شيء قدير، لا إله إلا الله وحده أنجز وعده، ونصر عبده، وهزم الأحزاب وحده، ويكرر ذلك مع التكبير ثلاث مرات، مع الدعاء على الصفا والمروة، هذا هو الأفضل. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18067/كيفية-التكبير-على-الصفا-والمروة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88205.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":19153,"question":"في بداية هذه الحلقة نعود إلى رسالة أحد الإخوة المستمعين يقول: صالح أحمد عالي الغامدي أخونا عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة بقي له عدد آخر من الأسئلة، فيقول في أحد أسئلته: حججت العام الماضي والحمد لله، وعندما أخذت طواف الوداع قبل المغرب بساعة بعد صلاة العشاء خرجت ولظرف غير مقصود تأخرت، فهل يلزمني شيء؟ أرجو التوجيه جزاكم الله خيرًا.الشيخ: أعد.المقدم: يقول: حججت العام الماضي والحمد لله، وعندما أخذت طواف الوداع قبل المغرب بساعة بعد صلاة العشاء تأخرت لظرف غير مقصود، فهل علي شيء؟","title":"حكم من طاف طواف الوداع ثم مكث في مكة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال عن الحجاج: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت خرجه مسلم في صحيحه، وقال ابن عباس رضي الله عنهما: «أمر الناس أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض» متفق عليه. ومعنى: أمر الناس يعني: أمرهم النبي عليه الصلاة والسلام. فلا يجوز للحاج أن يخرج من مكة إلا بعد طواف الوداع، إذا أراد السفر إلى بلاده، أو إلى بلاد أخرى، وإذا ودع قبل الغروب ثم جلس بعد العشاء لحاجة أو لسماع الدرس أو ليصلي العشاء فلا حرج في ذلك، المدة اليسيرة يعفى عنها. قد طاف النبي ﷺ في حجة الوداع، طواف الوداع في آخر الليل، ثم صلى بالناس الفجر، ثم سافر بعد ذلك عليه الصلاة والسلام. فالأمر اليسير يعفى عنه، فإذا كنت سافرت بعد العشاء فلا حرج في ذلك، أما إن كنت أقمت إقامة طويلة أصبحت فينبغي لك أن تعيد طواف الوداع، فإن كنت لم تعد طواف الوداع فلا حرج عليك إن شاء الله؛ لأن المدة وإن كانت فيها بعض الطول لكنها مغتفرة إن شاء الله من أجل الجهل بواجب المبادرة والمسارعة إلى الخروج بعد طواف الوداع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18322/حكم-من-طاف-طواف-الوداع-ثم-مكث-في-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93201.mp3","categories":["الطواف بالبيت"]},{"id":19592,"question":"هل الحائض والنفساء عليهما طواف الإفاضة؟","title":"حكم طواف الإفاضة للحائض والنفساء","answer":"الجواب: عليهما طواف الإفاضة نعم بعد الطهر، إذا جاءها الحيض قبل يوم العيد عليهما أن تمسكا حتى تطهرا، فإذا طهرتا طافتا للإفاضة ولو بعد أيام منى، ولو في الخامس عشر والرابع عشر والسادس عشر، عليهما الإمساك عن الطواف حتى تطهرا فإذا طهرتا اغتسلتا وطافتا، طواف الإفاضة لابد منه ركن، طواف الإفاضة ركن الحج لابد منه.","link":"https://binbaz.org.sa/fatwas/18853/حكم-طواف-الافاضة-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94909.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":19710,"question":"السعي يُشترط له طهارة؟","title":"هل تشترط الطهارة للسعي بين الصفا والمروة؟","answer":"لا، الطواف فقط.","link":"https://binbaz.org.sa/fatwas/27028/هل-تشترط-الطهارة-للسعي-بين-الصفا-والمروة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D9%87%D9%84%20%D8%AA%D8%B4%D8%AA%D8%B1%D8%B7%20%D8%A7%D9%84%D8%B7%D9%87%D8%A7%D8%B1%D8%A9%20%D9%84%D9%84%D8%B3%D8%B9%D9%8A%20%D8%A8%D9%8A%D9%86%20%D8%A7%D9%84%D8%B5%D9%81%D8%A7%20%D9%88%D8%A7%D9%84%D9%85%D8%B1%D9%88%D8%A9%D8%9F.mp3","categories":["الطواف بالبيت","السعي"]}]
